  ui_story_5033_50330101_33_dialog_content = "เหยื่อทั้งหมดได้รับบาดเจ็บเล็กน้อยก่อนจะทรุดตัวลงอย่างกะทันหันด้วยเหตุผลที่ยังไม่ทราบแน่ชัด",
  ui_story_5033_50330101_34_dialog_content = "บาดแผลมักจะเล็กเกินกว่าจะมองเห็นได้ด้วยตาเปล่าและดูเหมือนไม่เป็นอันตรายถึงชีวิต",
  ui_story_5033_50330101_35_dialog_content = "แต่เมื่อตรวจสอบเหยื่อรายล่าสุดของเราอย่างละเอียดถี่ถ้วนแล้ว ฉันค่อนข้างมั่นใจว่าเป็นบาดแผลจากมีด",
  ui_story_5033_50330101_36_dialog_content = "ผู้กระทำผิดมีฝีมือมาก มีดเข้าอย่างรวดเร็วและแม่นยำ กระแทกเฉพาะจุดที่ถูกต้อง",
  ui_story_5033_50330101_37_dialog_content = "คอแร็กซ์ ฉันให้คุณดำเนินคดีเพื่อนำผู้กระทำผิดมามีชีวิต",
  ui_story_5033_50330101_38_dialog_content = "คุณเป็นหมอ คุณควรรู้ว่าต้องทำอย่างไร",
  ui_story_5033_50330101_39_dialog_content = "... โปรดให้เวลาฉันมากกว่านี้ครับ",
  ui_story_5033_50330101_40_dialog_content = "แผนของคุณคืออะไร?",
