  ui_story_5033_50330101_42_dialog_content = "ดำเนินการอย่างรวดเร็วและด้วยความระมัดระวัง",
  ui_story_5033_50330101_43_dialog_content = "ฉันควรจะ.",
  ui_story_5033_50330101_44_dialog_content = "<color=#e8d9bb>หนึ่งเดือนต่อมาที่งาน Home Goods Convention ใน Umbraton</color>",
  ui_story_5033_50330101_45_dialog_content = "<size=45>พิเศษ พิเศษ!</size>",
  ui_story_5033_50330101_46_dialog_content = "ข่าวอัมบราตัน ออกจากเตา! รับสื่ออร่อยของคุณตอนนี้!",
  ui_story_5033_50330101_47_dialog_content = "(ใครเป็นคนอธิบายหนังสือพิมพ์แบบนั้น?!)",
  ui_story_5033_50330101_48_dialog_content = "อ๊ะ!",
  ui_story_5033_50330101_49_dialog_content = "PlayerName! ช่างเป็นภาพที่หายาก! คุณอยู่คนเดียวใน Umbraton หรือไม่?",
  ui_story_5033_50330101_50_dialog_content = "(ไม่นะ ฉันโดนจับได้!)",
  ui_story_5033_50330101_51_dialog_content = "แล้วจะหยิบสำเนาขึ้นมาได้อย่างไร? คุณไม่อยากพลาดสิ่งนี้เพียงแค่ใน!",
  ui_story_5033_50330101_52_dialog_content = "\"Umbraton ได้รับผลกระทบจาก <color=#FFB400>การสังหารต่อเนื่องลึกลับ</color> ในช่วงไม่กี่สัปดาห์ที่ผ่านมา\"...",
  ui_story_5033_50330101_53_dialog_content = "\"มีผู้ที่เกี่ยวข้องกับ <color=#FFB400>ตลาดมืด</color> เสียชีวิตแล้วในบ้าน\"...",
  ui_story_5033_50330101_54_dialog_content = "\"ผู้เสียหายแสดง <color=#FFB400>สัญญาณการต่อสู้ที่แปลกประหลาด</color> และฆาตกรยังคงอยู่ในวงกว้าง\"...",
  ui_story_5033_50330101_55_dialog_content = "วิธีที่ว่า? คุณได้รับความต้องการที่จะฉกกระดาษตอนนี้หรือไม่?",
  ui_story_5033_50330101_56_dialog_content = "ไม่ ฉันสบายดี! วันนี้ฉันไม่ได้มาซื้อกระดาษ",
  ui_story_5033_50330101_57_dialog_content = "มาเร็ว, PlayerNameคุณอยู่ที่นี่แล้ว คุณต้องซื้ออะไรบางอย่าง!",
  ui_story_5033_50330101_58_dialog_content = "อันที่จริง...",
  ui_story_5033_50330101_59_dialog_content = "<color=#e8d9bb>เมื่อหลายวันก่อนใน Cloud Gardens</color>",
  ui_story_5033_50330101_60_dialog_content = "(ในที่สุด Cloud Gardens ก็เรียบร้อยมากขึ้นแล้ว)",
  ui_story_5033_50330101_61_dialog_content = "(ฉันทำงานในโครงการมานานแล้ว ฉันสมควรที่จะได้พัก)",
  ui_story_5033_50330101_62_dialog_content = "แต่นี่ยังไม่ดีพอ",
  ui_story_5033_50330101_63_dialog_content = "อะไร?! คุณรู้ได้อย่างไรว่าฉันเป็นอะไร -",
  ui_story_5033_50330101_64_dialog_content = "ใบหน้าของคุณบอกฉันว่าคุณกำลังจะยอมแพ้ PlayerName.",
  ui_story_5033_50330101_65_dialog_content = "เรามีของตกแต่งพื้นฐานไว้แล้ว แต่ก็ยังว่างเปล่าและเรียบง่ายเกินไป",
  ui_story_5033_50330101_66_dialog_content = "เอาไป!",
  ui_story_5033_50330101_67_dialog_content = "โหหหหหหหหหหหหหหหหหหหหหหหหหหหหหหห นี่กองอะไร",
  ui_story_5033_50330101_68_dialog_content = "แคตตาล็อกผู้แสดงสินค้าสำหรับการประชุม Umbraton Home Goods Convention ประจำปี!",
  ui_story_5033_50330101_69_dialog_content = "คุณไม่ต้องการที่จะรู้ว่าฉันต้องผ่านการเชื่อมต่อกี่ครั้งเพื่อรวบรวมพวกเขาทั้งหมด!",
  ui_story_5033_50330101_70_dialog_content = "... คุณวางแผนเรื่องนี้มาโดยตลอดใช่ไหม",
  ui_story_5033_50330101_71_dialog_content = "อย่าอาศัยรายละเอียดเล็ก ๆ เลย!",
  ui_story_5033_50330101_72_dialog_content = "อย่างไรก็ตาม การปรับปรุงใหม่ไม่ใช่เรื่องเล็กน้อย ที่นี่คือบ้านของคุณ",
  ui_story_5033_50330101_73_dialog_content = "ตอนนี้ลองนึกภาพว่าในที่สุดจะได้กลับบ้านและพักผ่อนหลังจากการเดินทางอันยาวนาน คุณเห็นอะไร?",
  ui_story_5033_50330101_74_dialog_content = "โอ้ ฉันอยากนอนขดตัวบนเก้าอี้นวม",
  ui_story_5033_50330101_75_dialog_content = "คุณรู้สึกอย่างไรที่ผู้เอนกายรู้สึกอย่างไร ทำจากผ้าซาตินนุ่มหรือหนังเย็น?",
  ui_story_5033_50330101_76_dialog_content = "หนังสำหรับเอนกายแน่นอน! และมันจะดูเย็นลง",
  ui_story_5033_50330101_77_dialog_content = "ดู? เครื่องตกแต่งและการตกแต่งไม่เพียงแต่ช่วยให้เกิดความพึงพอใจ แต่ยังเป็นวิธีที่ดีในการอวดสไตล์ของคุณด้วย!",
  ui_story_5033_50330101_78_dialog_content = "ทุกสิ่งที่เข้ามาในบ้านควรเลือกอย่างระมัดระวัง",
  ui_story_5033_50330101_79_dialog_content = "WW-เดี๋ยวก่อน!",
