  ui_story_5033_50330101_81_dialog_content = "ไม่ใช่ว่าคุณมีอะไรจะทำในอีกไม่กี่วันข้างหน้านี้!",
  ui_story_5033_50330101_82_dialog_content = "และคุณต้องจัดการทุกขั้นตอนในการปรับปรุงเป็นการส่วนตัวอยู่ดี",
