  ui_story_5033_50330101_84_dialog_content = "เราต้องเตรียมพร้อม การช็อปปิ้งคือสงคราม รู้ไหม!",
  ui_story_5033_50330101_85_dialog_content = "จดจำวัสดุ การตกแต่ง และสไตล์สำหรับสินค้าทุกชิ้น",
  ui_story_5033_50330101_86_dialog_content = "อ่านและประเมินทุกอย่างอย่างละเอียดก่อนทำรายการสุดท้าย ดังนั้นคุณจะพร้อมสำหรับการประชุม!",
  ui_story_5033_50330101_87_dialog_content = "ครับท่านรองเสนาบดี!",
  ui_story_5033_50330101_88_dialog_content = "เช่นนั้น เราดูโบรชัวร์เป็นเวลาสี่วันเต็มโดยแทบไม่ได้นอนเลย",
