  ui_story_5033_50330101_91_dialog_content = "ฉันคิดว่าทั้งหมดที่ฉันต้องทำคือทำตาม Vice รอบการประชุม",
  ui_story_5033_50330101_92_dialog_content = "แต่ว่า...",
  ui_story_5033_50330101_93_dialog_content = "<color=#e8d9bb>ก่อนออกเดินทาง</color>",
  ui_story_5033_50330101_94_dialog_content = "โอ้ พระเจ้า ฉันขอโทษจริงๆ PlayerName!!!",
  ui_story_5033_50330101_95_dialog_content = "ฉันเพิ่งได้รับงานด่วนจากผู้บัญชาการฮิอิโระ...",
  ui_story_5033_50330101_96_dialog_content = "ดังนั้นฉันจึงมาด้วยตัวเองโดยไม่มีเงื่อนงำหรืองบประมาณในใจ",
  ui_story_5033_50330101_97_dialog_content = "น่าเสียดายแต่ PlayerName. แบบแผน <color=#FFB400>ยกเลิก</color> ในนาทีที่แล้ว",
  ui_story_5033_50330101_98_dialog_content = "อะไรนะ!",
