  ui_story_5033_50330101_109_dialog_content = "สีนี้สวยมาก",
  ui_story_5033_50330101_110_dialog_content = "โปสการ์ดสามารถเป็นของตกแต่งบ้านได้เช่นกัน",
  ui_story_5033_50330101_111_dialog_content = "รู้สึกอิสระที่จะมองผ่านพวกเขา พวกเขาเน้นเมืองและสถานที่ต่าง ๆ รอบ Umbraton",
  ui_story_5033_50330101_112_dialog_content = "(อืม อย่างน้อยฉันก็พอจะซื้อโปสการ์ดได้นะ...)",
