  ui_story_5033_50330101_120_dialog_content = "<color=#e8d9bb>ฟึบ!</color>",
  ui_story_5033_50330101_121_dialog_content = "โปสการ์ดของฉัน!!!",
  ui_story_5033_50330101_122_dialog_content = "เจส...หายไปไหน?",
  ui_story_5033_50330101_123_dialog_content = "หยุดตรงนั้นคุณสองคน!",
  ui_story_5033_50330101_124_dialog_content = "*แฮ่ก แฮ่ก แฮ่ก*",
  ui_story_5033_50330101_125_dialog_content = "...",
  ui_story_5033_50330101_126_dialog_content = "(ผู้ชายหน้าตาประหลาดอะไรอย่างนี้ ลุคนี้เป็นแฟชั่นล่าสุดใน Umbraton หรือเปล่า?)",
  ui_story_5033_50330101_127_dialog_content = "(เดี๋ยวก่อน ทำไมเขาดูคุ้นๆ)",
  ui_story_5033_50330101_128_dialog_content = "ฉันไม่รู้ว่าคุณหยุดเราทำไม...",
  ui_story_5033_50330101_129_dialog_content = "แต่ยังไงก็ขอบคุณ PlayerName.",
  ui_story_5033_50330101_130_dialog_content = "ก็ตั้งแต่ชายคนนั้นถูกจับได้...",
  ui_story_5033_50330101_131_dialog_content = "ฉันสามารถเอามันจากที่นี่",
  ui_story_5033_50330101_132_dialog_content = "คอแร็กซ์?! ทำไมแต่งตัวแบบนี้",
  ui_story_5033_50330101_133_dialog_content = "ได้โปรดเถอะ ฉันขอร้อง ฉันไม่เกี่ยวอะไรด้วย!",
