  ui_story_5033_50330101_135_dialog_content = "ฉันจะพาคุณตรงไปที่ Shadowlord",
  ui_story_5033_50330101_136_dialog_content = "แต่ฉันไม่รู้อะไรเลย!",
  ui_story_5033_50330101_137_dialog_content = "งั้นเหรอ",
  ui_story_5033_50330101_138_dialog_content = "<color=#e8d9bb>แกล๊ง!</color>",
  ui_story_5033_50330101_139_dialog_content = "ไม่ อย่า! โอเค ฉันจะพูด วางมันลง!",
  ui_story_5033_50330101_140_dialog_content = "ฉันทำธุรกิจกับพวกเขาแน่ แต่ฉันไม่ได้ฆ่าใคร!",
  ui_story_5033_50330101_141_dialog_content = "พวกเขาทั้งหมดได้เริ่มต้นทำธุรกิจที่ร่มรื่นและใช้เงินของพวกเขาเพื่อใช้ประโยชน์จากจุดอ่อนของอาชญากรของ Umbraton!",
  ui_story_5033_50330101_142_dialog_content = "นั่นเป็นข่าวเก่าทั้งหมด มีอะไรอีกไหม",
  ui_story_5033_50330101_143_dialog_content = "ล-แล้วก็...",
  ui_story_5033_50330101_144_dialog_content = "ก่อนตาย ทุกคนมาเยี่ยม <color=#FFB400>ความอิ่มเอิบ</color>!",
  ui_story_5033_50330101_145_dialog_content = "สมมุติว่า <color=#FFB400>ยมทูต</color>ปรากฏขึ้นที่นั่น!",
  ui_story_5033_50330101_146_dialog_content = "มัจจุราช?",
  ui_story_5033_50330101_147_dialog_content = "ต-ใช่แล้ว... ใครก็ตามที่ไม่เชื่อฟังมัจจุราช...",
  ui_story_5033_50330101_148_dialog_content = "มันฉวยชีวิตของพวกเขาในอีกไม่กี่วันต่อมา!",
  ui_story_5033_50330101_149_dialog_content = "พวกเขาต้องตายเพราะมัจจุราชที่ไม่มีใครพูดถึง!",
  ui_story_5033_50330101_150_dialog_content = "แต่ไม่ใช่ Euphoria แล้ว...",
  ui_story_5033_50330101_151_dialog_content = "คุณควรจะพูดความจริงดีกว่า",
  ui_story_5033_50330101_152_dialog_content = "ฉัน ฉันสาบาน!",
  ui_story_5033_50330101_153_dialog_content = "...",
  ui_story_5033_50330101_154_option_content = "บูสต์พลัง!",
  ui_story_5033_50330101_155_dialog_content = "เขากำลังพูดความจริง คอแร็กซ์",
  ui_story_5033_50330101_156_dialog_content = "ฉันไม่รู้สึกอะไรนอกจากความเครียดและความกลัว",
  ui_story_5033_50330101_157_dialog_content = "ขอบคุณสำหรับความช่วยเหลือครั้งใหญ่ PlayerName.",
  ui_story_5033_50330101_158_dialog_content = "ว-คุณกำลังทำอะไรอยู่ตอนนี้!",
  ui_story_5033_50330101_159_dialog_content = "ฉันอยากให้คุณไปยูโฟเรียกับฉัน",
  ui_story_5033_50330101_160_dialog_content = "ตอนนี้?!",
  ui_story_5033_50330101_161_dialog_content = "ฉันอยู่ภายใต้คำสั่งของ Shadowlord ให้ไปที่นั่นและตรวจสอบการสังหารต่อเนื่องใน Umbraton",
  ui_story_5033_50330101_162_dialog_content = "ฉันจะอธิบายส่วนที่เหลือระหว่างทาง",
  ui_story_5033_50330101_163_dialog_content = "เพื่อหลีกเลี่ยงไม่ให้ยักษ์ใหญ่ของคุณดึงความสนใจโดยไม่จำเป็น เราจะขึ้นเรือเหาะ",
  ui_story_5033_50330101_164_dialog_content = "พรุ่งนี้เช้าเจอกันที่ Shuttle Hub",
  ui_story_5033_50330101_165_dialog_content = "ฉันหมายถึงว่า ฉันอยากดู Euphoria แต่...",
  ui_story_5033_50330101_166_dialog_content = "แล้วเจอกันพรุ่งนี้",
  ui_story_5033_50330101_167_dialog_content = "รอให้ฉันเสร็จ!",
  ui_story_5033_50330101_168_dialog_content = "อย่างน้อยคุณให้ฉันคิดเกี่ยวกับมัน...",
  ui_story_5033_50330201_1_dialog_content = "<color=#e8d9bb>ศูนย์รับส่ง</color>",
  ui_story_5033_50330201_2_dialog_content = "(เอาล่ะ ฉันมาถึงแล้ว ฉันมาถึงเร็วกว่าที่สัญญาไว้ซะอีก...)",
  ui_story_5033_50330201_3_dialog_content = "(ฉันไม่ค่อยได้มาที่นี่เพราะไปเที่ยวโซรอซ)",
  ui_story_5033_50330201_4_dialog_content = "(ฉันหวังว่าฉันจะส่งไปรษณียบัตรกลับไปที่ Eraveil... ถ้าเมื่อวานฉันไม่ได้ทำโปสการ์ดหาย)",
  ui_story_5033_50330201_5_dialog_content = "โปสการ์ดของฉัน...เอ่อ...",
  ui_story_5033_50330201_6_dialog_content = "ขอโทษที่ฉันได้ยินคร่ำครวญของคุณ",
  ui_story_5033_50330201_7_dialog_content = "หากเป็นโปสการ์ดที่คุณอารมณ์เสีย",
  ui_story_5033_50330201_8_dialog_content = "ฉันมีหนึ่งกับฉัน นี่ เอาเลย",
  ui_story_5033_50330201_9_dialog_content = "ไม่มีทาง! มันเป็นภาพเดียวกันด้วยซ้ำ!",
  ui_story_5033_50330201_10_dialog_content = "ฉันรับไม่ได้ ฉันไม่รู้จักคุณด้วยซ้ำ...",
  ui_story_5033_50330201_11_dialog_content = "มันเหมาะกับคุณมากกว่า รับไปเถอะค่ะ เรียกว่าเป็นบุญของหนูไปวันๆ",
  ui_story_5033_50330201_12_dialog_content = "แน่จริงก็เก็บไว้ ฉันไม่ต้องการมันแล้ว",
  ui_story_5033_50330201_13_dialog_content = "คุณไม่?",
  ui_story_5033_50330201_14_dialog_content = "ใช่ เพราะฉันจะกลับไป",
  ui_story_5033_50330201_15_dialog_content = "สิบสี่ปีแล้วที่ฉันอยู่ในยูโฟเรียครั้งสุดท้าย",
  ui_story_5033_50330201_16_dialog_content = "ขอโทษที่พาดพิง",
  ui_story_5033_50330201_17_dialog_content = "ใจเย็นๆ ฉันยังรอใครซักคนอยู่ แล้วผมควรเรียกคุณว่าอะไร?",
  ui_story_5033_50330201_18_dialog_content = "...",
  ui_story_5033_50330201_19_dialog_content = "แอนสบายดีค่ะ",
  ui_story_5033_50330201_20_dialog_content = "ฉัน PlayerName. นี่จะเป็นครั้งแรกของฉันในยูโฟเรีย",
  ui_story_5033_50330201_21_dialog_content = "คุณพูดเหมือนคุณรู้ดี ช่วยบอกฉันหน่อยได้ไหม",
  ui_story_5033_50330201_22_dialog_content = "ฉันสังเกตเห็นโปสการ์ดที่ตั้งชื่อว่า \"<color=#FFB400>Wonderland</color>\"",
  ui_story_5033_50330201_23_dialog_content = "ถูกต้อง. สำหรับคนนอกในสมัยนั้น ถือได้ว่าเป็นดินแดนมหัศจรรย์อย่างแน่นอน",
  ui_story_5033_50330201_24_dialog_content = "พวกเขามาเพื่อแสวงหาความสุขที่หาไม่ได้จากที่อื่น",
  ui_story_5033_50330201_25_dialog_content = "อย่างไรก็ตาม สิ่งที่ดึงดูดใจที่สุดไม่ใช่บรรยากาศสบาย ๆ หรือภูมิทัศน์",
  ui_story_5033_50330201_26_dialog_content = "แต่กลับเป็น <color=#FFB400>ตลาดมืด</color>ที่เจริญรุ่งเรืองภายในเงามืดของอาคารอันเป็นเอกลักษณ์",
  ui_story_5033_50330201_27_dialog_content = "ตลาดมืด?!",
  ui_story_5033_50330201_28_dialog_content = "Umbraton ก็ไม่มีเหมือนกันเหรอ? ทำไมต้องไปยูโฟเรีย?",
  ui_story_5033_50330201_29_dialog_content = "มันเริ่มต้นค่อนข้างคล้ายกับ Umbraton แต่ Euphoria เป็นทรัพย์สินส่วนตัวตามกฎหมาย",
  ui_story_5033_50330201_30_dialog_content = "อย่างที่คุณอาจเดาได้ การข้ามขอบเขตเพื่อผลประโยชน์ส่วนตัวและความปรารถนาเป็นเรื่องปกติที่นั่น",
  ui_story_5033_50330201_31_dialog_content = "คาสิโนขนาดใหญ่ ผู้ผลิตอาวุธส่วนตัว... ทุกสิ่งที่คุณคิดได้ก็อยู่ที่นั่น",
  ui_story_5033_50330201_32_dialog_content = "ฟังดูมีแนวคิดเสรีมากกว่าอัมบราตันเสียอีก",
  ui_story_5033_50330201_33_dialog_content = "ขอบคุณสำหรับไพรเมอร์ ฉันรอคอยที่จะเยี่ยมชม",
  ui_story_5033_50330201_34_dialog_content = "แต่ฉันเกรงว่าคุณจะผิดหวังก็ต่อเมื่อคุณไปที่ Euphoria ด้วยความคิดอุปาทาน",
  ui_story_5033_50330201_35_dialog_content = "หมายความว่าไง",
  ui_story_5033_50330201_36_dialog_content = "หลังจากที่ฉันจากไปได้ไม่นาน ความรู้สึกสบายก็หายไปในทันใด",
  ui_story_5033_50330201_37_dialog_content = "ฉันไม่เคยได้ยินใครพูดถึงชื่อตั้งแต่นั้นมา",
  ui_story_5033_50330201_38_dialog_content = "ราวกับว่าเมืองนี้ถูกลืมโดยเจตนา",
  ui_story_5033_50330201_39_dialog_content = "เมืองที่ถูกลืม อืม...",
  ui_story_5033_50330201_40_dialog_content = "PlayerName!",
  ui_story_5033_50330201_41_dialog_content = "ขอโทษที่ให้รอ.",
  ui_story_5033_50330201_42_dialog_content = "ไม่เป็นไร. ฉันเคยคุยกับแม่ชีคนนี้ที่จะไปยูโฟเรียด้วย",
  ui_story_5033_50330201_43_dialog_content = "แอน นี่คือคอแร็กซ์ เขากำลังเดินทางไปกับฉัน",
  ui_story_5033_50330201_44_dialog_content = "เรือเหาะกำลังจะบินขึ้น เราควรขึ้นเครื่องตอนนี้",
  ui_story_5033_50330201_45_dialog_content = "หายากที่จะค้นหาเที่ยวบินไปยัง Euphoria ดังนั้นอย่าพลาด",
  ui_story_5033_50330201_46_dialog_content = "ค-ครับ...",
  ui_story_5033_50330201_47_dialog_content = "<color=#e8d9bb>บนเรือเหาะ</color>",
  ui_story_5033_50330201_48_dialog_content = "อย่างไรก็ตาม ฉันรับเรื่องอย่างเป็นทางการจาก Shadowlord เมื่อเดือนที่แล้ว",
  ui_story_5033_50330201_49_dialog_content = "Umbraton ได้พบเห็นอาชญากรรมรุนแรงที่พุ่งเป้าไปที่สถานที่หลายแห่งสำหรับการค้าใต้ดิน เช่นเดียวกับผู้ที่เกี่ยวข้องในการค้าขาย",
