  ui_story_5033_50330201_54_dialog_content = "อ้อ พูดถึง<color=#FFB400>การสังหารแม่ชี</color>ที่เป็นต้นเหตุ เรามีคนที่อยู่ข้างหน้าเราที่อาจช่วยได้",
  ui_story_5033_50330201_55_dialog_content = "...",
  ui_story_5033_50330201_56_dialog_content = "ไม่มีปัญหา ฉันสามารถให้ความร่วมมือ",
  ui_story_5033_50330201_57_dialog_content = "ใจเย็นๆ ฉันแค่อยากถามคำถามง่ายๆ สองสามข้อ",
  ui_story_5033_50330201_58_dialog_content = "คุณคุ้นเคยกับแม่ชีชื่อ <color=#FFB400>มาทิลด้า</color> หรือไม่?",
