  ui_story_5033_50330201_60_dialog_content = "แต่ทั้งหมดที่ฉันรู้คือเธอถูกย้ายจาก Euphoria ไปยัง Umbraton เธอ...?",
  ui_story_5033_50330201_61_dialog_content = "เธอเป็นหนึ่งในเหยื่อรายแรก",
  ui_story_5033_50330201_62_dialog_content = "...ขอให้เธอหลับให้สบาย",
  ui_story_5033_50330201_63_dialog_content = "บางทีนั่นอาจเป็นชะตากรรมของพวกเราแม่ชี",
  ui_story_5033_50330201_64_dialog_content = "คงหนีไม่พ้นแม้จะออกจาก Euphoria ไปแล้วก็ตาม",
  ui_story_5033_50330201_65_dialog_content = "ไม่พยายามหยาบคาย แต่ดูเหมือนคุณไม่ได้แปลกใจเป็นพิเศษ",
  ui_story_5033_50330201_66_dialog_content = "แม่ชีไม่มีที่ในความอิ่มเอิบอีกต่อไปแล้ว",
  ui_story_5033_50330201_67_dialog_content = "หากคุณถูกจับคนเดียวบนท้องถนนและไม่มีเงินเพียงพอ",
  ui_story_5033_50330201_68_dialog_content = "ตายอย่างไรก็แล้วแต่โชคชะตากำหนด",
  ui_story_5033_50330201_69_dialog_content = "ฟังดูเหมือนเป็นสถานที่เงียบสงบ...",
  ui_story_5033_50330201_70_dialog_content = "แต่คุณกำลังนั่งเรือเหาะไปยูโฟเรียเหมือนเรา",
