  ui_story_5033_50330201_80_dialog_content = "(เธอรีบจากไป ดูเหมือนเธอจะไม่กังวลเรื่องความปลอดภัยของเธอด้วย...)",
  ui_story_5033_50330201_81_dialog_content = "<color=#e8d9bb>Caw, caw—</color>",
  ui_story_5033_50330201_82_dialog_content = "ที่นี่รกร้างเหมือนที่แอนพูด",
  ui_story_5033_50330201_83_dialog_content = "อาคารทั้งอยู่ในสภาพทรุดโทรมหรือถูกทำลาย และไม่มีใครอยู่ในสายตา...",
  ui_story_5033_50330201_84_dialog_content = "ฉันเดาว่าสิ่งที่เรียกว่าวันเดอร์แลนด์นี้เป็นเพียงหมู่บ้านร้าง",
  ui_story_5033_50330201_85_dialog_content = "คุณคงเคยได้ยินชื่อเล่นของ Euphoria ใช่ไหม?",
  ui_story_5033_50330201_86_dialog_content = "ไม่ผิดหวัง. ฉันได้ข้อมูลที่เป็นประโยชน์จากทากิก่อนจะจากไป",
  ui_story_5033_50330201_87_dialog_content = "งั้นเอารายการนี้ไปลุยกันเลยครับ...",
  ui_story_5033_50330201_88_dialog_content = "หืมม?",
  ui_story_5033_50330201_89_dialog_content = "เป็นอะไรไปล่ะ",
  ui_story_5033_50330201_90_dialog_content = "ฉันสัมผัสได้ถึงสิ่งประหลาดในอากาศ...",
  ui_story_5033_50330201_91_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5033_50330201_92_dialog_content = "<size=45>เกร๋!!!</size>",
  ui_story_5033_50330201_93_dialog_content = "เช่นเดียวกับที่รายงานระบุว่า ท้องฟ้าครึ้มตลอดเวลาและมีหมอกหนาทึบทำให้เป็นสนามเด็กเล่นตามธรรมชาติสำหรับสุริยุปราคา...",
  ui_story_5033_50330201_94_dialog_content = "ไม่ว่าพวกมันจะเป็น Eclipsites ประเภทใด เราก็แค่ต้องต่อสู้กับพวกมัน!",
  ui_story_5033_50330201_95_dialog_content = "ใบมีดน้ำแข็ง!",
  ui_story_5033_50330202_1_dialog_content = "<size=45>ไอซ์เบลด!!</size>",
  ui_story_5033_50330202_2_dialog_content = "ออกไปจากที่นั่น PlayerName!",
  ui_story_5033_50330202_3_dialog_content = "<size=45>กรรรร!</size>",
  ui_story_5033_50330202_4_dialog_content = "(ฉันเคยผ่านสถานการณ์เดียวกันนี้มาแล้วนับล้านครั้งแล้ว!)",
  ui_story_5033_50330202_5_dialog_content = "(มีกรงเล็บ Eclipsite ขนาดยักษ์อยู่เหนือหัวของฉัน)",
  ui_story_5033_50330202_6_dialog_content = "(ถ้าไม่มุดหัวจะแตกในเสี้ยววินาที)",
  ui_story_5033_50330202_7_dialog_content = "อยู่ห่าง ๆ!!",
  ui_story_5033_50330202_8_dialog_content = "<color=#e8d9bb>ฟึบ!</color>",
  ui_story_5033_50330202_9_dialog_content = "...",
  ui_story_5033_50330202_10_dialog_content = "นั่นขวานเหรอ? พวกเขากำลังต่อสู้กับ Eclipsites ด้วยขวานหรือไม่?",
  ui_story_5033_50330202_11_dialog_content = "<color=#e8d9bb>*ขวานสับ*</color>",
  ui_story_5033_50330202_12_dialog_content = "<color=#e8d9bb>*ขวานเหวี่ยงและสับ*</color>",
  ui_story_5033_50330202_13_dialog_content = "พวกมันดูเหมือนชิงช้าอย่างไม่ตั้งใจ",
  ui_story_5033_50330202_14_dialog_content = "แน่นอน คนพวกนี้รู้วิธีจัดการกับ Eclipsites",
  ui_story_5033_50330202_15_dialog_content = "คุณสบายดีไหม, PlayerName? คุณดูไม่เจ็บ",
  ui_story_5033_50330202_16_dialog_content = "ฉันไม่เป็นไร แค่กลัวปัญญาเล็กน้อย",
  ui_story_5033_50330202_17_dialog_content = "พวกเขาเป็น Euphorians ในท้องถิ่นหรือไม่?",
  ui_story_5033_50330202_18_dialog_content = "ระวังว่าคุณลอกผิวมันอย่างไร หนังหน้าอกต้องเป็นชิ้นเดียว",
  ui_story_5033_50330202_19_dialog_content = "ดึงเล็บ ตัดเขาออก อ้อ ตาด้วย...",
  ui_story_5033_50330202_20_dialog_content = "โอ๊ย!",
  ui_story_5033_50330202_21_dialog_content = "ฉันบอกให้ระวังไง ไอ้สารเลว! ส่งมีดนั่นมาให้ฉัน!",
  ui_story_5033_50330202_22_dialog_content = "ตาจะพัง ใส่ลงในกองขยะแล้วเผาทิ้ง",
  ui_story_5033_50330202_23_dialog_content = "พวกเขากำลังผ่า Eclipsite หรือไม่? พวกเขาต้องการอะไรจากทั้งหมดนั้น?",
  ui_story_5033_50330202_24_dialog_content = "...",
  ui_story_5033_50330202_25_dialog_content = "เวลาที่จะไป, PlayerName.",
  ui_story_5033_50330202_26_dialog_content = "ตอนนี้? แต่พวกเขาช่วยฉันไว้ ฉันไม่ควรจะขอบคุณพวกเขาเหรอ?",
  ui_story_5033_50330202_27_dialog_content = "ตั้งใจฟัง.",
  ui_story_5033_50330202_28_dialog_content = "ดูสิ่งที่พวกเขากำลังทำอย่างใกล้ชิด",
  ui_story_5033_50330202_29_dialog_content = "พวกเขาไม่ได้พยายามช่วยคุณ พวกเขาไม่ได้สนใจคุณตั้งแต่แรก",
  ui_story_5033_50330202_30_dialog_content = "Eclipsite ซ่อนและอวัยวะ นั่นคือสิ่งที่พวกมันตามหา น่าจะขายในราคาถูกๆ แบบสกปรกๆ หนึ่งสำหรับ 200 สองสำหรับ 300",
  ui_story_5033_50330202_31_dialog_content = "พวกเขาอาจติดตาม Eclipsites มาระยะหนึ่งแล้ว เราเป็นเพียงผู้ค้ำประกันที่เดินผ่านไปมา",
  ui_story_5033_50330202_32_dialog_content = "Euphoria เมืองที่ถูกลืมไปอย่างที่เป็นอยู่ มีกฎเกณฑ์ที่แตกต่างไปจากเดิมอย่างสิ้นเชิง",
  ui_story_5033_50330202_33_dialog_content = "<size=33>ถ้าเราไม่ไปตอนนี้ ที่นี่จะดูดกลืนเราเข้าไปทั้งตัว</size>",
  ui_story_5033_50330202_34_dialog_content = "ตกลง. งั้นเรา—",
  ui_story_5033_50330202_35_dialog_content = "เดี๋ยวก่อนคุณคนนอก",
  ui_story_5033_50330202_36_dialog_content = "คุณไม่สามารถมาและไปได้ตามต้องการที่นี่",
  ui_story_5033_50330202_37_dialog_content = "<size=45>เราจำไม่ได้ว่าอนุญาตให้คุณออกไปได้!</size>",
  ui_story_5033_50330202_38_dialog_content = "<color=#e8d9bb>ส่งเสียงดัง!</color>",
  ui_story_5033_50330202_39_dialog_content = "อย่าบอกฉันว่าคุณไม่รู้กฎของ Euphoria",
  ui_story_5033_50330202_40_dialog_content = "เขาเพิ่งเจาะดิน...",
  ui_story_5033_50330202_41_dialog_content = "<size=33>ฉันว่ามันสายไปแล้วนะ</size>",
  ui_story_5033_50330202_42_dialog_content = "คำพูดคือ Euphoria เป็นสถานที่ที่มีอัธยาศัยดีซึ่งทำให้ทุกคนรู้สึกเป็นที่ต้อนรับ",
  ui_story_5033_50330202_43_dialog_content = "แน่นอนว่าการต้อนรับแบบนี้ควรได้รับการตอบแทน",
  ui_story_5033_50330202_44_dialog_content = "เอาล่ะ. ทำการนับของคุณ",
  ui_story_5033_50330202_45_dialog_content = "คุณมาที่นี่.",
  ui_story_5033_50330202_46_dialog_content = "ฉันใคร?",
  ui_story_5033_50330202_47_dialog_content = "ใครอีก? <size=33>นับตรงนี้ด้วย</size>",
  ui_story_5033_50330202_48_dialog_content = "สำหรับคุณ... พูดสิ คุณมาจากไหน?",
  ui_story_5033_50330202_49_dialog_content = "เราคือ...",
  ui_story_5033_50330202_50_dialog_content = "(ทำไมคอแร็กซ์ถึงมองมาที่ฉัน ตอนนี้คงไม่ใช่เวลามาพูดความจริง)",
  ui_story_5033_50330202_51_dialog_content = "(แต่นี่เป็นเขตการปกครองของ Umbraton ดังนั้นเราอาจสามารถดึงพวกเขาออกไปได้หากพวกเขารู้ว่าเรามาจากที่นั่น)",
  ui_story_5033_50330202_52_dialog_content = "เรามาจากเอราวีล ทางเหนือของลูโมโพลิส เป็นเมืองเล็กๆ ที่แยกตัวจากส่วนอื่นๆ ของโลก",
  ui_story_5033_50330202_53_dialog_content = "หา?",
  ui_story_5033_50330202_54_dialog_content = "อีราเวล...",
  ui_story_5033_50330202_55_dialog_content = "คุณกำลังพยายามที่จะหลอกใคร?",
  ui_story_5033_50330202_56_dialog_content = "มันเป็นความจริง.",
  ui_story_5033_50330202_57_dialog_content = "(เขาแน่ใจว่าขายมันด้วยใบหน้าที่ตรงไปตรงมา)",
  ui_story_5033_50330202_58_dialog_content = "(เขาอาจจะพยายามบอกเป็นนัยว่าพวกเขาไม่มีวัฒนธรรมเลย...)",
  ui_story_5033_50330202_59_dialog_content = "เอ่อ หัวหน้า ฉันคิดว่า Eraveil เป็นสถานที่จริง",
  ui_story_5033_50330202_60_dialog_content = "ดี. คำถามต่อไป คุณทำอะไรอยู่ และมาทำไม?",
  ui_story_5033_50330202_61_dialog_content = "เรามาที่นี่เพื่อทำธุรกิจ ขายขยะ คุณก็รู้ดีว่ามันดำเนินไปอย่างไร แค่พยายามจะขัดขืน",
  ui_story_5033_50330202_62_dialog_content = "แล้วทำไมคุณถึงไม่มีอะไรติดตัวเลย?",
  ui_story_5033_50330202_63_dialog_content = "เราแค่กำหนดขอบเขตของสถานที่ และเราได้นำเครื่องเซ่นไหว้มาด้วยไม่ใช่หรือ?",
  ui_story_5033_50330202_64_dialog_content = "เราเป็นใคร เขาเป็นคนขับรถของฉัน และฉัน ฉัน-",
  ui_story_5033_50330202_65_dialog_content = "<size=45>นับเสร็จแล้ว!</size>",
  ui_story_5033_50330202_66_dialog_content = "ฉันได้ทั้งหมด 1,235! <size=33>เงินเยอะนะเจ้านาย สองคนนี้รวยมาก</size>",
  ui_story_5033_50330202_67_dialog_content = "ไม่เป็นไร.",
  ui_story_5033_50330202_68_dialog_content = "เมื่อเราถวายเครื่องบูชาแล้ว ฉันคิดว่าเราสามารถยกเลิกพิธีต้อนรับเล็กๆ น้อยๆ นี้ได้",
  ui_story_5033_50330202_69_dialog_content = "เราจะไปเดี๋ยวนี้ ไม่จำเป็นต้องไปกับพวกเรา",
  ui_story_5033_50330202_70_dialog_content = "คุณได้กระอักเงิน แต่ไม่เพียงพอ",
  ui_story_5033_50330202_71_dialog_content = "หมายความว่าไง",
  ui_story_5033_50330202_72_dialog_content = "ราคาเพิ่งขึ้น.",
  ui_story_5033_50330202_73_dialog_content = "เท่าไร?",
  ui_story_5033_50330202_74_dialog_content = "20,000.",
  ui_story_5033_50330202_75_dialog_content = "และที่จะทำ?",
  ui_story_5033_50330202_76_dialog_content = "มาดูกันก่อน",
  ui_story_5033_50330202_77_dialog_content = "พวกเขากำลังปล้นเรา Corax! พวกเขาจะไม่ปล่อยให้เราไปแม้ว่าเราจะให้เงินทั้งหมดแก่พวกเขาก็ตาม",
  ui_story_5033_50330202_78_dialog_content = "ไม่ต้องห่วง",
  ui_story_5033_50330202_79_dialog_content = "ผมได้เงิน 20,000 คุณสามารถขอเพิ่มเติมได้ แต่คุณจะต้องมารับเอง",
  ui_story_5033_50330202_80_dialog_content = "มีเพียงเราสองคนและพวกคุณอีกสิบคน ไม่มีเหตุผลที่คุณต้องกลัว",
  ui_story_5033_50330202_81_dialog_content = "<color=#e8d9bb>สแนป!</color>",
  ui_story_5033_50330202_82_dialog_content = "<size=45>อ๊ะ!</size>",
  ui_story_5033_50330202_83_dialog_content = "เจ้านาย!!!!",
  ui_story_5033_50330202_84_dialog_content = "คุณมีความปรารถนาความตายที่เยือกเย็นหรือไม่!",
  ui_story_5033_50330202_85_dialog_content = "(แต่แขนเขาหัก!)",
  ui_story_5033_50330202_86_dialog_content = "(มันห้อยเหมือนบะหมี่เปียก)",
  ui_story_5033_50330202_87_dialog_content = "(แต่ก็ฟื้นคืนชีพได้ในเสี้ยววินาที)",
  ui_story_5033_50330202_88_dialog_content = "หยุดกรีดร้องดังๆ แขนของคุณสบายดี",
  ui_story_5033_50330202_89_dialog_content = "ดูเอาเองแล้วกัน",
  ui_story_5033_50330202_90_dialog_content = "แต่มันแตกและฉันรู้สึกได้!",
  ui_story_5033_50330202_91_dialog_content = "Yy-คุณ—",
  ui_story_5033_50330202_92_dialog_content = "เก็บเงินไว้. 20,000 นั่นเอง คุณไม่ต้องการที่จะรู้ว่าสิ่งที่ฉันทำเพื่อหาเลี้ยงชีพ?",
  ui_story_5033_50330202_93_dialog_content = "ฉันเป็นหมอ.",
  ui_story_5033_50330202_94_dialog_content = "ฉันสามารถรักษาคุณได้ และฉันสามารถทำลายกระดูกทุกส่วนในร่างกายของคุณได้เช่นกัน",
  ui_story_5033_50330202_95_dialog_content = "ไม่ใช่แค่คุณ แต่ทุกคนที่อยู่ข้างหลังคุณด้วย",
  ui_story_5033_50330202_96_dialog_content = "...",
  ui_story_5033_50330202_97_dialog_content = "ตอนนี้เรามีอิสระที่จะออกไปแล้วหรือยัง?",
  ui_story_5033_50330202_98_dialog_content = "คุณเพียงแค่รอ! คุณจะเสียใจสิ่งนี้!",
  ui_story_5033_50330301_1_dialog_content = "(ในที่สุดเราก็กำจัดมันได้...)",
  ui_story_5033_50330301_2_dialog_content = "ทำไมคุณถึงเสียเวลากับพวกเขามาก Corax?",
  ui_story_5033_50330301_3_dialog_content = "คุณน่าจะทิ้งชื่อของอิสต์วานทิ้งไป",
  ui_story_5033_50330301_4_dialog_content = "พวกเขาอาจดูใจร้าย แต่พวกมันก็แค่กลุ่มนักเลงข้างถนน",
  ui_story_5033_50330301_5_dialog_content = "ไม่มีทางที่พวกเขาจะท้าทาย Shadowlord of Umbraton",
  ui_story_5033_50330301_6_dialog_content = "นั่นจะเป็นทางออกที่ง่าย แต่อาจมีผลสะท้อนกลับ",
  ui_story_5033_50330301_7_dialog_content = "Umbraton นั้นทรงพลัง แต่ Shadowlord ชอบที่จะรักษาสิ่งต่าง ๆ ให้อยู่ในระดับต่ำ",
  ui_story_5033_50330301_8_dialog_content = "การพาเขาขึ้นมาจะถูกมองว่าเป็นการยั่วยุ",
  ui_story_5033_50330301_9_dialog_content = "นั่นคือเหตุผลที่คุณส่งสัญญาณฉันก่อนหน้านี้?",
  ui_story_5033_50330301_10_dialog_content = "ใช่. แต่เพื่อความปลอดภัยของเราและความเป็นส่วนตัวของ Shadowlord",
  ui_story_5033_50330301_11_dialog_content = "... มันจริงจังขนาดนั้นเลยเหรอ?",
  ui_story_5033_50330301_12_dialog_content = "ชาว Euphorian หลายคนเกลียด Umbraton \"หลายคน\" เป็นการพูดน้อยจริงๆ",
  ui_story_5033_50330301_13_dialog_content = "ทั้งสองไม่ได้ทำธุรกิจร่วมกันมานานหลายปี",
  ui_story_5033_50330301_14_dialog_content = "<color=#FFB400>สิบสองปีที่แล้ว</color> Darkover ได้กวาดล้าง Umbraton และภูมิภาคโดยรอบทั้งหมด",
  ui_story_5033_50330301_15_dialog_content = "เมืองทุกขนาดล่มสลาย ทำให้อัมบราตันต้องปรับโครงสร้างใหม่",
  ui_story_5033_50330301_16_dialog_content = "มีความโกลาหลอยู่ทุกหนทุกแห่ง และ Euphoria เป็นหนึ่งในเมืองที่ได้รับผลกระทบมากที่สุด",
  ui_story_5033_50330301_17_dialog_content = "สุริยุปราคาที่ Umbraton เอาชนะได้รุมเร้าเข้าสู่ Euphoria",
  ui_story_5033_50330301_18_dialog_content = "แต่ Shadowlord ไม่มีกำลังในตอนนั้น ดังนั้นเขาจึงช่วยใครไม่ได้",
  ui_story_5033_50330301_19_dialog_content = "หลังจากสงครามยุติลง ทฤษฎีสมคบคิด \"Umbraton ใช้ Darkover เพื่อทำลาย Euphoria\" ก็เริ่มหมุนเวียนไปรอบๆ",
  ui_story_5033_50330301_20_dialog_content = "แต่ฉันคิดว่าแอนบอกว่ายูโฟเรียเป็นของส่วนตัว?",
  ui_story_5033_50330301_21_dialog_content = "เจ้าของเพิ่งทิ้ง?",
