  ui_story_5033_50330301_23_dialog_content = "ผู้รอดชีวิตรวมตัวกันและสร้าง<color=#FFB400>สหกรณ์ขนาดเล็ก</color>จำนวนมาก",
  ui_story_5033_50330301_24_dialog_content = "สิ่งอำนวยความสะดวกด้านอุปทานบางส่วนสามารถกู้คืนได้หลังจากการซ่อมแซมขั้นพื้นฐาน",
  ui_story_5033_50330301_25_dialog_content = "เมื่อประชากรรอบข้างเริ่มเพิ่มขึ้น สถานที่บางแห่งกลับมาดำเนินการ",
