  ui_story_5033_50330301_29_dialog_content = "ตอนนี้ถนนอาจว่างเปล่า แต่มีดวงตาในเงามืดกำลังเฝ้าดูเราอยู่",
  ui_story_5033_50330301_30_dialog_content = "เอาล่ะ เราต้องขยับตัวและพยายามทำตัวให้ไม่เด่น",
  ui_story_5033_50330301_31_dialog_content = "ก่อนที่ฉันจะจากไป ทากิให้ทางเลือกฉันสองทาง และติดต่อผู้ติดต่อของเขาทั้งสอง",
