  ui_story_5033_50330302_33_dialog_content = "ฉันชื่อ Corax และนี่คือ PlayerName. เรามาที่นี่เพื่อตรวจสอบห่วงโซ่การสังหารต่อเนื่องในอัมบราตันเมื่อเร็วๆ นี้",
  ui_story_5033_50330302_34_dialog_content = "ตอนนี้ฉันรู้เรื่องฆาตกรน้อยมาก ยกเว้นวิธีการบางอย่าง",
  ui_story_5033_50330302_35_dialog_content = "ใจให้รายละเอียดเพิ่มเติม?",
  ui_story_5033_50330302_36_dialog_content = "โดยเฉพาะอย่างยิ่ง เหยื่อทุกคนเสียชีวิตจากการฉีกขาดแบบแปลกๆ",
