  ui_story_5033_50330302_63_dialog_content = "ลองใช้อาวุธที่เหมาะกับตัวเองมากขึ้นในครั้งต่อไป",
  ui_story_5033_50330302_64_dialog_content = "ฉันไม่เข้าใจสิ่งที่คุณหมายถึงเลย",
  ui_story_5033_50330302_65_dialog_content = "ฉันเพิ่งช่วยคุณจาก Eclipsites เหล่านั้น คุณยังไม่เข้าใจสถานการณ์ที่คุณอยู่หรือไม่?",
  ui_story_5033_50330302_66_dialog_content = "คุณหนาแน่นเกินไปที่จะคิดออกหรือไม่?",
  ui_story_5033_50330302_67_dialog_content = "Ingrates อยู่ได้ไม่นานใน Euphoria",
  ui_story_5033_50330302_68_dialog_content = "ฮึ เก็บมีดนั่นให้ห่างจากฉัน! ตกลงฉันจะพูดฉันจะบอกคุณทุกอย่างที่ฉันรู้!",
  ui_story_5033_50330302_69_dialog_content = "คุณถูกหลอกให้มาที่นี่โดยไม่รู้วิธีถือกริช",
  ui_story_5033_50330302_70_dialog_content = "ฉันจะให้ความรู้เล็กน้อยว่านายจ้างของคุณใส่ใจชีวิตของคุณเพียงใด",
  ui_story_5033_50330302_71_dialog_content = "ไม่ว่าฉันจะใช้คอของคุณเป็นพร็อพหรือไม่นั้นขึ้นอยู่กับว่าคุณให้ความร่วมมือแค่ไหน",
  ui_story_5033_50330302_72_dialog_content = "ฉันบอกว่าจะคุย!",
  ui_story_5033_50330302_73_dialog_content = "ชาวบ้านจำนวนมากเช่นฉันถูกรวมตัวเพื่อซุ่มโจมตีในเมือง",
  ui_story_5033_50330302_74_dialog_content = "ซุ่มโจมตี?",
  ui_story_5033_50330302_75_dialog_content = "ใช่ หัวหน้าไม่คิดว่าถึงเวลาต้องเคลื่อนไหวแล้ว",
  ui_story_5033_50330302_76_dialog_content = "เขาต้องการให้เราแทรกซึมเข้าไปในแก๊งค์และคลุกคลีกับพวกเขาที่บาร์และโต๊ะพนัน",
  ui_story_5033_50330302_77_dialog_content = "แค่นี้เองเหรอ",
  ui_story_5033_50330302_78_dialog_content = "คุณไม่เคยสงสัยเลยว่าพวกเขาอยากให้คุณทำอะไรต่อไป?",
  ui_story_5033_50330302_79_dialog_content = "ม-ขยับใบมีดออกไป!",
  ui_story_5033_50330302_80_dialog_content = "โอเค ฉันได้ยินเรื่องบางอย่างเกี่ยวกับพวกแกเมื่อสองสามวันก่อน",
  ui_story_5033_50330302_81_dialog_content = "ใครก็ตามที่จ้างเราอยากให้เราเผยแพร่<color=#FFB400>ข่าวลือ</color>ไปทั่วเมือง",
  ui_story_5033_50330302_82_dialog_content = "นั่นคือทั้งหมดที่ฉันรู้ ฉันสาบาน! ข่าวลืออะไรก็ไม่รู้!",
  ui_story_5033_50330302_83_dialog_content = "เข้าใจแล้ว",
  ui_story_5033_50330302_84_dialog_content = "คุณจะไม่ปล่อยฉันไปใช่ไหม ฉันบอกคุณทุกอย่างที่ฉันรู้!",
  ui_story_5033_50330302_85_dialog_content = "ข้าพเจ้าขอเสนอบทเรียนอื่นเกี่ยวกับบ้านเกี่ยวกับการเอาตัวรอดใน Euphoria...",
  ui_story_5033_50330302_86_dialog_content = "อย่าไว้ใจใครเลยที่นี่",
  ui_story_5033_50330302_87_dialog_content = "อ๊ะ!",
  ui_story_5033_50330302_88_dialog_content = "ทุก ๆ ครั้ง คุณแค่เคาะมันทิ้งแล้วทิ้งลงถังขยะ",
  ui_story_5033_50330302_89_dialog_content = "ถ้าคนรู้ว่าพอลลักซ์ที่เคารพนับถือมีเมตตาจริงๆ...",
  ui_story_5033_50330302_90_dialog_content = "พวกเขาจะยังเชื่อในชื่อเสียงที่เกี่ยวข้องกับชื่อได้อย่างไร?",
  ui_story_5033_50330302_91_dialog_content = "พวกเขาไม่ควร เป็นการดีที่สุดที่จะไม่ไว้ใจใครใน Euphoria โดยเฉพาะฉัน",
  ui_story_5033_50330302_92_dialog_content = "<color=#e8d9bb>คาว คาว...</color>",
  ui_story_5033_50330302_93_dialog_content = "อืม มีบางอย่างเกิดขึ้นที่จุดจบของเนโกะยาชิกิ",
  ui_story_5033_50330302_94_dialog_content = "ใช่ พวกเขาตามล่าเนโกะยาชิกิอย่างที่ฉันคาดไว้",
  ui_story_5033_50330302_95_dialog_content = "แม้จะเร็วกว่าที่คิด",
  ui_story_5033_50330302_96_dialog_content = "ไปที่ <color=#FFB400>ที่เดิม</color> แล้วรอ Nekoyashiki และแขกสองคนจาก Umbraton อย่างที่คุยกัน",
  ui_story_5033_50330302_97_dialog_content = "นี่ไม่เหมือนคุณเลย พอลลักซ์ อีกครั้งทำไมเราถึงพบพวกเขา?",
  ui_story_5033_50330302_98_dialog_content = "ฉันมีแรงจูงใจซ่อนเร้น ฉันรู้ว่า Shadowlord ส่งพวกเขามา",
