  ui_story_5033_50330302_105_dialog_content = "อืม...",
  ui_story_5033_50330302_106_dialog_content = "มันเริ่มเมื่อไหร่ฉันสงสัย?",
  ui_story_5033_50330401_1_dialog_content = "The Raven's Blood ที่คุณพูดถึง... เป็นหนึ่งในแก๊งค์ Euphoria หรือเปล่า?",
  ui_story_5033_50330401_2_dialog_content = "อันที่จริง คุณตัดสินใจถูกแล้วที่จะขอความช่วยเหลือจากฉัน",
  ui_story_5033_50330401_3_dialog_content = "ถ้าคุณไปหาใครอื่น คุณจะต้องกระโดดผ่านห่วงเพื่อหา Raven's Blood",
  ui_story_5033_50330401_4_dialog_content = "แก๊งนี้ประกอบด้วยผู้หญิงเพียงสองคนเท่านั้น: <color=#FFB400>Pollux</color> และ <color=#FFB400>Casta</color> แต่พวกเธอก็ยังเข้ากันได้ดีกับกลุ่มใหญ่ๆ",
  ui_story_5033_50330401_5_dialog_content = "พอลลักซ์ไม่ใช่คนที่แย่งชิงอำนาจระหว่างแก๊ง มีเพียงไม่กี่คนที่สามารถค้นหาได้",
  ui_story_5033_50330401_6_dialog_content = "Pollux เป็น \"เธอ\" ที่คุณพูดถึงหรือไม่?",
  ui_story_5033_50330401_7_dialog_content = "ได้สิ",
  ui_story_5033_50330401_8_dialog_content = "เธอรู้ว่าคุณมาถึง Euphoria และกำลังรอให้คุณมาหาฉัน",
  ui_story_5033_50330401_9_dialog_content = "หูที่ติดพื้นมากขึ้นเป็นสิ่งจำเป็นต่อการอยู่รอดที่นี่ใช่ไหม",
  ui_story_5033_50330401_10_dialog_content = "ฮ่า คุณจะไม่จับฉันได้โต้เถียงกับเรื่องนั้น โดยเฉพาะอย่างยิ่งกับแขกผู้มีเกียรติเช่นนี้",
  ui_story_5033_50330401_11_dialog_content = "ยังไงก็ตาม เธอบอกให้ผมพาพวกคุณมาหาเธอเอง ไปที่ \"จุดปกติ\" ตามที่เธอพูด",
  ui_story_5033_50330401_12_dialog_content = "หวังว่าเธอจะเป็นประโยชน์ในการสืบสวนของฉัน",
  ui_story_5033_50330401_13_dialog_content = "คุณสงสัยเธอ?",
  ui_story_5033_50330401_14_dialog_content = "ใจเย็นๆ ฉันจะไม่จับใครโดยไม่มีสาเหตุ",
  ui_story_5033_50330401_15_dialog_content = "แม้ว่าฉันจะมีผู้ต้องสงสัยอยู่ในใจ ฉันก็ยังต้องการหลักฐานที่เป็นรูปธรรมก่อนที่จะพาใครเข้ามา",
  ui_story_5033_50330401_16_dialog_content = "ทำไม รออะไร เหยื่อรายอื่นโดนตัด?",
  ui_story_5033_50330401_17_dialog_content = "ฉันไม่เคยต้องการให้ผู้บริสุทธิ์ตกเป็นเหยื่อ",
  ui_story_5033_50330401_18_dialog_content = "เรื่องนี้จริงจังมาก คุณเนโกะยาชิกิ ฉันหวังว่าคุณสามารถปฏิบัติต่อมันด้วยความเคารพ",
  ui_story_5033_50330401_19_dialog_content = "ของฉัน ของฉัน คุณได้ติดขึ้นตูดของคุณใช่ไหม? ฉันแค่พบว่าความสงสัยของคุณน่าสงสัย",
  ui_story_5033_50330401_20_dialog_content = "นั่นฟังดูไม่น่าเชื่อนักหรอกว่ามาจากฉันเพราะฉันเป็นเพื่อนของพวกเขาเหรอ?",
  ui_story_5033_50330401_21_dialog_content = "อย่างไรก็ตาม ฉันจะพาคุณไปยังที่ที่พวกเขารออยู่ก่อน",
