  ui_story_5033_50330401_23_dialog_content = "(เขาฟังดูมั่นใจในความบริสุทธิ์ของพวกเขามาก...)",
  ui_story_5033_50330401_24_dialog_content = "แล้วที่นี้ที่คุณพูดถึงคือที่ไหน?",
  ui_story_5033_50330401_25_dialog_content = "โอ้ เราเกือบจะถึงแล้ว",
  ui_story_5033_50330401_26_dialog_content = "เรากำลังจะไป <color=#FFB400>โบสถ์เก่า</color> มันเคยเป็นภาพที่เห็นก่อนที่จะถูกทอดทิ้ง",
  ui_story_5033_50330401_27_dialog_content = "(โบสถ์?)",
  ui_story_5033_50330401_28_dialog_content = "แม่ชีไม่มีที่ในความอิ่มเอิบอีกต่อไปแล้ว",
  ui_story_5033_50330401_29_dialog_content = "(พวกแม่ชีไปหมดแล้ว แต่โบสถ์ก็ยังอยู่ที่นี่ใช่มั้ย)",
  ui_story_5033_50330401_30_dialog_content = "<color=#e8d9bb>Euphoria: The Old Church</color>",
  ui_story_5033_50330401_31_dialog_content = "มันก็เหมือนกับอาคารอื่นๆ ทั้งหมด",
  ui_story_5033_50330401_32_dialog_content = "และเช่นเดียวกับอาคารอื่นๆ ทั้งหมดนั้นดีสำหรับที่พักอาศัยเท่านั้น",
  ui_story_5033_50330401_33_dialog_content = "Euphoria ไม่เคยมีผู้กอบกู้ และไม่มีใครที่นี่อธิษฐานถึงเทพเจ้าแห่งความสว่างอีกต่อไป",
  ui_story_5033_50330401_34_dialog_content = "เมืองนี้ได้รับการชำระล้างให้สะอาดจากภิกษุณีในช่วงไม่กี่ปีที่ผ่านมา คริสตจักรนี้ไม่ได้เป็นของนิกายใดอีกต่อไป",
  ui_story_5033_50330401_35_dialog_content = "แม่ชีถูกล้าง? โดยใคร?",
  ui_story_5033_50330401_36_dialog_content = "ถ้าฉันรู้ ฉันคงอยู่ได้ไม่นานพอมาถึงวันนี้",
  ui_story_5033_50330401_37_dialog_content = "บางทีอาจเป็นแค่ชะตากรรมของพวกเขา คุณไม่เจรจากับความตาย",
  ui_story_5033_50330401_38_dialog_content = "Grim Reaper ที่แพร่หลายได้ฉวยชีวิตของพวกเขาในอีกไม่กี่วันต่อมา!",
  ui_story_5033_50330401_39_dialog_content = "พวกเขาต้องตายเพราะมัจจุราชที่ไม่มีใครพูดถึง!",
  ui_story_5033_50330401_40_dialog_content = "(ฟังดูเหมือนที่ชายคนนั้นพูด...)",
  ui_story_5033_50330401_41_dialog_content = "(การฆาตกรรมต่อเนื่อง แม่ชีที่ถูกเชือด... ทั้งหมดนี้เป็นฝีมือของกริมรีปเปอร์หรือเปล่า)",
