  ui_story_5033_50330401_43_dialog_content = "เราแยกทางกันหลังจากมาถึง ฉันสงสัยว่าตอนนี้เธอเป็นอย่างไร",
  ui_story_5033_50330401_44_dialog_content = "อะไร จริงมั้ย!",
  ui_story_5033_50330401_45_dialog_content = "ใช่ เธอมากับเราจากอัมบราตัน เห็นได้ชัดว่าเธอเป็นภิกษุณี",
  ui_story_5033_50330401_46_dialog_content = "(แม่ชีจากอัมบราตัน?)",
  ui_story_5033_50330401_47_dialog_content = "คุณควรแจ้งให้ Raven's Blood ทราบเมื่อพบพวกเขา ฉันแน่ใจว่าพวกเขาจะยินดีที่จะได้ยิน",
