  ui_story_5033_50330401_49_dialog_content = "...?",
  ui_story_5033_50330401_50_dialog_content = "เกิดอะไรขึ้น พอลลักซ์?",
  ui_story_5033_50330401_51_dialog_content = "อย่าบอกนะว่าไอ้พวกนั้นยังอยู่แถวๆนั้น",
