  ui_story_5033_50330401_57_dialog_content = "คุณไปข้างหน้า ฉันต้องการกลับไปเป็นสองเท่าของย่านช้อปปิ้งนั้น",
  ui_story_5033_50330401_58_dialog_content = "ฉันไม่คิดว่าพวกฟังก์เหล่านั้นคุ้มค่ากับเวลาของคุณจริงๆ",
