  ui_story_5033_50330601_48_dialog_content = "หมอเหรอ?",
  ui_story_5033_50330601_49_dialog_content = "ฉันสามารถเห็นได้ว่าบาดแผลของพวกเขาถูกห่ออย่างระมัดระวังและผ้าพันแผลก็ค่อนข้างสะอาด",
  ui_story_5033_50330601_50_dialog_content = "แต่เด็กบางคนดูแย่กว่าการสวมใส่เล็กน้อย พวกเขาต้องการความสนใจเป็นพิเศษ",
  ui_story_5033_50330601_51_dialog_content = "หึ มันคงเป็นวันโชคดีของเรา คุณจะต้องรอจนกว่าพวกเขาจะกินเสร็จ",
  ui_story_5033_50330601_52_dialog_content = "(หืม มีใครดึงมือฉันอยู่หรือเปล่า)",
  ui_story_5033_50330601_53_dialog_content = "ใช่? มีอะไรผิดปกติหรือเปล่าสาวน้อย",
  ui_story_5033_50330601_54_dialog_content = "อืม...เอ็น-เนโกะยาชิกิบอกว่าเขาทิ้งขนมไว้ในกระเป๋าคุณ...",
  ui_story_5033_50330601_55_dialog_content = "ก-และฉันควรถามคุณว่าต้องการไหม",
  ui_story_5033_50330601_56_dialog_content = "เนโกะยาชิกิเอาขนมใส่กระเป๋าฉันเมื่อไหร่? ทำไมฉันถึงไม่รู้เรื่องนี้...",
  ui_story_5033_50330601_57_dialog_content = "ฮะ? ดูนั่นสิ มีขนมอยู่ในกระเป๋าของฉันจริงๆ!",
  ui_story_5033_50330601_58_dialog_content = "ท-แล้ว... ขอหน่อยได้มั้ยคะ?",
  ui_story_5033_50330601_59_dialog_content = "แน่นอนคุณสามารถ! เอาล่ะ. ขอโทษที่ทำให้รอ.",
  ui_story_5033_50330601_60_dialog_content = "ขอบคุณครับ!",
  ui_story_5033_50330601_61_dialog_content = "เฮ้! อย่ากินของหวานมากมายก่อนอาหาร!",
  ui_story_5033_50330601_62_dialog_content = "โอ๊ะ... ก็ได้ครับ",
  ui_story_5033_50330601_63_dialog_content = "<color=#e8d9bb>โครกก...</color>",
  ui_story_5033_50330601_64_dialog_content = "หิวเหรอ?",
  ui_story_5033_50330601_65_dialog_content = "ส-ขอโทษ. สิ่งที่วิ่งไปรอบ ๆ ทำให้เกิดความอยากอาหาร ฉันไม่สามารถทำอะไรเกี่ยวกับท้องของฉันคำราม ขออภัย",
  ui_story_5033_50330601_66_dialog_content = "ฉันสัญญาว่าฉันไม่ได้มาที่นี่เพื่อขโมยขนมปังจากเด็กๆ",
  ui_story_5033_50330601_67_dialog_content = "ฮ่า ๆ คุณสองคนเป็นคู่ที่น่าสนใจทีเดียว หมอที่ผันตัวเป็นฆาตกร กับเด็กในร่างวัยรุ่น",
  ui_story_5033_50330601_68_dialog_content = "บางทีพอลลักซ์อาจพูดถูกที่จะเชิญคุณมาที่นี่",
  ui_story_5033_50330601_69_dialog_content = "จริงอยู่ที่ การทำงานกับคน Umbraton นั้นฉลาดกว่าเสมอแทนที่จะต่อต้านพวกเขา",
  ui_story_5033_50330601_70_dialog_content = "กลิ่นนั้น — มันคือครัวซองต์!",
  ui_story_5033_50330601_71_dialog_content = "ใช่แล้ว และฉันก็นำมันมามากมายสำหรับทุกคน ดังนั้นวันนี้ทุกคนจะได้อิ่มท้องกันถ้วนหน้า",
  ui_story_5033_50330601_72_dialog_content = "ไปทักทายแขกของเรา พอลลักซ์ ฉันแจกเองได้ เอาล่ะ ใครอยากครัวซองต์ มากับฉัน!",
  ui_story_5033_50330601_73_dialog_content = "ได้เลยค่ะ!",
  ui_story_5033_50330601_74_dialog_content = "คุณสองคนยินดีเป็นอย่างยิ่งที่จะได้บางส่วนเช่นกัน",
  ui_story_5033_50330601_75_dialog_content = "ขอบคุณค่ะ เดี๋ยวเราช่วยเอง",
  ui_story_5033_50330601_76_dialog_content = "ที่นี่, PlayerName.",
  ui_story_5033_50330601_77_dialog_content = "ท-ขอบคุณ...",
  ui_story_5033_50330601_78_dialog_content = "ขอโทษ ฉันควรจะช่วย แต่สิ่งที่ฉันทำคือทำให้เรื่องยากขึ้น",
  ui_story_5033_50330601_79_dialog_content = "อย่าเข้มงวดกับตัวเองมากนัก",
  ui_story_5033_50330601_80_dialog_content = "ท้ายที่สุด เราพบคนที่สามารถทำงานด้วยที่นี่ซึ่งเราสามารถไว้วางใจได้ นั่นดีกว่าที่ฉันคาดไว้มาก",
  ui_story_5033_50330601_81_dialog_content = "มม. คนที่จะดูแลที่พักพิงใน Euphoria เพียงเพื่อเด็กๆ...",
  ui_story_5033_50330601_82_dialog_content = "ฉันพนันได้เลยว่าพวกเขาไม่เพียงแค่แข็งแกร่งมาก พวกเขาจะต้องใจดีจริงๆ ด้วย",
  ui_story_5033_50330601_83_dialog_content = "คุณประจบเรา แต่แท้จริงแล้ว การดูแลเด็กเหล่านี้ไม่ใช่เรื่องง่าย",
  ui_story_5033_50330601_84_dialog_content = "คุณไม่ได้คิดที่จะส่งพวกเขาไปที่อื่นที่ดีกว่านี้เหรอ?",
  ui_story_5033_50330601_85_dialog_content = "Umbraton มีสถานเลี้ยงเด็กกำพร้ามากมายพร้อมสิ่งอำนวยความสะดวกทุกอย่างที่จำเป็น",
  ui_story_5033_50330601_86_dialog_content = "แน่นอนว่าเราคิดเกี่ยวกับมันแล้ว เป็นเหตุผลที่เราตัดสินใจร่วมงานกับคุณ",
  ui_story_5033_50330601_87_dialog_content = "แต่ไม่ใช่ทุกคนที่สามารถเห็นเด็กกำพร้าของ Euphoria เหมือนกับเด็กคนอื่นๆ ฉันต้องหาที่ที่พร้อมจะรับพวกเขา",
  ui_story_5033_50330601_88_dialog_content = "เข้าใจแล้ว",
  ui_story_5033_50330601_89_dialog_content = "ไม่ใช่ว่าเด็กทุกคนจะเต็มใจที่จะออกจากที่นี่เช่นกัน ยิ่งไปกว่านั้น Euphoria และ Umbraton ไม่ได้อยู่ในสภาพที่ดีที่สุดในช่วงนี้...",
  ui_story_5033_50330601_90_dialog_content = "ฉันต้องการรอจนกว่าทุกอย่างจะคลี่คลายก่อนที่จะหาวิธีแก้ปัญหาระยะยาวเพิ่มเติม",
  ui_story_5033_50330601_91_dialog_content = "ฉันเข้าใจ. เท่าที่เด็ก ๆ เป็นกังวล ฉันสามารถรับประกันได้ว่า Umbraton จะต้อนรับพวกเขาด้วยอ้อมแขนที่เปิดกว้าง",
  ui_story_5033_50330601_92_dialog_content = "และเนื่องจากเราจะสำรวจสิ่งต่าง ๆ สักพัก บางทีเราอาจจะช่วยเหลือที่นี่ด้วยก็ได้",
  ui_story_5033_50330601_93_dialog_content = "โอ้ใช่! เมื่อแม่ชีมาถึงที่นี่ บางทีเธออาจช่วยลูกๆ ได้",
  ui_story_5033_50330601_94_dialog_content = "นุ่น? คุณกำลังพูดว่าคริสตจักรส่งแม่ชีมาที่คริสตจักรของเราหรือไม่?",
  ui_story_5033_50330601_95_dialog_content = "ฉันคิดอย่างนั้น. ขณะที่เราอยู่บนเรือเหาะไปยูโฟเรีย เราพบแม่ชีคนหนึ่งซึ่งบอกว่าเธอกำลังมาที่นี่",
  ui_story_5033_50330601_96_dialog_content = "บอกตามตรง ฉันคิดว่าเธอจะอยู่ที่นี่ตอนนี้...",
  ui_story_5033_50330601_97_dialog_content = "ความอิ่มอกอิ่มใจไม่ได้พบภิกษุณีมานานแล้ว บางทีพวกเขาก็ไม่ต้องการที่จะมา",
  ui_story_5033_50330601_98_dialog_content = "แต่คริสตจักรนี้ยังคงยืนอยู่ แม้ว่ามันจะค่อนข้างโทรม แต่ฉันไม่คิดว่านั่นจะหยุดพวกเขาจากการต้องการมาที่นี่",
  ui_story_5033_50330601_99_dialog_content = "คุณรู้ไหม มันเป็นภิกษุณีที่ให้ชื่อฉันเมื่อเธอพบฉันเดินไปตามถนนในยูโฟเรียเมื่อนานมาแล้ว",
  ui_story_5033_50330601_100_dialog_content = "แต่หลังจากที่ฉันออกจากโบสถ์ ฉันก็ขาดการติดต่อกับเธอ",
  ui_story_5033_50330601_101_dialog_content = "เมื่อประมาณแปดหรือเก้าปีที่แล้ว ฉันได้ยินมาว่าเธอได้ช่วยเด็กกลุ่มหนึ่งให้พ้นจากความโกลาหล เธอไปที่อัมบราตันโดยหวังว่าจะได้เงินมากกว่านี้ แต่เสียชีวิตในอุบัติเหตุระหว่างทาง",
  ui_story_5033_50330601_102_dialog_content = "ด้วยเหตุนี้ คริสตจักรแห่งนี้จึงตกอยู่ในสภาพทรุดโทรมและกระทั่งการก่อกวน",
  ui_story_5033_50330601_103_dialog_content = "และนั่นคือตอนที่คุณสองคน...",
  ui_story_5033_50330601_104_dialog_content = "ถูกต้อง. นั่นคือตอนที่คาสตากับฉันก่อตั้ง Raven's Blood และตัดสินใจซ่อมแซมสถานที่แห่งนี้ เพื่อที่จะได้พาเด็กเร่ร่อนกลับมาอีกครั้ง",
  ui_story_5033_50330601_105_dialog_content = "แต่ถ้าคริสตจักรได้ส่งภิกษุณีใหม่มารับช่วงต่อ ก็อาจจะดีกว่า",
  ui_story_5033_50330601_106_dialog_content = "\"ดีขึ้นแล้ว\"? คุณคงไม่ได้หมายความอย่างนั้นจริงๆ ใช่ไหม พอลลักซ์",
  ui_story_5033_50330601_107_dialog_content = "ฉันคิดว่า... ฉันคิดว่าคุณจะพูดว่าสำหรับเรา จะไม่มีใครมาแทนที่<color=#FFB400>ซิสเตอร์มาทิลด้า</color>",
  ui_story_5033_50330601_108_dialog_content = "ไม่มีใครแทนที่เธอ แคสต้า",
  ui_story_5033_50330601_109_dialog_content = "ดูเหมือนว่าคุณสองคนจะมีสายสัมพันธ์ทางอารมณ์ที่แน่นแฟ้นมากกับซิสเตอร์มาทิลด้าคนนี้",
  ui_story_5033_50330601_110_dialog_content = "ฉันเป็นเด็กกำพร้า Euphorian ซิสเตอร์มาทิลด้าเป็นคนที่รับฉันเข้าไป",
  ui_story_5033_50330601_111_dialog_content = "ถ้าไม่ใช่เพราะเธอ ก็บอกไม่ได้ว่าพวกแกงค์ที่นี่จะทำอะไรกับฉัน ส่วนพอลลักซ์...",
  ui_story_5033_50330601_112_dialog_content = "ความทรงจำวันเดียวก็เพียงพอแล้ว คาสต้า ถึงคราวที่เราจะฟังคุณคอแร็กซ์และเรียนรู้เกี่ยวกับการสืบสวนของเขา",
  ui_story_5033_50330601_113_dialog_content = "ฉันรู้สาระสำคัญของสิ่งที่เกิดขึ้นแล้ว ขอบคุณเนโกะยาชิกิ",
  ui_story_5033_50330601_114_dialog_content = "การลอบสังหารลึกลับเกิดขึ้นใน Umbraton และคุณสงสัยว่าฆาตกรมีส่วนเกี่ยวข้องกับ Euphoria อย่างใด",
  ui_story_5033_50330601_115_dialog_content = "ฉันคิดว่าคุณสองคนจะเต็มใจช่วยเหลือฉันมากกว่าเมื่อคุณได้ยินรายละเอียดเพิ่มเติมเกี่ยวกับการสืบสวนของฉัน",
