  ui_story_5033_50330601_117_dialog_content = "ฉันปวดใจที่จะบอกคุณ... แต่ซิสเตอร์มาทิลด้าไม่ได้เสียชีวิตจากอุบัติเหตุ",
  ui_story_5033_50330601_118_dialog_content = "เราเรียนรู้จากคริสตจักรท้องถิ่นว่าบาดแผลลึกลับบนร่างกายของเธอนั้นเหมือนกันทุกประการกับบาดแผลของเหยื่อรายอื่นในคดีนี้",
  ui_story_5033_50330601_119_dialog_content = "อะไรนะ!",
  ui_story_5033_50330601_120_dialog_content = "<color=#e8d9bb>*แตก*</color>",
  ui_story_5033_50330601_121_dialog_content = "<size=45>เมื่อกี้พูดว่าอะไรนะ?! พูดอีกที!</size>",
