  ui_story_5033_50330701_11_dialog_content = "ปกติแล้วไม่ว่าจะเกิดอะไรขึ้นหรือข่าวประเภทไหนที่เนโกะยาชิกินำมาให้พวกเขา",
  ui_story_5033_50330701_12_dialog_content = "พวกเขาไม่เคยแสดงอาการอารมณ์เสียเลย อย่างน้อยก็ไม่อยู่ต่อหน้าเรา",
  ui_story_5033_50330701_13_dialog_content = "นั่นเป็นครั้งแรกที่เราเคยเห็นพวกเขาโกรธหรือได้ยินพวกเขาตะโกนแบบนั้น",
  ui_story_5033_50330701_14_dialog_content = "อย่ากังวลมากเกินไปเกี่ยวกับเรื่องนี้ โอเค? เมื่อเราเข้าใจทุกอย่างแล้ว ฉันแน่ใจว่าพวกเขาจะไม่โกรธอีกต่อไป",
