  ui_story_5033_50330701_18_dialog_content = "ฉันสามารถบอกคุณได้ว่าใช่ มันเกี่ยวข้องกับซิสเตอร์มาทิลด้า",
  ui_story_5033_50330701_19_dialog_content = "สำหรับรายละเอียดที่เหลือ เรายังมีอีกมากที่ต้องทำ",
  ui_story_5033_50330701_20_dialog_content = "แต่เมื่อเราทำงานเสร็จแล้ว ฉันแน่ใจว่าพอลลักซ์และคาสตาจะแบ่งปันงานที่เหลือกับคุณ",
