  ui_story_5033_50330701_23_dialog_content = "มีอะไรหรือเปล่า",
  ui_story_5033_50330701_24_dialog_content = "ฉันคิดว่าฉันเจอคนข้างนอกเมื่อกี้... ข้างหลังคุณ ตรงนั้น",
  ui_story_5033_50330701_25_dialog_content = "<color=#e8d9bb>เอี๊ยด...</color>",
  ui_story_5033_50330701_26_dialog_content = "ฉันไม่เห็นใครเลย",
  ui_story_5033_50330701_27_dialog_content = "แปลก ... ฉันอาจจะจินตนาการได้? สาบานได้เลยว่าเห็นใครเดินผ่านมา...",
  ui_story_5033_50330701_28_dialog_content = "บางทีพวกเขากำลังซ่อนตัวอยู่? ฉันจะพยายามรับรู้ถึงการมีอยู่ของพวกเขา...",
  ui_story_5033_50330701_29_dialog_content = "เธอหมายความว่าไง",
  ui_story_5033_50330701_30_dialog_content = "เอ่อ... พูดง่ายๆ ก็คือ ฉันมีพลังพิเศษที่ช่วยให้ฉันค้นหาผู้คนโดยไม่เห็นพวกเขา มันเป็นเรื่องของฉัน",
