  ui_story_5033_50330701_33_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5033_50330701_34_dialog_content = "ฉันสัมผัสได้ถึงคนที่มีอำนาจมากสามคนในทางเดินด้านนอกนั้น นั่นควรเป็น Corax, Casta และ Pollux",
  ui_story_5033_50330701_35_dialog_content = "นอกจากนี้ยังมี Eclipsites สองสามแห่งที่สัญจรไปมาในพื้นที่ แต่ก็ยังค่อนข้างไกลจากโบสถ์",
  ui_story_5033_50330701_36_dialog_content = "และยิ่งไปกว่านั้น... ทั้งหมดที่ฉันสัมผัสได้คือคนธรรมดา",
  ui_story_5033_50330701_37_dialog_content = "โอ้... บางทีฉันอาจจะแค่เห็นสิ่งต่าง ๆ ก็ได้",
