  ui_story_5033_50330701_44_dialog_content = "ชาโดว์ลอร์ดต้องการใครสักคนเพื่อตรวจสอบซากศพ และนั่นเป็นช่วงเวลาที่ฉันค้นพบร่องรอยของวิธีการฆ่าที่ฆาตกรชอบ",
  ui_story_5033_50330701_45_dialog_content = "<color=#e8d9bb>หนึ่งเดือนก่อน...</color>",
  ui_story_5033_50330701_46_dialog_content = "คุณกำลังพูดว่าคุณเห็นบาดแผลแบบนี้ในผู้ป่วยที่เสียชีวิตเมื่อสองสามวันก่อนเหรอ?",
  ui_story_5033_50330701_47_dialog_content = "แน่นอนและผู้ป่วยที่แปลกประหลาดในตอนนั้น สภาพของเขายังห่างไกลจากวิกฤต แต่เขาก็ยังเสียชีวิตเหมือนเดิม",
