  ui_story_5033_50330701_50_dialog_content = "มีรายงานล่าสุดเกี่ยวกับการเสียชีวิตที่แปลกประหลาดเช่นนี้หรือไม่?",
  ui_story_5033_50330701_51_dialog_content = "ใช่ แต่ร่างกายของพวกมันถูกวางให้พักแล้ว... เว้นแต่คุณต้องการให้ฉันขุดพวกมัน?",
