  ui_story_5033_50330701_60_dialog_content = "หากไม่ใช่เพราะการฆาตกรรมที่ใกล้เคียงกันเพิ่มขึ้นเมื่อเร็วๆ นี้ เราอาจไม่เคยค้นพบว่านี่เป็นผลงานของฆาตกรต่อเนื่อง",
  ui_story_5033_50330701_61_dialog_content = "แม้ว่าเราจะตรวจสอบ MO แล้ว แต่เราก็ยังไม่พบเบาะแสที่เป็นประโยชน์อื่นๆ",
  ui_story_5033_50330701_62_dialog_content = "ระหว่างการสอบสวน ฉันพบว่าร่างของผู้เสียชีวิตในอุบัติเหตุที่ถูกกล่าวหาเมื่อหลายปีก่อนมีรอยแผลเป็นเหมือนกับเหยื่อของฆาตกรต่อเนื่อง",
