  ui_story_5033_50330702_46_dialog_content = "เนโกะยาชิกิทิ้งขนมนี้ไว้กับฉัน รู้ไหม? ถ้าคุณไม่เคารพเขา ทำไมฉันถึงต้องแบ่งปันบางอย่างกับคุณ?",
