  ui_story_5033_50330702_48_dialog_content = "อยากรู้อะไรบางอย่าง? เมื่อเนโกะยาชิกิมาที่ยูโฟเรียเป็นครั้งแรก เขามีทัศนคติที่แย่มาก",
  ui_story_5033_50330702_49_dialog_content = "แต่แล้วพวกอันธพาลก็เอาชนะอึที่มีชีวิตออกจากตัวเขา!",
  ui_story_5033_50330702_50_dialog_content = "เขาปรากฏตัวขึ้นที่นี่ เต็มไปด้วยเลือดและฟกช้ำ ต้องขอบคุณ Pollux และ Casta เท่านั้นที่เขารอดชีวิตมาได้",
  ui_story_5033_50330702_51_dialog_content = "ทำไมคุณเล่าเรื่องนี้ราวกับว่าคุณเห็นมันด้วยตัวคุณเอง? คุณอยู่ที่นั่นเมื่อมันเกิดขึ้น?",
  ui_story_5033_50330702_52_dialog_content = "เดี๋ยวนะ... อย่าบอกนะว่านายแก่กว่าเขาจริงๆ!",
  ui_story_5033_50330702_53_dialog_content = "มีถั่วมั้ย? ใช่ ฉันอยู่ที่นั่น แต่ฉันอายุแค่ 5 ขวบ",
  ui_story_5033_50330702_54_dialog_content = "แล้วจุดประสงค์ของการเล่าเรื่องนั้นคืออะไร?",
