  ui_story_5033_50330702_57_dialog_content = "ส-ใช่... ฉันไม่รู้ว่าเนโกะยาชิกิต้องเจออะไรแบบนั้น ฉันเดาว่ามันอธิบายได้ว่าทำไมเขาถึงมีข้อตกลงที่ดีกับ Raven's Blood",
