  ui_story_5033_50330702_59_dialog_content = "ฮี่ฮี่ฮี่... ฉันได้ยินมาว่าเนโกะยาชิกิยังเป็นเด็กเลยตอนที่เขามาโบสถ์ครั้งแรก",
  ui_story_5033_50330702_60_dialog_content = "พอลลักซ์กล่าวว่าแม้ว่าใบหน้าของเขาจะบวมและเปื้อนเลือดในตอนนั้น แต่ดวงตาของเขาเต็มไปด้วยความภาคภูมิใจ",
