  ui_story_5033_50331001_82_dialog_content = "ฉันขอโทษ... Antares... ฉันรู้ว่าฉันดื้อรั้นและเธอแค่มองออกสำหรับฉัน...",
  ui_story_5033_50331001_83_dialog_content = "คุณไม่จำเป็นต้องขอโทษฉัน พอลลักซ์ ฉันไม่ใช่คนที่คุณเจ็บปวด... คุณคือ.",
  ui_story_5033_50331001_84_dialog_content = "ถ้าฉันสามารถทำสิ่งต่าง ๆ ได้อีกครั้ง ฉันจะเลือกชีวิตของตัวเอง",
  ui_story_5033_50331001_85_dialog_content = "ชีวิตที่ปราศจากความรู้สึกผิด... หรือฝันร้ายที่จะปลุกฉันทุกคืน",
  ui_story_5033_50331001_86_dialog_content = "ชีวิต... ปราศจาก \"ภารกิจ\"",
  ui_story_5033_50331001_87_dialog_content = "ฮะ? แต่ฉันอยากไปทำภารกิจจริงๆ แอนทาเรส...",
  ui_story_5033_50331001_88_dialog_content = "ฉันอยากสู้เคียงข้างเธอ เราจะได้มีกันและกันตลอดเวลา",
  ui_story_5033_50331001_89_dialog_content = "หลังจากที่ผมบอก ผมก็สามารถออกไปทำงานเผยแผ่ได้...",
  ui_story_5033_50331001_90_dialog_content = "คุณกำลังทำอะไรอยู่ที่นั่น พอลลักซ์? มันเป็นความลับหรือไม่?",
  ui_story_5033_50331001_91_dialog_content = "ฮ-เฮ้! หลับตาลงเสีย! ไม่แอบดู ได้ยินไหม!",
  ui_story_5033_50331001_92_dialog_content = "อืม ได้... เห็นไหม พวกเขากำลังปิด",
  ui_story_5033_50331001_93_dialog_content = "และ...เรียบร้อย! คุณสามารถเปิดตาของคุณตอนนี้!",
  ui_story_5033_50331001_94_dialog_content = "นี่คือ <color=#FFB400>เข็มกลัด</color>... สำหรับฉันเหรอ?",
  ui_story_5033_50331001_94X1_dialog_content = "ใช่ ร้านบอกฉันว่าเป็นไฮเดรนเยีย และฉันคิดว่ามันเหมาะกับคุณมาก",
  ui_story_5033_50331001_95_dialog_content = "ใช่! ฉันได้รับค่าจ้างเพียงเล็กน้อยในตอนนี้ ดังนั้นนี่คือทั้งหมดที่ฉันพอจะจ่ายได้",
  ui_story_5033_50331001_96_dialog_content = "แต่เมื่อฉันทำภารกิจเสร็จสิ้นและเก็บเงิน ฉันจะได้ของที่ดีกว่ามาให้คุณ! สิ่งที่ฉันแน่ใจว่าคุณจะรัก!",
  ui_story_5033_50331001_97_dialog_content = "ม-ภารกิจ...?",
  ui_story_5033_50331001_98_dialog_content = "ใช่! ฉันพบบอสเมื่อสองสามวันก่อน และเขาบอกฉันว่าเขาจะมีภารกิจให้ฉันในไม่ช้า!",
  ui_story_5033_50331001_99_dialog_content = "ดังนั้นฉันจึงมีสิ่งนี้สำหรับคุณเพื่อเฉลิมฉลองความปรารถนาของฉันที่เป็นจริงและเพื่อขอบคุณที่อยู่ที่นั่นเพื่อฉันเสมอมา",
  ui_story_5033_50331001_100_dialog_content = "แล้วฉันจะให้อะไรคุณต่อไป...?",
  ui_story_5033_50331001_101_dialog_content = "...",
  ui_story_5033_50331001_102_dialog_content = "เป็นอะไรไป อันทาเรส? คุณไม่ชอบมันเหรอ?",
  ui_story_5033_50331001_103_dialog_content = "ไม่ นั่นไม่ใช่มัน ฉันชอบดอกไม้สีม่วงที่ดูสวย",
  ui_story_5033_50331001_104_dialog_content = "พอลลักซ์...",
  ui_story_5033_50331001_105_dialog_content = "อะไรเหรอ?",
  ui_story_5033_50331001_106_dialog_content = "ขอบคุณ...ที่เป็นเพื่อนฉัน ช่วงเวลาที่เราได้ใช้ร่วมกันเป็นช่วงเวลาที่มีความสุขที่สุดในชีวิตของฉัน",
  ui_story_5033_50331001_107_dialog_content = "คุณจะไม่เป็น Antares ถ้าคุณไม่ได้ออกมาพร้อมกับสิ่งที่วิเศษ",
  ui_story_5033_50331001_108_dialog_content = "ฉันทำมันเกินไป",
  ui_story_5033_50331001_109_dialog_content = "ขอบคุณที่เป็นเพื่อนของฉัน Antares",
  ui_story_5033_50331001_110_dialog_content = "ฉันไม่เคยคาดหวังว่าภารกิจจะเป็นแบบนั้น",
  ui_story_5033_50331001_111_dialog_content = "ฉันในสนามประลอง เผชิญหน้ากับเพื่อนสนิทของฉัน...",
  ui_story_5033_50331001_112_dialog_content = "อ-อะไรกัน...",
  ui_story_5033_50331001_113_dialog_content = "ทำไมคุณถึงเป็นคู่ต่อสู้ของฉัน...?",
  ui_story_5033_50331001_114_dialog_content = "หนึ่งคือหุ่นยนต์ต่อสู้ซึ่งได้รับการเลี้ยงดูจากการต่อสู้จริง",
  ui_story_5033_50331001_115_dialog_content = "อีกคนหนึ่งเป็นดาวรุ่งที่มีแนวโน้มสดใสและมีพรสวรรค์ที่ได้รับการฝึกฝนมาอย่างดีในค่ายฝึก",
  ui_story_5033_50331001_116_dialog_content = "คู่หูไดนาไมต์นี้เรียกว่าราศีเมถุน! แต่วันนี้ มีเพียงคนเดียวเท่านั้นที่จะเดินออกจากสังเวียน",
  ui_story_5033_50331001_117_dialog_content = "ความอิ่มอกอิ่มใจเคยเห็น—หรือจะเคยพบเห็น—เป็นการกัดเล็บและการแข่งขันที่น่าตื่นเต้นเช่นนี้หรือไม่?",
  ui_story_5033_50331001_118_dialog_content = "แอนทาเรส คุณ...",
  ui_story_5033_50331001_119_dialog_content = "ยกกริชของคุณขึ้นแล้วมาหาฉัน",
  ui_story_5033_50331001_120_dialog_content = "ไม่ใช่ภารกิจที่คุณรอคอยใช่ไหม",
  ui_story_5033_50331001_121_dialog_content = "ฉันรู้ว่าคุณฝึกฝนอย่างหนักเพื่อสิ่งนี้",
  ui_story_5033_50331001_122_dialog_content = "แต่ฉัน...",
  ui_story_5033_50331001_123_dialog_content = "จะรออะไรอยู่ล่ะ?",
  ui_story_5033_50331001_124_dialog_content = "ถ้านี่เป็นการต่อสู้จริง คุณคงตายไปหลายสิบครั้งแล้วในตอนนี้",
  ui_story_5033_50331001_125_dialog_content = "ฉันแค่ยกมือขึ้นสู้คุณไม่ได้...",
  ui_story_5033_50331001_126_dialog_content = "ถ้าฉันบอกคุณว่าเหตุผลเดียวที่คุณอยู่ที่นี่ตอนนี้ เป็นเพราะฉัน",
  ui_story_5033_50331001_127_dialog_content = "ไม่... ไม่ นั่นไม่เป็นความจริง!",
  ui_story_5033_50331001_128_dialog_content = "ทำให้เราทะเลาะกันทำไม? คุณไม่คิดว่ามันแปลกไปหน่อยเหรอ?",
  ui_story_5033_50331001_129_dialog_content = "แปลก? ไม่มีอะไรแปลกใน Euphoria และมีความลับมากมายที่คุณไม่สามารถคาดเดาได้",
  ui_story_5033_50331001_130_dialog_content = "เห็นได้ชัดว่าฉัน... ชักชวนคุณหลายครั้งในอดีต",
  ui_story_5033_50331001_131_dialog_content = "ไม่มีทางที่ฉันจะหักเงินให้คุณได้",
  ui_story_5033_50331001_132_dialog_content = "คุณจะยกมือขึ้นต่อต้านฉันจริงๆ ... ?",
  ui_story_5033_50331001_133_dialog_content = "ถูกต้อง. ฉันเกิดมาในการต่อสู้ และสิ่งแรกที่ฉันเรียนรู้คือ—",
  ui_story_5033_50331001_134_dialog_content = "ไม่แสดงความเมตตาต่อใคร",
  ui_story_5033_50331001_135_dialog_content = "ไม่... <size=45>ฉันไม่ต้องการที่จะสู้กับคุณ Antares!</size>",
  ui_story_5033_50331001_136_dialog_content = "<size=45>ป้องกันตัว หรือ ตาย!!</size>",
  ui_story_5033_50331001_137_dialog_content = "เมื่อฉันมาถึง...",
  ui_story_5033_50331001_138_dialog_content = "มันสายเกินไปแล้ว.",
  ui_story_5033_50331001_139_dialog_content = "อึก...!",
  ui_story_5033_50331001_140_dialog_content = "ฉัน... ฉัน... ฉันทำอะไรลงไป",
  ui_story_5033_50331001_141_dialog_content = "Antares... ทำไมคุณไม่วิ่ง?",
  ui_story_5033_50331001_142_dialog_content = "<anim type=Shake>ขอบคุณ... ขอบคุณ... Pollux...</anim>",
  ui_story_5033_50331001_143_dialog_content = "อันทาเรส! ไม่! อย่าทิ้งฉัน... ขอโทษ... ฉันขอโทษ...",
  ui_story_5033_50331001_144_dialog_content = "ทำไม... ทำไมคุณไม่วิ่งหนีล่ะ?",
  ui_story_5033_50331001_145_dialog_content = "<anim type=Shake>ทางนี้ฉันจะ... เป็นอิสระได้...</anim>",
  ui_story_5033_50331001_146_dialog_content = "<anim type=Shake>ในที่สุดก็ว่าง...</anim>",
  ui_story_5033_50331001_147_dialog_content = "ฉันทำมัน การตายของ Antares อยู่กับฉัน... ฉันฆ่าเพื่อนคนเดียวในโลกทั้งใบด้วยมือของฉันเอง",
  ui_story_5033_50331001_148_dialog_content = "ฉันไม่เข้าใจจนกระทั่งกริชในมือของฉันเจาะหน้าอกของ Antares แล้ว",
  ui_story_5033_50331001_149_dialog_content = "ที่ครั้งหนึ่งฉันเคยใฝ่ฝันช่างน่ากลัวจริงๆ",
  ui_story_5033_50331001_150_dialog_content = "เหตุนี้ท่านจึงไม่ถือมีดอีกต่อไป...",
  ui_story_5033_50331001_151_dialog_content = "ใช่. เหตุการณ์ในวันนั้นวนเวียนอยู่ในหัวของฉัน จริง ๆ แล้วเหมือนฉันกลับมาที่เวทีจริง ๆ",
  ui_story_5033_50331001_152_dialog_content = "ฉันหมดสติหลังการต่อสู้และมีไข้สูงเป็นเวลากว่าสัปดาห์",
  ui_story_5033_50331001_153_dialog_content = "เมื่อฉันตื่นขึ้น ฉันก็อยู่คนเดียวในห้อง",
  ui_story_5033_50331001_154_dialog_content = "เสื้อผ้า สมุดโน้ตของ Antares... ร่องรอยทั้งหมดของเธอหายไปจากภายในกำแพงสี่เหลี่ยมทั้งสี่นั้นอย่างสมบูรณ์",
  ui_story_5033_50331001_155_dialog_content = "มันสะอาดมาก ปลอดเชื้อ... ราวกับว่าเธอไม่เคยมีอยู่ในโลกนี้",
  ui_story_5033_50331001_156_dialog_content = "ฉันรีบออกจากห้องนั้นด้วย ในเวลาไม่ถึงเดือน ชาวเมืองทั้งสองก็จากไป",
  ui_story_5033_50331001_157_dialog_content = "คุณออกจากองค์กรนั้นหรือไม่?",
  ui_story_5033_50331001_158_dialog_content = "มันไม่ใช่เรือกระโดดมากเท่ากับถูกผลัก",
  ui_story_5033_50331001_159_dialog_content = "หลังจากการต่อสู้ครั้งนั้น ฉันเริ่มกลัวและพบว่ามันยากแม้จะถือกริช",
  ui_story_5033_50331001_160_dialog_content = "สำหรับทหารรับจ้าง การสูญเสียความสามารถในการต่อสู้หมายถึงการสูญเสียคุณค่าทั้งหมด",
  ui_story_5033_50331001_161_dialog_content = "ดังนั้นจึงเป็นเรื่องธรรมดาที่ฉันถูกไล่ออกจากทีมและถูกคุมขังในห้องใต้ดิน",
  ui_story_5033_50331001_162_dialog_content = "จนกระทั่งสุริยุปราคามาถล่มที่นั้นให้ราบคาบ",
  ui_story_5033_50331001_163_dialog_content = "คุณมีอินเทลอื่นหรือไม่?",
  ui_story_5033_50331001_164_dialog_content = "ไม่ฉันขอโทษ. นั่นคือทั้งหมดที่ฉันรู้...",
  ui_story_5033_50331001_165_dialog_content = "ฉันจะสัญญากับคุณ - ฉันจะช่วยให้คุณไปถึงก้นบึ้งของสิ่งนี้",
  ui_story_5033_50331001_166_dialog_content = "<color=#e8d9bb>ลา ลา ล้า...</color>",
  ui_story_5033_50331001_167_dialog_content = "เดี๋ยวก่อน! ฉันรู้สึกว่าคนจำนวนมากกำลังมุ่งหน้าไปทางนี้!",
  ui_story_5033_50331001_168_dialog_content = "ใครน่ะ?",
  ui_story_5033_50331001_169_dialog_content = "ฉันไม่รู้ แต่ฉันคิดว่าพวกเขาต้องการ... ล้อมรอบโบสถ์!",
  ui_story_5033_50331101_1_dialog_content = "<color=#e8d9bb>ตูม—!</color>",
  ui_story_5033_50331101_2_dialog_content = "ก้าวต่อไปพวก! รีบขึ้น!",
  ui_story_5033_50331101_3_dialog_content = "อาวุธพร้อม เตรียมรบ Raven's Blood ไม่ใช่การยั่วยุ!",
  ui_story_5033_50331101_4_dialog_content = "พร้อมค่ะ!",
  ui_story_5033_50331101_5_dialog_content = "ต่ำลงจนกว่าเราจะอยู่ในตำแหน่ง ฉันจะให้สัญญาณไฟ เข้าใจไหม",
  ui_story_5033_50331101_6_dialog_content = "รับทราบ!",
  ui_story_5033_50331101_7_dialog_content = "พวกเราทุกคนอยู่และถูกต้องหรือไม่?",
  ui_story_5033_50331101_8_dialog_content = "ทุกคนอยู่ที่นี่เจ้านาย! Raven's Blood เสร็จแล้วคราวนี้!",
  ui_story_5033_50331101_9_dialog_content = "ฮา สุดยอด! ฉันรอวันนี้มานานแล้ว",
  ui_story_5033_50331101_10_dialog_content = "เฮ้ เดี๋ยวก่อน... กุสตาฟบอกเราว่าอย่ารีบไม่ใช่เหรอ?",
  ui_story_5033_50331101_11_dialog_content = "<size=45>รู้อะไรมั้ย!</size>",
  ui_story_5033_50331101_12_dialog_content = "นี่เป็นโอกาสที่ดีในการหาหลักฐานการสมรู้ร่วมคิดระหว่าง Raven's Blood และ Umbraton",
  ui_story_5033_50331101_13_dialog_content = "เราจะทำอย่างไรถ้าเราปล่อยให้พวกเขาหนีไป หืม?",
  ui_story_5033_50331101_14_dialog_content = "เชิงลบ. ฉันต้องรายงานกลับไปที่กุสตาฟ",
  ui_story_5033_50331101_15_dialog_content = "คุณกลายเป็นหุ่นเชิดของกุสตาฟเมื่อไหร่?",
  ui_story_5033_50331101_16_dialog_content = "ดีแล้ว ออกไปจากที่นี่ ฉันพูดว่า GO! อย่ารบกวนฉัน!",
  ui_story_5033_50331101_17_dialog_content = "ไม่ว่าพวกเขาจะเป็นใคร พวกเขากำลังมุ่งหน้าไปทางนี้อย่างแน่นอน",
  ui_story_5033_50331101_18_dialog_content = "ใครกล้ามองหาปัญหากับ Raven's Blood?",
  ui_story_5033_50331101_19_dialog_content = "ฉันเกรงว่าครั้งนี้จะไม่ง่ายนัก",
  ui_story_5033_50331101_20_dialog_content = "ไม่มีใครกล้าเข้าใกล้คริสตจักรมาก่อน",
  ui_story_5033_50331101_21_dialog_content = "ครั้งนี้เป็นกลุ่มใหญ่ ฉันกังวลว่าพวกเขาได้รวมตัวกันเพื่อเริ่มการโจมตี",
  ui_story_5033_50331101_22_dialog_content = "ทำไมต้องมาตอนนี้ด้วยเนี่ย?",
  ui_story_5033_50331101_23_dialog_content = "ดูเหมือนพวกเขาจะมีอะไรกับพวกอัมบราตันที่เข้ามาในยูโฟเรียจริงๆ",
  ui_story_5033_50331101_24_dialog_content = "เป็นเพราะเรามาที่นี่?",
  ui_story_5033_50331101_25_dialog_content = "ฉันขอโทษ คอแร็กซ์",
  ui_story_5033_50331101_26_dialog_content = "บางทีวิธีการทำสิ่งต่างๆ ของเราอาจทำให้แก๊งท้องถิ่นไม่พอใจ",
  ui_story_5033_50331101_27_dialog_content = "ฉันเกรงว่าเราต้องจัดการเรื่องทะเลาะวิวาทนี้ก่อน",
  ui_story_5033_50331101_28_dialog_content = "พวกเขาเป็นแค่คนขี้ขลาด รังแกคนอ่อนแอ แต่กลัวคนเข้มแข็ง พวกเขาคิดว่าพวกเขาสามารถเอาชนะ Raven's Blood ของเราได้จริงหรือ?",
