  ui_story_5033_50331101_30_dialog_content = "เหน็บมันเข้าไปหน่อย ไม่มีประโยชน์สำหรับเราในการทำให้เรื่องแย่ลง",
  ui_story_5033_50331101_31_dialog_content = "Casta, Corax—พาเด็กๆ ไปที่ Nekoyashiki เพื่อหาที่พักพิง",
  ui_story_5033_50331101_32_dialog_content = "พวกเขากำลังติดตามเลือดของเรเวนและคริสตจักร ฉันจะพยายามขัดขวางพวกเขาที่นี่",
  ui_story_5033_50331101_33_dialog_content = "ตกลง. ฉันจะดูแลเด็กๆ ให้ปลอดภัย ฉันสัญญา",
  ui_story_5033_50331101_34_dialog_content = "แล้วคุณล่ะ ไม่มีใครสามารถจัดการกับคนจำนวนมากเพียงลำพังได้ แม้กระทั่งคุณ",
  ui_story_5033_50331101_35_dialog_content = "ฉันจะพยายามอย่างเต็มที่เพื่อซื้อเวลาให้คุณ ไปเดี๋ยวนี้ พาเด็ก ๆ และออกไปจากที่นี่",
  ui_story_5033_50331101_36_dialog_content = "... เข้าใจแล้ว คุณควรรอจนกว่าฉันจะกลับไป!",
