  ui_story_5033_50331101_38_dialog_content = "PlayerName",
  ui_story_5033_50331101_39_dialog_content = "ฮะ? ที่นี่!",
  ui_story_5033_50331101_40_dialog_content = "แม้ว่าฉันจะไม่ค่อยรู้เรื่องของคุณมากนัก แต่ฉันคิดว่าคุณสามารถหาเส้นทางที่ปลอดภัยเพื่อพาทุกคนออกไปจากที่นี่ได้",
