  ui_story_5033_50331101_42_dialog_content = "ได้เลย!",
  ui_story_5033_50331101_43_dialog_content = "เนโกะยาชิกิมักจะอยู่ที่กระท่อมของเขา จำได้มั้ยว่าที่ไหน?",
  ui_story_5033_50331101_44_option_content = "แน่นอนสิ",
  ui_story_5033_50331101_45_dialog_content = "เนโกะยาชิกิอาศัยอยู่ในกระท่อมที่มีภาพวาดรูปแผลเป็น",
