  ui_story_5033_50331202_47_dialog_content = "ดังนั้น... นี่คือความรู้สึก... ที่ถูกสังหารโดยจอมมรณะ...",
  ui_story_5033_50331202_48_dialog_content = "ด้วยความขอบคุณที่คุณให้เบาะแสนี้แก่ฉัน ฉันจะพยายามทำให้ดีที่สุดเพื่อที่คุณจะได้ไม่ต้องทนทุกข์ทรมานเกินควร",
  ui_story_5033_50331202_49_dialog_content = "คุณมีความขอบคุณของฉัน",
  ui_story_5033_50331202_50_dialog_content = "และตอนนี้... ในที่สุด ผมก็สามารถไปหาพอลลักซ์ได้",
  ui_story_5033_50331202_51_dialog_content = "เจ้านาย! เฮ้ บอส! เรามีระเบิด!",
  ui_story_5033_50331202_52_dialog_content = "อาจจะไม่มากนัก แต่ก็เพียงพอที่จะทำให้โบสถ์นั้นลอยสูงเสียดฟ้า",
  ui_story_5033_50331202_53_dialog_content = "ยอดเยี่ยม! ทำได้ดี.",
  ui_story_5033_50331202_54_dialog_content = "จัดวางเป็นวงกลมรอบโบสถ์",
  ui_story_5033_50331202_55_dialog_content = "ระวังเมื่อวาง โดยเฉพาะอย่างยิ่งเกี่ยวกับพวกเขายิงจากภายในโบสถ์",
  ui_story_5033_50331202_56_dialog_content = "ได้เลย!",
  ui_story_5033_50331202_57_dialog_content = "ขอโทษนะ ฉันขอตัวไปก่อนนะ",
  ui_story_5033_50331202_58_dialog_content = "ภิกษุณีมาจากไหน? ออกไปให้พ้น เว้นแต่คุณจะอยู่ในตลาดโลงศพ...",
  ui_story_5033_50331202_59_dialog_content = "<color=#e8d9bb>วู้—!</color>",
  ui_story_5033_50331202_60_dialog_content = "<size=45>อ้ากกก!! ฆาตกรรม!!</size>",
  ui_story_5033_50331202_61_dialog_content = "อะไร?! เกิดอะไรขึ้นที่นั่น?",
  ui_story_5033_50331202_62_dialog_content = "ไม่ต้องกังวล ไม่มีอะไรเกิดขึ้น... ผู้คนตายในสงครามแก๊งค์",
  ui_story_5033_50331202_63_dialog_content = "คุณมาจากที่ไหน?!",
  ui_story_5033_50331202_64_dialog_content = "<color=#e8d9bb>วู้—!</color>",
  ui_story_5033_50331202_65_dialog_content = "อ๊าก—! มือฉัน...มือฉัน!",
  ui_story_5033_50331202_66_dialog_content = "เจ้านาย! แม่ชีคนนี้มีมีด...!",
  ui_story_5033_50331202_67_dialog_content = "ฉันรู้! เธอเป็นคนตัดฉันเอง! ไล่ตามนางลงมา!!",
  ui_story_5033_50331202_68_dialog_content = "ฉันแนะนำว่าอย่าใช้ระเบิดเพื่อทำลายโบสถ์ มิฉะนั้นคุณจะเผชิญกับพระพิโรธจากสวรรค์",
  ui_story_5033_50331202_69_dialog_content = "<color=#e8d9bb>วู้—!</color>",
  ui_story_5033_50331202_70_dialog_content = "<color=#e8d9bb>ตูม—!</color>",
  ui_story_5033_50331202_71_dialog_content = "ระเบิด? กระจายด่วน!",
  ui_story_5033_50331202_72_dialog_content = "ภิกษุณีนั้นแล่เปิดคาร์ทริดจ์ระเบิด เธอบ้าไปแล้ว!",
  ui_story_5033_50331202_73_dialog_content = "ดูนั่นสิ! แม่ชียังมีชีวิตอยู่... เธอทำได้อย่างไร?",
  ui_story_5033_50331202_74_dialog_content = "หากทุกคนสามารถเงียบสักครู่ได้โปรด ฉันมาที่นี่เพราะฉันมีงานต้องทำในคริสตจักร เมื่อฉันทำเสร็จแล้ว ฉันจะปล่อยให้ทุกคนอยู่คนเดียว",
  ui_story_5033_50331202_75_dialog_content = "ฉันขอแนะนำไม่ให้มีการกระทำที่ผื่นขึ้นก่อนหน้านั้น",
  ui_story_5033_50331202_76_dialog_content = "เว้นแต่ว่าคุณต้องการพบกับ <color=#FFB400>ยมทูต</color>...",
  ui_story_5033_50331301_1_dialog_content = "ก-อะไรนะ... เราควรฟังภิกษุณีคนนั้นดีไหม?",
  ui_story_5033_50331301_2_dialog_content = "มีคนตายไปหลายคนแล้ว ไม่เห็นเหรอ?",
  ui_story_5033_50331301_3_dialog_content = "ถ้าอยากขึ้นไปบนนั้น สบายใจได้... ผมไม่รีบ",
  ui_story_5033_50331301_4_dialog_content = "เธอ... แค่พูดถึง Reaper เหรอ? นั่นหมายความว่าตำนานเหล่านั้นเป็นจริงหรือไม่?",
  ui_story_5033_50331301_5_dialog_content = "ชู่... ถ้าจริง นั่นเป็นชื่อเดียวที่เราไม่ต้องพูดถึง",
  ui_story_5033_50331301_6_dialog_content = "ขอบคุณสำหรับความร่วมมือ.",
  ui_story_5033_50331301_7_dialog_content = "<color=#e8d9bb>ภายในโบสถ์</color>",
  ui_story_5033_50331301_8_dialog_content = "... เกิดอะไรขึ้นกันแน่?",
  ui_story_5033_50331301_9_dialog_content = "<color=#e8d9bb>ดา ดา...</color>",
  ui_story_5033_50331301_10_dialog_content = "หวัดดีครับ...",
  ui_story_5033_50331301_11_dialog_content = "ล้อมวงไว้อย่างแน่นหนา... เจ้าเข้ามาที่นี่ได้อย่างไร?",
  ui_story_5033_50331301_12_dialog_content = "ฉันคุยกับคนข้างนอกและพวกเขาตกลงที่จะให้ฉันผ่าน",
  ui_story_5033_50331301_13_dialog_content = "ฉันไม่สนใจว่าคุณเป็นใคร หรือคุณมาที่นี่ทำไม",
  ui_story_5033_50331301_14_dialog_content = "แต่ได้โปรด ไปเถอะ... ที่นี่ไม่มีเทพเจ้าแห่งแสงแล้ว ซิสเตอร์",
  ui_story_5033_50331301_15_dialog_content = "... คุณไม่รู้จักฉันเหรอ? พอลลักซ์",
  ui_story_5033_50331301_16_dialog_content = "<size=45>คุณ...!</size>",
  ui_story_5033_50331301_17_dialog_content = "มันเป็นเวลานาน.",
  ui_story_5033_50331301_18_dialog_content = "<color=#FFB400>Antares</color> คุณคือ... ไม่... เป็นไปได้ยังไง?",
  ui_story_5033_50331301_19_dialog_content = "ฉันขอโทษ พอลลักซ์ นี่เป็นทางเดียวที่ฉันจะได้พบคุณอีกครั้ง",
  ui_story_5033_50331301_20_dialog_content = "พูดตามตรง ฉันคิดว่าคุณจะลืมฉัน",
  ui_story_5033_50331301_21_dialog_content = "ฉันจะลืมไปได้อย่างไร! ตอนนั้นฉันเป็นคนรับผิดชอบ...",
  ui_story_5033_50331301_22_dialog_content = "อย่ามองฉันผิดแบบนั้น พอลลักซ์ ฉันขอให้คุณ",
  ui_story_5033_50331301_23_dialog_content = "ฉันเอาแต่เล่นมันอยู่ในหัวของฉัน ฉันควรจะพูดอะไรกับคุณถ้าเราได้พบกันอีก ฉันจะเผชิญหน้าคุณอย่างไร",
  ui_story_5033_50331301_24_dialog_content = "แต่ตอนนี้เธอมายืนอยู่ตรงหน้าฉันแล้ว ฉันจำคำพูดไม่ได้แม้แต่คำเดียว",
  ui_story_5033_50331301_25_dialog_content = "คุณพยายามจะพูดอะไร...?",
  ui_story_5033_50331301_26_dialog_content = "ดวงตาของคุณยังคงเหมือนเดิมเมื่อหลายปีก่อน พวกเขาไม่ได้เปลี่ยนแปลง",
  ui_story_5033_50331301_27_dialog_content = "สว่างไสวเหมือนดวงดาว",
  ui_story_5033_50331301_28_dialog_content = "แอน... คุณอยู่เบื้องหลังทุกสิ่ง? แต่ทำไม?",
  ui_story_5033_50331301_29_dialog_content = "แต่มันจะเป็นเช่นนี้ได้อย่างไร? คุณรอดชีวิตมาได้อย่างไร?",
  ui_story_5033_50331301_30_dialog_content = "แล้วทำไมคุณ...แต่งตัวเหมือนแม่ชี?",
  ui_story_5033_50331301_31_dialog_content = "ไม่ต้องกังวล พอลลักซ์ ฉันจะบอกคุณ ฉันจะบอกคุณทุกอย่าง",
  ui_story_5033_50331301_32_dialog_content = "ฉันจะให้เวอร์ชันสั้นแก่คุณตอนนี้... เรามีเวลาไม่มาก",
  ui_story_5033_50331301_33_dialog_content = "<color=#e8d9bb>14 ปีที่แล้ว...</color>",
  ui_story_5033_50331301_34_dialog_content = "ใช่แค่ที่นี่ ตอนนี้จะโยนมันลงในแม่น้ำ",
  ui_story_5033_50331301_35_dialog_content = "ช่างน่าเสียดาย! ในฐานะหนึ่งในราศีเมถุน เธอเพิ่งตายแบบนี้",
  ui_story_5033_50331301_36_dialog_content = "บอสไม่คิดว่าเธอจะเลือกแบบนั้นเหมือนกัน...",
  ui_story_5033_50331301_37_dialog_content = "<color=#e8d9bb>กระเซ็น—</color>",
  ui_story_5033_50331301_38_dialog_content = "โอ้สวรรค์! ดู! ในแม่น้ำ...",
  ui_story_5033_50331301_39_dialog_content = "ช่วยด้วย... มีเด็กอยู่ที่นี่!",
  ui_story_5033_50331301_40_dialog_content = "ดับไฟเร็ว! เธอยังมีชีวิตอยู่! มีคนโทรหาหมอ!",
  ui_story_5033_50331301_41_dialog_content = "อุ้ย...เจ็บ...",
  ui_story_5033_50331301_42_dialog_content = "ฉันยังมีชีวิตอยู่?",
  ui_story_5033_50331301_43_dialog_content = "ใครที่อยู่นอกประตู?",
  ui_story_5033_50331301_44_dialog_content = "มันเป็นเพียงมหึมา ใครสามารถทำเช่นนี้กับเด็ก?",
  ui_story_5033_50331301_45_dialog_content = "เธอแน่ใจว่าจะมีความยืดหยุ่นในการเอาตัวรอดแม้กระทั่งอาการบาดเจ็บแบบนั้น",
  ui_story_5033_50331301_46_dialog_content = "มีอะไรมากกว่านี้ พาเธอไปที่วัดในอัมบราตัน ไม่อยากมีปัญหามากกว่านี้...",
  ui_story_5033_50331301_47_dialog_content = "<color=#e8d9bb>ปัง ปัง ปัง!</color>",
  ui_story_5033_50331301_48_dialog_content = "นี่คือกระดาษของวันนี้ แอนน์",
  ui_story_5033_50331301_49_dialog_content = "มีจดหมายด้วย... แม้ว่าคุณจะไม่มีใครชื่อ <color=#FFB400>Antares</color> ที่นี่ ใช่ไหม",
  ui_story_5033_50331301_50_dialog_content = "ว่าไง",
  ui_story_5033_50331301_51_dialog_content = "... ไม่ ไม่มีใครที่นี่โดยใช้ชื่อนั้น",
  ui_story_5033_50331301_52_dialog_content = "บางทีอาจเป็นชื่อที่ไม่ถูกต้อง คุณสามารถคิดออกสำหรับใคร?",
  ui_story_5033_50331301_53_dialog_content = "ถึงแอนทาเรส",
  ui_story_5033_50331301_54_dialog_content = "ฉันเป็นลูกศิษย์ผู้ศรัทธาของเทพเจ้าแห่งแสง ข้าพเจ้าประสงค์จะกลับใจแทนผู้ที่ทำบาปที่ยกโทษให้ไม่ได้",
  ui_story_5033_50331301_55_dialog_content = "เธอแกล้งทำเป็นตายและหลอกครอบครัวของเธอ ทั้งหมดนี้มีไว้เพื่อที่จะได้รับอิสรภาพที่ผิดพลาด",
  ui_story_5033_50331301_56_dialog_content = "เธอใช้ประโยชน์จากมิตรภาพ ปล่อยให้คนที่รักเธอแบกรับภาระชีวิตแทนเธอและจมดิ่งลงไปในทะเลแห่งความทุกข์ยาก",
  ui_story_5033_50331301_57_dialog_content = "เธอต้องกลับใจจนกว่าจดหมายสารภาพฉบับต่อไปจะมาถึง",
  ui_story_5033_50331301_58_dialog_content = "ใครส่งมาเนี่ย...?",
  ui_story_5033_50331301_59_dialog_content = "สบายดีไหม แอนน์ คุณหน้าซีดแล้ว",
  ui_story_5033_50331301_60_dialog_content = "ขอเก็บจดหมายนี้ไว้ที่นี่ก่อน",
  ui_story_5033_50331301_61_dialog_content = "บางทีคนที่ชื่อ Antares อาจ... มาอ้างสิทธิ์",
  ui_story_5033_50331301_62_dialog_content = "ตลอดหลายปีที่ผ่านมานี้ คุณใช้ชีวิตเป็นภิกษุณี?",
  ui_story_5033_50331301_63_dialog_content = "ถูกต้อง",
  ui_story_5033_50331301_64_dialog_content = "ฉันไม่รู้ว่าใครที่ส่งจดหมายถึงรู้ตัวตนที่แท้จริงของฉัน...",
  ui_story_5033_50331301_65_dialog_content = "แต่ไม่ว่า \"เขา\" จะควบคุมฉันไว้แน่น ไม่กล้าขัดคำสั่งใดๆ",
  ui_story_5033_50331301_66_dialog_content = "แต่คุณไม่กลัวความตาย! จะมีใครมาควบคุมคุณได้อย่างไร? ผีมีจุดอ่อนหรือไม่?",
  ui_story_5033_50331301_67_dialog_content = "ใช่... จุดอ่อนเดียวของฉันคือเพื่อนคนเดียวของฉัน",
  ui_story_5033_50331301_68_dialog_content = "คุณกำลังพูดเพราะฉัน?",
  ui_story_5033_50331301_69_dialog_content = "ใช่. เขาบอกว่าเหตุการณ์นั้นเกือบจะทำลายคุณ แต่ราศีเมถุนต้องดำเนินต่อไป...",
  ui_story_5033_50331301_70_dialog_content = "\"พอลลักซ์ไม่มีค่าถ้าเธอไม่สามารถควงมีดได้อีกต่อไป\"",
  ui_story_5033_50331301_71_dialog_content = "ถ้าข้าไม่ทำตามคำสั่ง เจ้าจะ...",
  ui_story_5033_50331301_72_dialog_content = "ฉันคิดเสมอว่าองค์กรไม่ได้ไล่ตามความล้มเหลวของฉัน เพราะสุริยุปราคาบุก และพวกเขาไม่มีเวลาเหลือ...",
  ui_story_5033_50331301_73_dialog_content = "แต่องค์กรจะไม่ปล่อยให้เราไปง่ายๆ ขนาดนั้น",
  ui_story_5033_50331301_74_dialog_content = "แม้ว่า Euphoria ทั้งหมดจะถูกทำลาย แต่ก็ยังมีคนในองค์กรที่จะจัดการกับเราต่อไป",
  ui_story_5033_50331301_75_dialog_content = "คุณทำสิ่งเหล่านั้นทั้งหมดจริงๆ แอนน์?",
  ui_story_5033_50331301_76_dialog_content = "ฉันไม่มีทางเลือก พอลลักซ์",
  ui_story_5033_50331301_77_dialog_content = "คุณไม่เพียงแต่รอดชีวิตจากการต่อสู้ครั้งนั้น แต่คุณยังสามารถหนีออกจากที่นั่นได้ด้วย",
  ui_story_5033_50331301_78_dialog_content = "ฉันต้องการปกป้องอิสรภาพของคุณ",
  ui_story_5033_50331301_79_dialog_content = "แม้จะไม่ได้ทิ้งยูโฟเรีย แต่ก็มีคนคอยปกป้อง ให้พึ่งพา ใช่ไหม?",
  ui_story_5033_50331301_80_dialog_content = "คุณกำลังพูดถึงเด็ก ๆ หรือไม่?",
  ui_story_5033_50331301_81_dialog_content = "และหญิงสาวที่ถือปืนนั้น เธอดูค่อนข้างพึ่งพาได้",
  ui_story_5033_50331301_82_dialog_content = "เมื่อมีคนแบบนั้นอยู่เคียงข้างคุณ คุณไม่ต้องกลัวอะไร",
  ui_story_5033_50331301_83_dialog_content = "ในขณะที่ฉันไม่เป็นอะไรนอกจาก...",
  ui_story_5033_50331301_84_dialog_content = "ฆ่าซิสเตอร์มาทิลด้าด้วยเหรอ?!",
  ui_story_5033_50331301_85_dialog_content = "...",
  ui_story_5033_50331301_86_dialog_content = "ตอบฉันที แอนน์!",
  ui_story_5033_50331301_87_dialog_content = "ได้สิ",
  ui_story_5033_50331301_88_dialog_content = "ทำไมละ",
  ui_story_5033_50331301_89_dialog_content = "การฆ่าเธอเป็นเพียงคำสั่งเดียวของหลายๆ คน ฉันไม่รู้ด้วยซ้ำว่าทำไมองค์กรถึงมุ่งเป้าไปที่เธอ",
  ui_story_5033_50331301_90_dialog_content = "ฉันขอโทษ พอลลักซ์",
  ui_story_5033_50331301_91_dialog_content = "เธอก็รู้ว่าเธอสำคัญกับฉันแค่ไหน",
  ui_story_5033_50331301_92_dialog_content = "ฉันไม่มีทางเลือก...",
