  ui_story_5033_50331301_94_dialog_content = "ว่าไง",
  ui_story_5033_50331301_95_dialog_content = "อาวุธของคุณ Antares คุณมาต่อหน้าฉัน บอกฉันทั้งหมดนี้ แต่คุณไม่มีอาวุธ ...",
  ui_story_5033_50331301_96_dialog_content = "คุณกำลังเล่นการพนัน ฉันจะไม่ยกมือขึ้นกับคุณ?",
  ui_story_5033_50331301_97_dialog_content = "รู้สึกเหมือนเราเคยมาที่นี่มาก่อน... แม้ว่า Pollux ฉันติดอาวุธ",
  ui_story_5033_50331301_98_dialog_content = "เพราะภารกิจสุดท้ายของฉัน...คือการ <color=#FFB400>ฆ่าคุณ</color>",
  ui_story_5033_50331301_99_dialog_content = "ถ้างั้นจะรออะไรล่ะ?",
  ui_story_5033_50331301_100_dialog_content = "คุณรู้จักฉัน พอลลักซ์ คุณก็รู้ว่าฉันไม่เคยทำอย่างนั้น",
  ui_story_5033_50331301_101_dialog_content = "ไม่ได้มาเพื่อบอกเล่าเรื่องราวเก่าๆ...",
  ui_story_5033_50331301_102_dialog_content = "ฉันจะดูแลสวะนั่นที่ใช้ฉันมาหลายปีแล้ว และกำจัดภัยคุกคามที่อันตรายที่สุดสำหรับคุณในกระบวนการนี้",
  ui_story_5033_50331301_103_dialog_content = "คุณคาดหวังให้ฉันขอบคุณไหม",
  ui_story_5033_50331301_104_dialog_content = "ไม่เลยสักนิด ฉันมาหาเธอครั้งสุดท้ายก่อนจะจากลาอีกครั้ง",
  ui_story_5033_50331301_105_dialog_content = "พอลลักซ์ที่รักของฉัน... ฉันหวังว่าเมื่อเรื่องนี้จบลง คุณจะรู้ว่าต้องทำอะไร",
  ui_story_5033_50331301_106_dialog_content = "เอ่อ...",
