  ui_story_5033_50331301_108_dialog_content = "หลอมรวมมิตรภาพของฉันและมีดของฉันเข้าไปในร่างกายของคุณ ... แม้กระทั่ง \"ตาย\" คุณก็ยังสามารถควบคุมชะตากรรมของฉันได้ ...",
  ui_story_5033_50331301_109_dialog_content = "และตอนนี้คุณยืนอยู่ต่อหน้าฉันอย่างสง่างาม คำพูดของคุณเย่อหยิ่ง",
