  ui_story_5033_50331302_2_dialog_content = "ดีเรามีทุกคน",
  ui_story_5033_50331302_3_dialog_content = "ทุกคนต้องอยู่ที่นี่ไม่หนีไปไหน เข้าใจไหม?",
  ui_story_5033_50331302_4_dialog_content = "ฉันสามารถช่วยได้! พอลลักซ์ สอนวิธีสู้!",
