  ui_story_5033_50331302_6_dialog_content = "ปักหลัก. มันไม่ใช่...",
  ui_story_5033_50331302_7_dialog_content = "เมื่อมันเกิดขึ้น ฉันต้องการยามที่ได้รับการฝึกฝนอยู่ที่นี่ สวรรค์รู้ว่าพวกอันธพาลจะปรากฏตัวหรือไม่",
  ui_story_5033_50331302_8_dialog_content = "ถ้าเพียงแต่พวกคุณสามารถอยู่ที่นี่และคอยดูทางเข้าและทางออกได้ นั่นจะช่วยได้มาก",
  ui_story_5033_50331302_9_dialog_content = "สุดยอด! เดี๋ยวจะรวบรวมหน่วยเฉพาะกิจทันที!!",
  ui_story_5033_50331302_10_dialog_content = "อีกสองสามแผ่นสำหรับตอกตะปูบนหน้าต่างก็ยอดเยี่ยมเช่นกัน",
  ui_story_5033_50331302_11_dialog_content = "โรเจอร์. ไปกันเถอะ ลาตัน!",
  ui_story_5033_50331302_12_dialog_content = "รับทราบ!",
  ui_story_5033_50331302_13_dialog_content = "คุณแน่ใจหรือว่าเด็ก ๆ จะอยู่ที่นี่?",
  ui_story_5033_50331302_14_dialog_content = "มันอันตรายเกินไปที่จะส่งพวกเขาไปที่อื่นในตอนนี้",
  ui_story_5033_50331302_15_dialog_content = "ฉันไม่เคยมีคนจำนวนมากที่นี่พร้อม ๆ กันและฉันไม่รู้ว่าเสบียงของเราจะนานแค่ไหน",
  ui_story_5033_50331302_16_dialog_content = "ไม่ต้องกังวล. เรื่องนี้ไม่ควรใช้เวลานาน",
  ui_story_5033_50331302_17_dialog_content = "กุสตาฟ. คุณอยู่ที่นี่.",
  ui_story_5033_50331302_18_dialog_content = "คิดสิ่งใดสิ่งหนึ่งอย่างรวดเร็ว ก่อนที่ทุกอย่างจะเริ่มต้นขึ้นที่โบสถ์ คุณรู้ทุกอย่างเกี่ยวกับ Euphoria ใช่ไหม?",
  ui_story_5033_50331302_19_dialog_content = "เท่าที่ฟังมา สถานการณ์วิกฤต",
  ui_story_5033_50331302_20_dialog_content = "หลายคนที่อยู่รายรอบโบสถ์มาจากกลุ่มใดกลุ่มหนึ่ง ทั้งหมดที่ฉันต้องทำคือติดต่อกับผู้นำของพวกเขา และฉันควรจะจัดการเรื่องนี้ให้ได้",
  ui_story_5033_50331302_21_dialog_content = "แต่คำถามสำคัญคือจะทำอย่างไรกับพลเรือนทั่วไป",
  ui_story_5033_50331302_22_dialog_content = "ตอนนี้ทุกคนรู้ดีว่าพอลลักซ์กำลังปกป้องคนอัมบราตันในโบสถ์ ฉันเกรงว่าจะใช้เวลามากกว่าสองสามคำที่ดีในการแยกแยะ",
  ui_story_5033_50331302_23_dialog_content = "...",
  ui_story_5033_50331302_24_dialog_content = "คุณคงเป็นเด็กอัมบราตันคนนั้นใช่ไหม",
  ui_story_5033_50331302_25_dialog_content = "ฉันเดาว่าทากิไม่เคยพูดถึงเรากับคุณเลยเหรอ?",
  ui_story_5033_50331302_26_dialog_content = "เขาบอกฉันว่าคุณกำลังจะมา แต่ไม่เคยพูดถึงอาการปวดหัวใหญ่ที่คุณนำมาด้วย",
  ui_story_5033_50331302_27_dialog_content = "ตอนนี้ Euphoria ทุกคนคิดว่า Shadowlord ส่งคุณมาที่นี่เพื่อทำลายสถานที่",
  ui_story_5033_50331302_28_dialog_content = "แต่เรายังไม่ได้ทำอะไรเลย!",
  ui_story_5033_50331302_29_dialog_content = "ฮึ่ม! มันสายไปหน่อยสำหรับคุณที่จะพูดว่าตอนนี้",
  ui_story_5033_50331302_30_dialog_content = "การสืบสวนคือการสืบสวน แต่คุณต้องยั่วยุชาวบ้านและเข้าไปเกี่ยวข้องกับเลือดของเรเวนจริงๆ หรือ?",
  ui_story_5033_50331302_31_dialog_content = "คุณมีความคิดว่าเลือดของ Raven ที่เป็นปฏิปักษ์เป็นอย่างไร?",
  ui_story_5033_50331302_32_dialog_content = "สถานะแก๊งถูกกำหนดโดยความแข็งแกร่งใน Euphoria เสมอ เราไม่ได้ทำอะไรผิดกฎเกณฑ์",
  ui_story_5033_50331302_33_dialog_content = "ฉันเตือนคุณนานแล้วว่าอย่ารุกรานคนมากเกินไป มิฉะนั้น คุณจะเป็นศัตรูกับความขุ่นเคือง แต่ได้ยินไหม?",
  ui_story_5033_50331302_34_dialog_content = "และดูสิว่าเกิดอะไรขึ้น! ตอนนี้แก๊งค์ทั้งหมดได้รวมตัวกันเพื่อล้างพวกคุณออกไป และฉันก็หยุดพวกเขาไม่ได้",
  ui_story_5033_50331302_35_dialog_content = "พอลลักซ์ค่อนข้างฉลาด แอบย่องคุณออกจากที่นั่น พูดถึงเธออยู่ที่ไหน?",
  ui_story_5033_50331302_36_dialog_content = "เธออยู่ข้างหลังในโบสถ์เพื่อซื้อเวลาให้เรา อันที่จริงเราต้องกลับไปหาเธอเดี๋ยวนี้!",
  ui_story_5033_50331302_37_dialog_content = "ไปกันเถอะ! พวกเขาอาจจะทะเลาะกันอยู่แล้ว!",
  ui_story_5033_50331302_38_dialog_content = "ใจเย็นๆ นะคาสต้า ฉันมีบางอย่างต้องบอกคุณก่อน...",
  ui_story_5033_50331302_39_dialog_content = "บุคคลที่อันตรายมากอยู่ที่นี่ใน Euphoria",
  ui_story_5033_50331302_40_dialog_content = "ฉันสงสัยว่าเธอคือคนที่คุณสองคนมาที่นี่เพื่อตามหา",
  ui_story_5033_50331302_41_dialog_content = "คุณหมายถึงกรณีเหล่านั้น...?",
  ui_story_5033_50331302_42_dialog_content = "มีภิกษุณีในหมู่สหายของคุณหรือไม่?",
  ui_story_5033_50331302_43_dialog_content = "ก็ใช่ แต่เธอขอลาไปพักหนึ่ง",
  ui_story_5033_50331302_44_dialog_content = "อย่าบอกนะว่า...",
  ui_story_5033_50331302_45_dialog_content = "เธอฆ่าทหารยามของฉันคนหนึ่ง ที่โบสถ์ เธออยู่ที่นั่นตอนนี้",
  ui_story_5033_50331302_46_dialog_content = "อะไรนะ!",
  ui_story_5033_50331302_47_dialog_content = "แกกำลังบอกฉันเหรอว่าครีปที่ฆ่ามาทิลด้าอยู่ที่โบสถ์ตอนนี้!",
  ui_story_5033_50331302_48_dialog_content = "ใช่. มีลักษณะเด่นเหมือนกับเคส Umbraton ต้องเป็นเธอ",
  ui_story_5033_50331302_49_dialog_content = "เดี๋ยวก่อน คุณรู้ทั้งหมดนี้ได้อย่างไร?",
  ui_story_5033_50331302_50_dialog_content = "ความฉลาดคือขนมปังและเนยของฉัน หนุ่มน้อย",
  ui_story_5033_50331302_51_dialog_content = "นั่นไม่ใช่ทั้งหมดที่ฉันรู้เช่นกัน ฉันเองก็รู้ความลับเล็กๆ น้อยๆ ที่มั่นใจว่าพอลลักซ์คงจะสนใจมาก...",
  ui_story_5033_50331302_52_dialog_content = "“แม่ชี” นั้นไม่ใช่ผู้รับใช้ของเทพแห่งแสง",
  ui_story_5033_50331302_53_dialog_content = "เธอและพอลลักซ์เคยถูกเรียกว่า Gemini ในฐานะสมาชิกขององค์กร และชื่อของเธอคือ <color=#FFB400>Antares</color>",
  ui_story_5033_50331302_54_dialog_content = "เธอว่าไงนะ",
  ui_story_5033_50331302_55_dialog_content = "เดี๋ยว! คนที่คุณกำลังพูดถึงคนตายไม่ใช่เหรอ?",
  ui_story_5033_50331302_56_dialog_content = "ถูกตัอง! มันเป็นไปไม่ได้. พอลลักซ์ ชัดเจน...",
  ui_story_5033_50331302_57_dialog_content = "ฉันแค่สงสัยเหมือนคุณเมื่อข้อมูลนี้มาถึงหูของฉันครั้งแรก แต่ฉันรับรองกับคุณว่ามันเป็นเรื่องจริง",
  ui_story_5033_50331302_58_dialog_content = "เธอไม่เพียงแต่รอดชีวิต แต่เธอยังรวบรวมกำลังมาหลายปี และตอนนี้ เธอตัดสินใจที่จะแก้แค้น Euphoria",
  ui_story_5033_50331302_59_dialog_content = "เรารออะไรอยู่? พอลลักซ์ต้องเจอปัญหา!",
  ui_story_5033_50331302_60_dialog_content = "ใช่... ถ้าเธอฆ่าคนได้โดยไม่กระพริบตา ฉันนึกไม่ออกว่าเธอจะทำอะไรได้อีก...",
  ui_story_5033_50331302_61_dialog_content = "เราไม่สามารถปล่อยให้เธอก่อปัญหาต่อไปได้",
  ui_story_5033_50331302_62_dialog_content = "แน่ใจนะว่ากุสตาฟ?",
  ui_story_5033_50331302_63_dialog_content = "ฟังนะ เด็กน้อย ฉันบอกคุณแล้วว่าจะหาคนที่คุณตามหาได้ที่ไหน คุณจะจับเธอได้หรือไม่นั้นขึ้นอยู่กับคุณ",
  ui_story_5033_50331302_64_dialog_content = "ที่ระเบิด...",
  ui_story_5033_50331302_65_dialog_content = "ทำไมคุณไม่ไปกับพวกเขา กุสตาฟ? คุณอาจต้องจับสถานการณ์ให้ได้ เนื่องจากเป็นการยากสำหรับพวกเขาที่จะต่อสู้กับ Antares...",
  ui_story_5033_50331302_66_dialog_content = "ฮ่าฮ่าฮ่า คุณไม่จำเป็นต้องกังวลว่าฉันจะเข้าใจสถานการณ์ ปล่อยให้ฉัน.",
  ui_story_5033_50331302_67_dialog_content = "คุณแค่โฟกัสที่การตามหาฆาตกรและเปิดเผยความจริงให้ทุกคนรู้",
  ui_story_5033_50331302_68_dialog_content = "ฉันจะพยายามช่วยระงับความโกรธที่ Euphoria มีต่อเธอ...",
  ui_story_5033_50331401_1_dialog_content = "<color=#e8d9bb>*ดังก้อง...*</color>",
  ui_story_5033_50331401_2_dialog_content = "นั่นเป็นระเบิดเหรอ? หรือฟ้าร้อง?",
  ui_story_5033_50331401_3_dialog_content = "เร่งจังหวะเลย คาเอเลสไทต์ คุณช้ากว่ากระดูกเก่าเหล่านี้อย่างไร?",
  ui_story_5033_50331401_4_dialog_content = "ผมเสียใจด้วยจริง ๆ...",
  ui_story_5033_50331401_5_dialog_content = "ฉันต้องการคุยกับคุณ แคสต้า",
