  ui_story_5033_50331401_7_dialog_content = "เธอต้องตาย",
  ui_story_5033_50331401_8_dialog_content = "เธอ...",
  ui_story_5033_50331401_9_dialog_content = "คาสต้า ฉันรู้ว่าคุณกับพอลลักซ์ โกรธมาทิลด้า",
  ui_story_5033_50331401_10_dialog_content = "แต่ฉันไม่คิดว่านี่เป็นสถานการณ์ง่ายๆ คุณเคยคิดบ้างไหมว่าทำไมเธอถึงทำทั้งหมดนี้?",
  ui_story_5033_50331401_11_dialog_content = "เพราะเธอต้องการแก้แค้น Pollux และ Euphoria ทั้งหมดสำหรับ \"ความตาย\" ของเธอ",
  ui_story_5033_50331401_12_dialog_content = "เป็นไปได้ แต่ทำไมตอนนี้หลังจากหลายปี?",
  ui_story_5033_50331401_13_dialog_content = "ฉันไม่สามารถพูดได้",
  ui_story_5033_50331401_14_dialog_content = "ทำไมถึงก่ออาชญากรรมที่มีชื่อเสียงมากมาย แล้วจึงไปหาพอลลักซ์?",
  ui_story_5033_50331401_15_dialog_content = "ไม่รู้สิ",
  ui_story_5033_50331401_16_dialog_content = "และทำไม...",
  ui_story_5033_50331401_17_dialog_content = "<size=45>ไม่รู้และไม่อยากรู้!</size>",
  ui_story_5033_50331401_18_dialog_content = "พอลลักซ์เคยฆ่าเธอครั้งหนึ่ง เธอจึงฆ่าซิสเตอร์มาทิลด้า ผู้ช่วยพอลลักซ์",
  ui_story_5033_50331401_19_dialog_content = "นำความสงสัยทั้งหมดมาสู่ Pollux แล้วกลับมาที่ Euphoria ขณะที่คุณกำลังติดตามอยู่",
  ui_story_5033_50331401_20_dialog_content = "ยากไหมที่จะเข้าใจว่านี่คือการแก้แค้น Pollux ทั้งหมด?",
  ui_story_5033_50331401_21_dialog_content = "ใจเย็นก่อน แล้วคิดว่าพอลลักซ์จะทำอะไร!",
  ui_story_5033_50331401_22_dialog_content = "พอลลักซ์ไม่ปกปิด Antares!",
  ui_story_5033_50331401_23_dialog_content = "เธอจะทำในสิ่งที่ฉันต้องการ - ตัดเธอเป็นชิ้น ๆ !",
  ui_story_5033_50331401_24_dialog_content = "คาสต้า!",
  ui_story_5033_50331401_25_dialog_content = "เฮ้ยอย่ากินมัน! คายมันออกมา...",
  ui_story_5033_50331401_26_dialog_content = "<color=#e8d9bb>ดิงดอง ดิงดอง—</color>",
  ui_story_5033_50331401_27_dialog_content = "ฟังนะ เธอห้ามกินนี่ เข้าใจไหม ตอนนี้วิ่งไปเล่นที่อื่น",
  ui_story_5033_50331401_28_dialog_content = "วุ้ย... ในที่สุดก็จัดการเจ้าตัวเล็กได้แล้ว",
  ui_story_5033_50331401_29_dialog_content = "<color=#e8d9bb>ก๊อก ก๊อก ก๊อก!</color>",
  ui_story_5033_50331401_30_dialog_content = "นั่นใครน่ะ?",
  ui_story_5033_50331401_31_dialog_content = "เปิดประตูเร็วเข้า! ฉันเอโฮ สายลับพิเศษ Umbraton Courier Union!",
  ui_story_5033_50331401_32_dialog_content = "คุณทำให้ฉันกลัวแทบตาย! คุณมาทำอะไรที่นี่? คุณมีแพ็คเกจของฉันไหม",
  ui_story_5033_50331401_33_dialog_content = "อืม การจัดส่งด่วนมากจาก Umbraton!",
  ui_story_5033_50331401_34_dialog_content = "เอาไว้ลงได้มั้ย! ให้ที่นี่.",
  ui_story_5033_50331401_35_dialog_content = "<color=#e8d9bb>*เปิดกระดาษ*</color>",
  ui_story_5033_50331401_36_dialog_content = "“นี่ทากิ ฉันติดต่อคอแรกซ์ไม่ได้ เลยลองเสี่ยงดวงกับนายดู”",
  ui_story_5033_50331401_37_dialog_content = "“เหยื่อรายหนึ่งรอดชีวิตจากฆาตกรต่อเนื่อง และเขาฟื้นแล้ว คุณต้องบอกคอแรกซ์ทันที...”",
  ui_story_5033_50331401_38_dialog_content = "“ผู้ต้องสงสัยเป็นภิกษุณี ผมหงอก ตาสีเทา รูปภาพอยู่ด้านล่าง...”",
  ui_story_5033_50331401_39_dialog_content = "“แต่เธอไม่ใช่ผู้บงการ! ยังมีคนคอยดึงสายของเธออยู่!”",
  ui_story_5033_50331401_40_dialog_content = "ว่าไง",
  ui_story_5033_50331401_41_dialog_content = "<size=42>\"นี่ <color=#FFB400>กุสตาฟ</color>!\"</size>",
  ui_story_5033_50331401_42_dialog_content = "<size=42>\"เบื้องหลัง มีแต่ <color=#FFB400>กุสตาฟ</color>!\"</size>",
  ui_story_5033_50331401_43_dialog_content = "การชดใช้? แบ่งปัน? มาทำอะไรที่นี่กันแน่...?",
  ui_story_5033_50331401_44_dialog_content = "ฉันมาที่นี่เพียงเพราะอยากบอกคุณว่า ฉันรู้แล้วว่าใครเป็นคนชักใยอยู่เบื้องหลังทั้งหมดนี้",
  ui_story_5033_50331401_45_dialog_content = "รอให้ฉันทำเขาเสร็จ แล้วฉันจะให้ชีวิตคุณกลับคืนมา",
  ui_story_5033_50331401_46_dialog_content = "ฉันเป็นหนี้สิ่งนี้กับคุณ",
  ui_story_5033_50331401_47_dialog_content = "ฉันไม่ต้องการมัน! ฉันจะมอบตัวนายให้อัมบราตัน",
  ui_story_5033_50331401_48_dialog_content = "เกรงว่าจะไม่เกิด... ข้าพเจ้าไม่อยากตายด้วยมือใครนอกจากของท่าน",
  ui_story_5033_50331401_49_dialog_content = "จะบ้าเหรอ?!",
  ui_story_5033_50331401_50_dialog_content = "ทำไมถึงใช่! ฉันบ้ามานานแล้ว",
  ui_story_5033_50331401_51_dialog_content = "ตั้งแต่ฉันเกิดมาเป็นลูกของ Euphoria... ตั้งแต่ฉันเข้าร่วมองค์กรนั้น...",
  ui_story_5033_50331401_52_dialog_content = "เท่าที่ฉันกังวล การฆ่าเป็นธรรมชาติพอๆ กับการหายใจ",
  ui_story_5033_50331401_53_dialog_content = "ฉันไม่เคยตื่นเลยจริงๆ",
  ui_story_5033_50331401_54_dialog_content = "กว่าฉันจะเจอเพื่อนคนแรกของฉัน... เธอเป็นเหมือนดาวนำทางของฉันที่ชี้ทางให้ฉัน...",
  ui_story_5033_50331401_55_dialog_content = "ปิดมัน! วินาทีที่คุณฆ่าซิสเตอร์มาทิลด้า เราสูญเสียโอกาสที่จะเป็นเพื่อนกัน",
  ui_story_5033_50331401_56_dialog_content = "ไม่... วินาทีที่ฉันหยิบมีดขึ้นมาหาเธอ เธอไม่ใช่เพื่อนของฉัน",
  ui_story_5033_50331401_57_dialog_content = "ไม่ พอลลักซ์ นั่นเป็นความผิดขององค์กร! กุสตาฟต้องโทษทุกอย่าง...",
  ui_story_5033_50331401_58_dialog_content = "ทุกอย่างจะจบลง ตราบใดที่มันหายไป",
  ui_story_5033_50331401_59_dialog_content = "<size=45>กุสตาฟ?!</size>",
  ui_story_5033_50331401_60_dialog_content = "ใช่. อย่างที่ฉันพูดไป ในที่สุดฉันก็ค้นพบว่าใครเป็นผู้อยู่เบื้องหลัง",
  ui_story_5033_50331401_61_dialog_content = "กุสตาฟ... เขาเป็นส่วนหนึ่งขององค์กรและเคยเป็นมือขวาของบอส",
  ui_story_5033_50331401_62_dialog_content = "เขาเป็นสมาชิกจริงๆเหรอ?",
  ui_story_5033_50331401_63_dialog_content = "คุณมีหลักฐานอะไรไหม?",
  ui_story_5033_50331401_64_dialog_content = "ฉันเสียใจที่จะบอกว่าฉันไม่ได้",
  ui_story_5033_50331401_65_dialog_content = "ทั้งหมดนี้เป็นคำให้การที่ได้ยินจากปากของคนที่กำลังจะตาย",
  ui_story_5033_50331401_66_dialog_content = "<color=#e8d9bb>ขัดข้อง—</color>",
  ui_story_5033_50331401_67_dialog_content = "<size=45>อยู่นี่แล้ว Antares!!</size>",
  ui_story_5033_50331401_68_dialog_content = "เอ่อ...",
  ui_story_5033_50331401_69_dialog_content = "พอลลักซ์ โอเคมั้ย!",
  ui_story_5033_50331401_70_dialog_content = "ฉันสบายดี. แล้วเด็กล่ะ? คุณได้รับพวกเขาปลอดภัย?",
  ui_story_5033_50331401_71_dialog_content = "ผู้หญิงคนนี้ไม่ใช่แม่ชี! เธอฆ่าซิสเตอร์มาทิลด้า!",
  ui_story_5033_50331401_72_dialog_content = "ถ้าคุณไม่ล้างแค้นเธอ ฉันจะทำ!",
  ui_story_5033_50331401_73_dialog_content = "*แค่ก*",
  ui_story_5033_50331401_74_dialog_content = "<size=45>คุณฆ่ามาทิลด้า...!!</size>",
  ui_story_5033_50331401_75_dialog_content = "คาสต้า คุณ...",
  ui_story_5033_50331401_76_dialog_content = "ไม่เป็นไร พอลลักซ์ เป็นเด็กที่มีความหวังมากจริงๆ...",
  ui_story_5033_50331401_77_dialog_content = "<size=45>อาวุธของคุณอยู่ที่ไหน! วาดเลย!</size>",
  ui_story_5033_50331401_78_dialog_content = "<size=45>ฉันจะจ่ายให้คุณ...เพื่อมาทิลด้า!</size>",
  ui_story_5033_50331401_79_dialog_content = "คุณ... คุณเห็นไหม มันเร็วมาก มันพุ่งทะลุกำแพงเลย!",
  ui_story_5033_50331401_80_dialog_content = "ดู! กุสตาฟมาแล้ว!",
  ui_story_5033_50331401_81_dialog_content = "ขอโทษที่มาช้านะคะทุกคน",
  ui_story_5033_50331401_82_dialog_content = "กุสตาฟครับท่าน! บอกเราว่าต้องทำอย่างไร ได้โปรด! Pollux มีขยะ Umbraton เหล่านั้น ...",
  ui_story_5033_50331401_83_dialog_content = "ทุกคนใจเย็นๆ ฉันจะอธิบายทุกอย่างให้คุณฟังในอีกสักครู่",
  ui_story_5033_50331401_84_dialog_content = "แต่ก่อนหน้านั้น ให้คนพวกนี้ผ่านพ้นไป",
  ui_story_5033_50331401_85_dialog_content = "...",
  ui_story_5033_50331401_86_dialog_content = "ฮะ? ฮะ?!",
  ui_story_5033_50331401_87_dialog_content = "คุณมาทำอะไรที่นี่? คุณปรากฏตัวเมื่อไหร่?",
  ui_story_5033_50331401_88_dialog_content = "เราต้องไปที่คริสตจักร PlayerName! Casta สูญเสียการควบคุม!",
  ui_story_5033_50331401_89_dialog_content = "<color=#e8d9bb>ปัง ปัง!</color>",
  ui_story_5033_50331401_90_dialog_content = "Casta... นั่นคือชื่อของคุณใช่มั้ย?",
  ui_story_5033_50331401_91_dialog_content = "<size=45>สู้กลับ! คุณคิดว่าคุณกำลังดูถูกใครอยู่! โต้กลับ!</size>",
  ui_story_5033_50331401_92_dialog_content = "ฉันยังต้องการเวลาที่จะสรุปสิ่งต่าง ๆ ดังนั้นฉันจึงเกรงว่าฉันจะพินาศที่นี่ไม่ได้ แต่ข้าจะไม่มีวันยกมือขึ้นสู้เจ้า...",
  ui_story_5033_50331401_93_dialog_content = "เห็นว่าคุณมีความสำคัญต่อพอลลักซ์...",
  ui_story_5033_50331401_94_dialog_content = "...",
  ui_story_5033_50331401_95_dialog_content = "ห้ามพูดชื่อนั้นนะฆาตกร!",
  ui_story_5033_50331401_96_dialog_content = "หยุด คาสต้า!",
  ui_story_5033_50331401_97_dialog_content = "<size=45>ออกไปจากที่นี่!</size>",
  ui_story_5033_50331401_98_dialog_content = "ฉันจะไม่ยอมให้คุณทำลายภารกิจของฉัน... นี่คือพระราชกฤษฎีกาสูงสุดของ Shadowlord!",
  ui_story_5033_50331401_99_dialog_content = "เธอจะต้องถูกเอาชีวิตกลับมาให้ได้!",
  ui_story_5033_50331401_100_dialog_content = "<size=45>ฉันบอกให้ออกไปจากที่นี่!!</size>",
  ui_story_5033_50331401_101_dialog_content = "ช่วยฉันควบคุมเธอที PlayerName!",
  ui_story_5033_50331402_1_dialog_content = "<color=#e8d9bb>หวือหวา! ตูม!</color>",
  ui_story_5033_50331402_2_dialog_content = "คุณ...ขยะ...",
  ui_story_5033_50331402_3_dialog_content = "ฉันเสียใจ. ฉันต้องต่อสู้อย่างจริงจังเพื่อหยุดคุณ",
  ui_story_5033_50331402_4_dialog_content = "ฆาตกร! ที่นี่! ฆาตกรอยู่ที่นี่!",
  ui_story_5033_50331402_5_dialog_content = "ก็พอแล้ว คาสต้า",
  ui_story_5033_50331402_6_dialog_content = "ใจเย็น?",
  ui_story_5033_50331402_7_dialog_content = "พอลลักซ์ เธอฆ่ามาทิลด้า...",
  ui_story_5033_50331402_8_dialog_content = "เข้าใจแล้ว",
  ui_story_5033_50331402_9_dialog_content = "เธอฆ่ามาทิลด้า...",
  ui_story_5033_50331402_10_dialog_content = "และฉันจะล้างแค้นให้เธอ ไม่ใช่วันนี้",
  ui_story_5033_50331402_11_dialog_content = "ใช่ ฉันจะชดใช้... เมื่อทั้งหมดนี้จบลง",
  ui_story_5033_50331402_12_dialog_content = "ถ้าใครจะไปปลิดชีพแอน ก็คงเป็นฉันเอง คุณเข้าใจไหม?",
  ui_story_5033_50331402_13_dialog_content = "เรามีความเข้าใจ เธอและฉัน",
  ui_story_5033_50331402_14_dialog_content = "พอลลักซ์...",
  ui_story_5033_50331402_15_dialog_content = "แอน ไม่ แอนทาเรส",
  ui_story_5033_50331402_16_dialog_content = "เจอกันอีกแล้ว PlayerName, คอแร็กซ์.",
  ui_story_5033_50331402_17_dialog_content = "สิ่งที่คุณทำทั้งหมดนั้น Antares?",
  ui_story_5033_50331402_18_dialog_content = "คุณรับผิดชอบต่อการตายของซิสเตอร์มาทิลด้าเหรอ?",
  ui_story_5033_50331402_19_dialog_content = "ดูเหมือนคุณจะเข้าใจทุกอย่างแล้ว",
  ui_story_5033_50331402_20_dialog_content = "ใช่แล้ว ฉันคือคนที่คุณกำลังมองหา",
  ui_story_5033_50331402_21_dialog_content = "เกลียดที่จะทำลายมันให้กับคุณ แต่ฉันไม่ใช่แม่ชีจริงๆด้วย ฉันขอโทษที่หลอกลวงคุณ",
  ui_story_5033_50331402_22_dialog_content = "ทำไม... ทำไมคุณถึงฆ่าคนพวกนั้น? และทำไมคุณถึงมาที่นี่?",
  ui_story_5033_50331402_23_dialog_content = "<size=42>อะไรนะ! จริงหรอ!</size>",
  ui_story_5033_50331402_24_dialog_content = "ทำไมคนพวกนั้นถึงกลับมาโวยวายกันอีก? กุสตาฟไม่ได้ตั้งใจจะควบคุมเหรอ?",
  ui_story_5033_50331402_25_dialog_content = "เดี๋ยวก่อน คุณเห็นเขาไหม",
  ui_story_5033_50331402_26_dialog_content = "ใช่ เขามากับเรา",
  ui_story_5033_50331402_27_dialog_content = "แล้วตอนนี้เขาอยู่ที่ไหน?",
  ui_story_5033_50331402_28_dialog_content = "ฉันไม่รู้. เขาไม่ได้มากับเรา",
  ui_story_5033_50331402_29_dialog_content = "เขาอันตราย! เขาเป็นผู้บงการเบื้องหลังทั้งหมดนี้!",
  ui_story_5033_50331402_30_dialog_content = "อะไร บงการ?",
  ui_story_5033_50331402_31_dialog_content = "ฉันอธิบายได้นะ พอลลักซ์",
  ui_story_5033_50331402_32_dialog_content = "คุณกำลังพูดของจริง กุสตาฟ?",
  ui_story_5033_50331402_33_dialog_content = "ถูกตัอง. เธอเป็นเพื่อนสนิทของพอลลักซ์... Antares",
  ui_story_5033_50331402_34_dialog_content = "คงจะสยดสยองที่คบกับคนแบบนั้น... ทำไมเธอถึงทำอย่างนี้ล่ะ?",
  ui_story_5033_50331402_35_dialog_content = "ทำไมถึงจงใจสร้างปัญหากับอัมบราตัน!",
  ui_story_5033_50331402_36_dialog_content = "เธอต้องใช้มันเป็นข้ออ้างในการเข้ายึดกลุ่มกำไรของ Euphoria และ Umbraton",
  ui_story_5033_50331402_37_dialog_content = "รวมทั้งพวกนักสืบของอัมบราตันด้วย พวกเขาอาจจะแค่แสดงมันออกมา",
  ui_story_5033_50331402_38_dialog_content = "ฉันจะไม่แปลกใจถ้าทุกอย่างใน Euphoria มีราคาอยู่แล้วและพร้อมสำหรับการคว้า",
  ui_story_5033_50331402_39_dialog_content = "แต่ทำไมพวกเขาถึงมาสู้กันที่นี่? มันเป็นความขัดแย้งภายในบางอย่างหรือไม่?",
  ui_story_5033_50331402_40_dialog_content = "ขอโทษนะทุกคน ฉันขอโทษ แต่ฉันมีเรื่องจะคุยกับคุณกุสตาฟ",
  ui_story_5033_50331402_41_dialog_content = "แล้วยังไงเหรอ",
  ui_story_5033_50331402_42_dialog_content = "ทั้ง Pollux และ Casta ไม่สามารถดูแล Antares ได้",
  ui_story_5033_50331402_43_dialog_content = "พวกเขาไม่สามารถ? หรือเพียงแค่ล่าช้า?",
  ui_story_5033_50331402_44_dialog_content = "ฉันขอโทษ ฉันไม่สามารถพูดได้อย่างแน่นอน",
  ui_story_5033_50331402_45_dialog_content = "เป็นไปไม่ได้... ระดับของความเกลียดชังและความเกลียดชังนั้น... เป็นไปได้อย่างไร... คุณแน่ใจในเรื่องนี้หรือไม่?",
  ui_story_5033_50331402_46_dialog_content = "อย่างน้อยที่สุด Antares ยังมีชีวิตอยู่ และ...",
  ui_story_5033_50331402_47_dialog_content = "ถึงเวลาแล้วล่ะครับ",
  ui_story_5033_50331402_48_dialog_content = "ดูเหมือนว่าเธอจะบอกพวกเขาทุกอย่างแล้ว",
  ui_story_5033_50331402_49_dialog_content = "ดูเหมือนว่าสิ่งต่างๆจะไม่เลวร้ายไปกว่านี้อีกแล้ว ...",
  ui_story_5033_50331402_50_dialog_content = "แล้วก้าวต่อไปของเราจะเป็นอย่างไร?",
  ui_story_5033_50331402_51_dialog_content = "ก้าวต่อไป...",
  ui_story_5033_50331402_52_dialog_content = "<color=#e8d9bb>*Rumble—*</color>",
  ui_story_5033_50331402_53_dialog_content = "ฉันรู้แค่ว่าการเคลื่อนไหวครั้งสุดท้ายของเราจะเป็นอย่างไร",
  ui_story_5033_50331402_54_dialog_content = "บอกทุกคนว่าถึงเวลาต้องทำเช่นนี้แล้ว",
  ui_story_5033_50331402_55_dialog_content = "ถ้าเราไม่จัดการกับ Raven's Blood ที่นี่ ตอนนี้ Euphoria จะไม่มีวันสงบสุข",
  ui_story_5033_50331501_1_dialog_content = "พอลลักซ์! ออกมาที่นี่! เจ้าทรยศต่อ Euphoria!",
  ui_story_5033_50331501_2_dialog_content = "พอลลักซ์! พอลลักซ์!",
  ui_story_5033_50331501_3_dialog_content = "ปอ...",
  ui_story_5033_50331501_4_dialog_content = "ว้าว! เธอ... เธอออกมาจริงๆ...",
  ui_story_5033_50331501_5_dialog_content = "ใครเรียกฉัน?",
  ui_story_5033_50331501_6_dialog_content = "...",
  ui_story_5033_50331501_7_dialog_content = "อะไร ในที่สุดคุณกล้าแสดงใบหน้าของคุณ?",
  ui_story_5033_50331501_8_dialog_content = "คุณดูดีนะ กุสตาฟ ฉันคิดว่าจินและยาชูกำลังประจำวันของคุณต้องขอบคุณ",
  ui_story_5033_50331501_9_dialog_content = "ไม่เชิง. พวกเขาแค่ทำให้ฉันชา เพราะ Euphoria นี้มีความผิดหวังมากพอแล้วใช่ไหม",
  ui_story_5033_50331501_10_dialog_content = "คุณไม่ได้วิ่ง ฉันค่อนข้างชื่นชมที่",
  ui_story_5033_50331501_11_dialog_content = "แล้วฉันจะวิ่งไปทำไม? ฉันมาที่นี่เพื่อดูแลทุกอย่าง ท้ายที่สุด Euphoria ต้องการคนที่สามารถดูแลได้",
  ui_story_5033_50331501_12_dialog_content = "<color=#e8d9bb>ดา ดา—</color>",
  ui_story_5033_50331501_13_dialog_content = "นี่แม่ชีเหรอ!",
  ui_story_5033_50331501_14_dialog_content = "กลับไปซะ กุสตาฟบอกว่าเธอเป็นคนบ้า...",
  ui_story_5033_50331501_15_dialog_content = "ทุกคน ให้ฉันแนะนำคุณกับใครซักคน",
  ui_story_5033_50331501_16_dialog_content = "ฆาตกรต่อเนื่องของ Umbraton คนบาปแห่ง Euphoria และอดีตสมาชิกองค์กร Gemini—Antares",
  ui_story_5033_50331501_17_dialog_content = "...",
  ui_story_5033_50331501_18_dialog_content = "อะ-อะไร? สารภาพอย่างง่ายดาย?",
  ui_story_5033_50331501_19_dialog_content = "นั่นคือพอลลักซ์สำหรับคุณ ทำตัวน่าชื่นชมแม้ในสถานการณ์ที่สิ้นหวังเช่นนี้",
  ui_story_5033_50331501_20_dialog_content = "แล้วคุณล่ะ ในฐานะผู้บงการที่อยู่เบื้องหลังทั้งหมดนี้ มันจะง่ายกว่าถ้าคุณเพียงแค่สารภาพเช่นกัน",
  ui_story_5033_50331501_21_dialog_content = "ดูเหมือนว่าคุณจะเขียนเรื่องราวทั้งหมดแล้ว กุสตาฟ",
  ui_story_5033_50331501_22_dialog_content = "น่าเสียดายที่นักโทษของฉันที่นี่มีคำสารภาพที่แตกต่างออกไป คุณต้องการที่จะได้ยิน?",
  ui_story_5033_50331501_23_dialog_content = "ผู้มีเกียรติแห่ง Euphoria! คุณต้องการที่จะรู้ความจริง?",
  ui_story_5033_50331501_24_dialog_content = "สุภาพบุรุษผู้นี้ต่อหน้าคุณ กุสตาฟ ไม่ได้เป็นเพียงผู้รอบรู้ในความอิ่มเอิบ...",
  ui_story_5033_50331501_25_dialog_content = "เขายังเป็นอดีตเจ้าหน้าที่ระดับสูงในองค์กรอีกด้วย",
  ui_story_5033_50331501_26_dialog_content = "องค์กร? หมายความว่า... องค์กรที่บอสจัดการเมื่อสิบกว่าปีที่แล้วหรือเปล่า?",
  ui_story_5033_50331501_27_dialog_content = "นั่นมันกลุ่มที่เลี้ยงนักฆ่าไม่ใช่หรือ? กุสตาฟเป็นแค่หน่วยข่าวกรองธรรมดาๆ ใช่ไหม?",
  ui_story_5033_50331501_28_dialog_content = "องค์กรล่มสลายเมื่อ 12 ปีที่แล้ว ต้องขอบคุณการบุกรุกของ Eclipsite แต่สำหรับกุสตาฟที่นี่ นี่เป็นโอกาสทอง",
  ui_story_5033_50331501_29_dialog_content = "ด้วยการใช้อัตลักษณ์ของสำนักข่าวกรอง เขาเริ่มติดพันและเอาชนะพวกแก๊ง และสร้างระเบียบขึ้นใหม่ โดยพยายามจะค่อยๆ เข้ายึดครองยูโฟเรีย",
  ui_story_5033_50331501_30_dialog_content = "แต่ที่สำคัญกว่านั้น เขายังจับอาวุธร้ายแรง...",
  ui_story_5033_50331501_31_dialog_content = "<color=#FFB400>แอนทาเรส</color>",
  ui_story_5033_50331501_32_dialog_content = "อะไร แม่ชีทำงานให้กุสตาฟ?",
  ui_story_5033_50331501_33_dialog_content = "ในช่วงหลายปีที่ผ่านมา Antares ได้ดำเนินการตามคำสั่งของเขา โดยกำจัดใครก็ตามที่ยังคงควบคุมห่วงโซ่กำไรของ Euphoria ออกไป",
  ui_story_5033_50331501_34_dialog_content = "ความโกรธของอัมบราตันจำเป็นต้องมีแพะรับบาป ดังนั้นคำสั่งสุดท้ายของเขาคือให้แอนกลับมาที่นี่ เพื่อฆ่าฉัน...",
  ui_story_5033_50331501_35_dialog_content = "หรือจะให้พวกเราฆ่ากันเอง",
  ui_story_5033_50331501_36_dialog_content = "อืม... ฉันเห็นว่ามันสมเหตุสมผลดี",
  ui_story_5033_50331501_37_dialog_content = "ไม่ไม่! เรามีคำพูดของเธอเท่านั้น!",
  ui_story_5033_50331501_38_dialog_content = "แต่กุสตาฟก็เหมือนกันไม่ใช่เหรอ? เราไม่ควรเชื่อเขาอย่างสุ่มสี่สุ่มห้าเช่นกัน เพียงเพราะเขาบริหารหน่วยข่าวกรอง...",
  ui_story_5033_50331501_39_dialog_content = "แดร็ก... เราเคยเล่นกันจริงๆ เหรอ?",
  ui_story_5033_50331501_40_dialog_content = "<size=45>พอลลักซ์! พอแล้ว!</size>",
  ui_story_5033_50331501_41_dialog_content = "คนดีเหล่านี้ไม่ใช่คนโง่! พวกเขาจะไม่ถูกหลอกโดยคำโกหกของคุณ",
  ui_story_5033_50331501_42_dialog_content = "คุณแค่ต้องการโยนฉันลงใต้รถ และทำให้ฉันต้องโทษที่บงการทั้งหมดนี้",
  ui_story_5033_50331501_43_dialog_content = "คุณรู้ดีว่าคุณทำอะไรลงไป และคุณจะต้องจ่ายเงินให้กับมัน แม้จะไม่มีหลักฐานที่แน่ชัด!",
  ui_story_5033_50331501_44_dialog_content = "ฟังสิ่งที่คุณพูดซิน้องสาว ฉันรู้สึกอับอายสำหรับคุณ",
  ui_story_5033_50331501_45_dialog_content = "ถ้าหลังของคุณพิงกำแพง และสุดท้ายคุณตั้งใจจะฆ่าฉัน คนแก่ มาที่ฉันสิ!",
  ui_story_5033_50331501_46_dialog_content = "แต่ฉันจะไม่หนี ถ้าคุณสามารถสร้างหลักฐานได้",
  ui_story_5033_50331501_47_dialog_content = "<size=45>ฉันมีหลักฐาน!</size>",
  ui_story_5033_50331501_48_dialog_content = "ฉันมีหลักฐาน! ที่นี่!",
  ui_story_5033_50331501_49_dialog_content = "เนโกะยาชิกิ?!",
  ui_story_5033_50331501_50_dialog_content = "...?!",
  ui_story_5033_50331501_51_dialog_content = "ถอยไป พวกแกทุกคน ไปให้พ้น!",
  ui_story_5033_50331501_52_dialog_content = "คุณต้องการหลักฐานไหม กุสตาฟ? ฉันมีหลักฐานของคุณที่นี่!",
  ui_story_5033_50331501_53_dialog_content = "นี่เพิ่งมาจากอัมบราตัน คำให้การของผู้รอดชีวิต!",
  ui_story_5033_50331501_54_dialog_content = "ก... ผู้รอดชีวิต?!",
  ui_story_5033_50331501_55_dialog_content = "...",
  ui_story_5033_50331501_56_dialog_content = "ฆาตกรเป็นแม่ชี—เธอ! และผู้ที่จัดการมันทั้งหมด วางแผนไว้ทั้งหมด—",
  ui_story_5033_50331501_57_dialog_content = "<size=45>ไม่ใช่ใครอื่นนอกจากคุณ กุสตาฟ!</size>",
  ui_story_5033_50331501_58_dialog_content = "ไม่มีทาง... เป็นไปไม่ได้... ไม่มีทางที่ใครจะรอดได้!",
  ui_story_5033_50331501_59_dialog_content = "นี่เป็นหลักฐานปลอม!",
  ui_story_5033_50331501_60_dialog_content = "นี่เป็นข้อมูลเท็จ! แกมารุมตีฉันงั้นเหรอ!",
  ui_story_5033_50331501_61_dialog_content = "\"จิมมี่ โอเดนเคิร์ก วัย 47 ปี ฟื้นจากโคม่าอย่างร้ายแรง...\"",
  ui_story_5033_50331501_62_dialog_content = "\"... ตามคำอธิบาย ผู้ต้องสงสัยแต่งตัวเป็นภิกษุณี ผมหงอก...\"",
  ui_story_5033_50331501_63_dialog_content = "พอได้แล้ว...",
  ui_story_5033_50331501_64_dialog_content = "\"วันนั้นฉันได้รับเชิญจากกุสตาฟแห่งยูโฟเรีย... เราเดินเข้าไปในกับดัก แต่ไม่มีคนมาช่วยเลย...\"",
  ui_story_5033_50331501_65_dialog_content = "เพียงพอ!! ไม่ต้องฟังเรื่องไร้สาระไร้สาระนี้แล้ว!!",
  ui_story_5033_50331501_66_dialog_content = "หากคุณยังไม่ยอมรับ งั้นเรามาแจ้งเรื่องของเรากับชาโดว์ลอร์ดกันเถอะ!",
  ui_story_5033_50331501_67_dialog_content = "มาดูกันว่าคู่วายร้ายของคุณมีข้อแก้ตัวอะไรในตอนนั้น!",
  ui_story_5033_50331501_68_dialog_content = "ฉันไม่มีเวลาที่จะตามใจเรื่องไร้สาระของคุณ! อย่าเพิ่งยืนตรงนั้น จับเนโกะยาชิกิและผู้ทรยศคนอื่นๆ!",
  ui_story_5033_50331501_69_dialog_content = "ชิ...",
  ui_story_5033_50331501_70_dialog_content = "ได้ยินที่ฉันพูดไหม!",
  ui_story_5033_50331501_71_dialog_content = "ที่คุณกำลังพูดเป็นความจริง เนโกะยาชิกิ?",
  ui_story_5033_50331501_72_dialog_content = "อาจจะดีกว่ารอดู อย่าด่วนสรุป... เรื่องเหลวไหลเกินไป...",
  ui_story_5033_50331501_73_dialog_content = "ดูท่าทางน่าสะอิดสะเอียนของกุสตาฟอย่างรวดเร็ว...",
  ui_story_5033_50331501_74_dialog_content = "ความหมายของสิ่งนี้คืออะไร...",
  ui_story_5033_50331501_75_dialog_content = "เจ้าพวกไร้ประโยชน์มากมายที่ไร้ประโยชน์! ลืมไปแล้วรึเปล่าว่าใครเป็นเจ้านาย?!",
  ui_story_5033_50331501_76_dialog_content = "ลืมความเสียหายที่ Umbraton สร้างขึ้นในสถานที่นี้หรือไม่!",
  ui_story_5033_50331501_77_dialog_content = "ผู้ชายคนนี้กำลังพูดอะไร? ไม่มีทางที่เขาเป็นเจ้านายของเรา!",
  ui_story_5033_50331501_78_dialog_content = "เฮ้ย กุสตาฟ! คุณควรให้คำอธิบายที่ดีกับเรา! เกิดอะไรขึ้น?",
  ui_story_5033_50331501_79_dialog_content = "และลูกสมุนตัวน้อยของคุณทั้งหมดด้วย คุณอยู่ด้วยกันไหม",
  ui_story_5033_50331501_80_dialog_content = "ไม่ไม่! ไม่ใช่เรื่องของฉัน... ฉันไม่เกี่ยวอะไรกับเขา!",
  ui_story_5033_50331501_81_dialog_content = "ฮิฮิ...ฮ่าฮ่าฮ่า!",
  ui_story_5033_50331501_82_dialog_content = "ดีมาก. คุณได้นำสิ่งนี้มาสู่ตัวคุณเอง",
  ui_story_5033_50331501_83_dialog_content = "คุณบังคับให้ฉันทำเช่นนี้!",
  ui_story_5033_50331501_84_dialog_content = "<color=#e8d9bb>เสียงดัง... เสียงกริ๊ก...</color>",
  ui_story_5033_50331501_85_dialog_content = "ฮะ? นั่นคือ Darkflow...?",
  ui_story_5033_50331501_86_dialog_content = "<anim type=Shake><size=45>กร๊าก!</size></anim>",
  ui_story_5033_50331501_87_dialog_content = "ไม่นะ! สุริยุปราคา!",
  ui_story_5033_50331501_88_dialog_content = "ไป! วิ่งอาละวาดตามใจชอบ... โทรหาเพื่อนและก่อกวน!",
  ui_story_5033_50331501_89_dialog_content = "<anim type=Shake><size=45>Graaagh—!</size></anim>",
  ui_story_5033_50331501_90_dialog_content = "สุริยุปราคา! สุริยุปราคาทุกที่!",
  ui_story_5033_50331501_91_dialog_content = "คำสาป! พวกเขาจัดการเพื่อล้อมรอบเราได้อย่างไร? ไม่มีทางรอด!",
  ui_story_5033_50331501_92_dialog_content = "คุณ... คนเลว! คุณปล่อยให้สุริยุปราคาออกมา? พวกเขาจะดึงดูดมากขึ้น!",
  ui_story_5033_50331501_93_dialog_content = "ด-อย่าเข้ามาใกล้กว่านี้! อร๊ายยย!!",
  ui_story_5033_50331501_94_dialog_content = "กุสตาฟ! บันทึกเรา!",
  ui_story_5033_50331501_95_dialog_content = "ขอโทษอย่างแรงนะทุกคน ปล่อยให้ยูโฟเรีย...",
  ui_story_5033_50331501_96_dialog_content = "ได้รับการทำความสะอาด",
  ui_story_5033_50331502_1_dialog_content = "อ๊าก! ช่วย! ช่วยฉัน!!",
  ui_story_5033_50331502_2_dialog_content = "ขาของฉัน! ฉันขยับไม่ได้!",
  ui_story_5033_50331502_3_dialog_content = "หยุดตะโกน เป็นแค่บาดแผลทางเนื้อ",
  ui_story_5033_50331502_4_dialog_content = "ไม่มี Eclipsites อยู่ที่นี่ แค่ไปหาเพื่อนของคุณ",
  ui_story_5033_50331502_5_dialog_content = "โอเค โอเค... ขอบคุณ...",
  ui_story_5033_50331502_6_dialog_content = "ถ้าคุณต้องการขอบคุณใคร ขอบคุณ Pollux คุณเกือบจะเผาโบสถ์ทิ้งแล้ว แต่เธอก็ยังเต็มใจที่จะลงมือเพื่อช่วยเหลือคุณ",
  ui_story_5033_50331502_7_dialog_content = "คอแร็กซ์! ซ้ายมือ!",
  ui_story_5033_50331502_8_dialog_content = "เวร! พวกมันมาได้ยังไง!",
  ui_story_5033_50331502_9_dialog_content = "ฉันไม่รู้. บางที Eclipsites ในท้องถิ่นก็ถูกดึงดูดเช่นกัน?",
  ui_story_5033_50331502_10_dialog_content = "Antares เป็นยังไง? คุณเคยเห็นเธอไหม?",
  ui_story_5033_50331502_11_dialog_content = "ให้ฉันตามหาเธอด้วยพลังจิตของฉัน! ที่นี่วุ่นวายไปหมด!",
  ui_story_5033_50331502_12_dialog_content = "เฮ้! คุณเคยเห็นพอลลักซ์ไหม?",
  ui_story_5033_50331502_13_dialog_content = "ไม่... เรากำลังมองหา...",
  ui_story_5033_50331502_14_dialog_content = "ฉันเพิ่งเห็นเธอที่อีกด้านหนึ่งของโบสถ์! ตรงนั้น!",
  ui_story_5033_50331502_15_dialog_content = "แล้วกุสตาฟล่ะ? เขาคงหนีไม่พ้นใช่ไหม",
  ui_story_5033_50331502_16_dialog_content = "เฮ้ กุสตาฟ! รอก่อน!",
  ui_story_5033_50331502_17_dialog_content = "เคลื่อนไหว! หลีกทางให้ฉัน...",
  ui_story_5033_50331502_18_dialog_content = "<anim type=Shake><size=45>Graaaugh...!</size></anim>",
  ui_story_5033_50331502_19_dialog_content = "อัก!",
  ui_story_5033_50331502_20_dialog_content = "แอนทาเรส",
  ui_story_5033_50331502_21_dialog_content = "คุณปล่อยสุริยุปราคาพวกนี้ออกไปแล้วเหรอ กุสตาฟ?",
  ui_story_5033_50331502_22_dialog_content = "คุณต้องการให้ทุกคนตายกับคุณหรือไม่?",
  ui_story_5033_50331502_23_dialog_content = "คุณกำลังบอกฉันว่าคุณสงสารคนเหล่านี้?",
  ui_story_5033_50331502_24_dialog_content = "สงสาร? ขอโทษด้วย แต่ฉันไม่สนใจชีวิตพวกเขาน้อยลง",
  ui_story_5033_50331502_25_dialog_content = "คุณช่างไร้ความปราณีจริงๆ แอนทาเรส และคู่ควรกับการเป็นหนึ่งในราศีเมถุนอย่างแท้จริง...",
  ui_story_5033_50331502_26_dialog_content = "แต่ตอนนี้ฉันรู้สึกงุนงงเป็นพิเศษกับการกระทำของคุณ",
  ui_story_5033_50331502_27_dialog_content = "คุณยังคงหวังในการไถ่ถอนจริงหรือ?",
  ui_story_5033_50331502_28_dialog_content = "คุณไม่สามารถคิดว่าคุณสามารถได้รับการอภัยสำหรับการตั้งชื่อฉันในที่สาธารณะและเทศนาในสิ่งที่คุณเรียกว่าความยุติธรรม?",
  ui_story_5033_50331502_29_dialog_content = "... ไม่นะ. แน่นอนไม่",
  ui_story_5033_50331502_30_dialog_content = "คุณจะต้องจ่ายสำหรับสิ่งนี้! และคุณคนเดียว!",
  ui_story_5033_50331502_31_dialog_content = "ทุกสิ่งที่ฉันทำเพื่อ Euphoria... คุณไม่เข้าใจ ไม่เข้าใจ!",
  ui_story_5033_50331502_32_dialog_content = "สิ่งที่คุณมีคือมิตรภาพและความผูกพันที่น่าเบื่อและไร้สาระ! คุณไม่สามารถเห็นสิ่งที่ฉันเห็น!",
  ui_story_5033_50331502_33_dialog_content = "ความอิ่มอกอิ่มใจเป็นเรื่องยุ่งเหยิงมาสิบสองปีแล้ว Antares!",
  ui_story_5033_50331502_34_dialog_content = "พวก Umbraton เหล่านั้นไม่สนใจว่าเราจะอยู่หรือตาย ในขณะที่ชาวบ้านไม่มีแม้แต่ความกล้าหาญหรือความแข็งแกร่งที่จะสร้างใหม่!",
  ui_story_5033_50331502_35_dialog_content = "มีเพียงฉันเท่านั้น! รู้ไหม ฉันเป็นคนเดียวที่ก้าวขึ้นมาได้!",
  ui_story_5033_50331502_36_dialog_content = "การจะฟื้นฟูแขนขาที่เป็นโรคนั้น เราต้องผ่าเอาเนื้อที่เน่าเสียและคัดตัวหนอนออก...",
  ui_story_5033_50331502_37_dialog_content = "และคุณ Antares เป็นมีดผ่าตัดของฉัน เครื่องมือที่ยอดเยี่ยมสำหรับ exc...",
  ui_story_5033_50331502_38_dialog_content = "หลังจากวันนี้ Euphoria สามารถเกิดใหม่ได้เช่นกัน",
  ui_story_5033_50331502_39_dialog_content = "เพียงแต่เราทั้งสองมองไม่เห็น",
  ui_story_5033_50331502_40_dialog_content = "...",
  ui_story_5033_50331502_41_dialog_content = "<color=#e8d9bb>เสียงกริ๊ก—</color>",
  ui_story_5033_50331502_42_dialog_content = "วางอาวุธลง กุสตาฟ สิ่งที่คุณไม่มีโอกาส",
  ui_story_5033_50331502_43_dialog_content = "ในที่สุดคุณก็มาถึงแล้ว พอลลักซ์ นี่คือ... การพัฒนาที่โชคดีอย่างแท้จริง",
  ui_story_5033_50331502_44_dialog_content = "ถึงเวลาที่คุณจะต้องออกจากโบสถ์เล็กๆ อันอบอุ่นสบาย สู่ถนนที่เต็มไปด้วยซากศพ",
  ui_story_5033_50331502_45_dialog_content = "แกต้องการอะไรกันแน่?",
  ui_story_5033_50331502_46_dialog_content = "ฮะฮะฮะ...",
  ui_story_5033_50331502_47_dialog_content = "อย่าขายสถานที่นี้ออกไป พอลลักซ์ อย่าขายมันออกไป",
  ui_story_5033_50331502_48_dialog_content = "ถ้าอยากได้จริงๆ...",
  ui_story_5033_50331502_49_dialog_content = "อย่างน้อยก็ได้ราคาที่ดี",
  ui_story_5033_50331502_50_dialog_content = "คุณกำลังวางแผนอะไร กุสตาฟ!",
  ui_story_5033_50331502_51_dialog_content = "ฉันไม่อยากรบกวนคุณ... ฉันจบเรื่องนี้เองได้!",
  ui_story_5033_50331502_52_dialog_content = "ฉันจะไม่ตายด้วยความอัปยศเหมือนบอส...ไม่เคย...",
  ui_story_5033_50331502_53_dialog_content = "อัก!",
  ui_story_5033_50331502_54_dialog_content = "เขาฆ่าตัวตาย",
  ui_story_5033_50331502_55_dialog_content = "ฉันมีแผนอื่นสำหรับเขา เขาออกไปอย่างแผ่วเบา",
  ui_story_5033_50331502_56_dialog_content = "เก็บแผนเหล่านั้นไว้ในกระเป๋าของคุณตอนนี้ บันทึกไว้สำหรับ <color=#FFB400>อื่นๆ</color>",
  ui_story_5033_50331502_57_dialog_content = "คนอื่น?",
  ui_story_5033_50331502_58_dialog_content = "พอลลักซ์ คุณเห็นคนข้างล่างนั่นไหม ถือคบเพลิงและถือโมโลตอฟ?",
  ui_story_5033_50331502_59_dialog_content = "ฉันไม่สามารถมองเห็นใบหน้าของพวกเขาได้ชัดเจน สำหรับฉัน พวกเขาทั้งหมดดูเหมือนกัน: น่าเกลียด โง่เขลา และสิ้นหวัง",
  ui_story_5033_50331502_60_dialog_content = "แอน มันจบแล้ว มันเสร็จแล้ว คุณแค่ต้องกลับมาที่ Umbraton และเผชิญหน้ากับชะตากรรมของคุณ แล้ว...",
  ui_story_5033_50331502_61_dialog_content = "สิ่งหนึ่งที่กุสตาฟพูดมีเหตุผล",
  ui_story_5033_50331502_62_dialog_content = "เราทุกคนต่างพากันแช่งในความอิ่มเอิบ เป็นแผลสกปรกที่ไม่มีวันหายดี",
  ui_story_5033_50331502_63_dialog_content = "โดยการขจัดส่วนที่เน่าเสียเหล่านี้ออกเท่านั้นจึงจะสามารถเกิดใหม่ได้จริงๆ",
  ui_story_5033_50331502_64_dialog_content = "คุณจะทำอะไร",
  ui_story_5033_50331502_65_dialog_content = "บรรลุภารกิจของฉันในฐานะยมฑูต",
  ui_story_5033_50331502_66_dialog_content = "ไม่นะ ถ้าอย่างนั้นเรา... ช่วยเราด้วย! วิ่ง!",
  ui_story_5033_50331502_67_dialog_content = "อันทาเรส!",
  ui_story_5033_50331502_68_dialog_content = "ใจนายยังนุ่มเหมือนเดิม พอลลักซ์ นั่นเป็นเหตุผลที่ฉันบอกว่าคุณไม่เปลี่ยนแปลง แม้จะผ่านไปหลายปีแล้วก็ตาม",
  ui_story_5033_50331502_69_dialog_content = "แต่ความเจ็บป่วยร้ายแรงต้องการยาที่มีฤทธิ์แรง",
  ui_story_5033_50331502_70_dialog_content = "<color=#e8d9bb>ฟิ้วว—</color>",
  ui_story_5033_50331502_71_dialog_content = "อะไรที่บินได้เหมาะกับเรา! ปกปิด—!",
  ui_story_5033_50331502_72_dialog_content = "<color=#e8d9bb>กร๊อบ!</color>",
  ui_story_5033_50331502_73_dialog_content = "ผู้หญิงบ้า... คุณจะเกี่ยวข้องกับพลเรือนผู้บริสุทธิ์ได้อย่างไร!",
  ui_story_5033_50331502_74_dialog_content = "คาสต้า! ช่วย! หยุดภิกษุณีนี้ เร็วเข้า!",
  ui_story_5033_50331502_75_dialog_content = "พอลลักซ์! ทำอะไรสักอย่าง!",
  ui_story_5033_50331502_76_dialog_content = "ฉัน...",
  ui_story_5033_50331502_77_dialog_content = "แอน ฉันรู้ว่าคุณกำลังทำอะไร แต่ไม่ใช่นี่... ไม่จำเป็นสำหรับสิ่งนี้",
  ui_story_5033_50331502_78_dialog_content = "เรามีข้อตกลง",
  ui_story_5033_50331502_79_dialog_content = "คุณยังได้ยินหลักฐานที่แข็งกร้าว ที่สุภาพบุรุษเปิดเผยต่อสาธารณชนเมื่อครู่นี้...",
  ui_story_5033_50331502_80_dialog_content = "แม้ว่าฉันจะไม่สนใจทำความสะอาด Euphoria แต่ฉันก็ยังปล่อยให้พยานเหล่านี้มีชีวิตอยู่ไม่ได้",
  ui_story_5033_50331502_81_dialog_content = "หุบปาก แอนน์... หยุดเลย...",
  ui_story_5033_50331502_82_dialog_content = "และฉันจะเริ่มกับคนที่อยู่ใกล้ฉันที่สุด",
  ui_story_5033_50331502_83_dialog_content = "อ๊าก! กลับ! กลับไป!",
  ui_story_5033_50331502_84_dialog_content = "คุณยังเป็นคนเดียวที่หยุดฉันได้",
  ui_story_5033_50331502_85_dialog_content = "เธอพร้อมหรือยัง",
  ui_story_5033_50331502_86_dialog_content = "ต้องทำขนาดนี้เลยเหรอ!",
  ui_story_5033_50331502_87_dialog_content = "<size=30>ฉันจะไม่ปล่อยให้คุณพาฉันไป พอลลักซ์ ฉันต้องการอยู่ในความสบายแม้ว่าจะอยู่ในทางของฉันก็ตาม</size>",
  ui_story_5033_50331502_88_dialog_content = "<size=30>เหลือเพียงฉันเท่านั้นที่จะชดใช้บาปของฉัน</size>",
  ui_story_5033_50331502_89_dialog_content = "...",
  ui_story_5033_50331502_90_dialog_content = "แค่นี้แหละ",
  ui_story_5033_50331502_91_dialog_content = "ฉันไม่มีอุดมการณ์ที่ยิ่งใหญ่ แอนน์",
  ui_story_5033_50331502_92_dialog_content = "นี่เป็นเพียงสำหรับมาทิลด้า",
  ui_story_5033_50331502_93_dialog_content = "แน่นอนว่าสิ่งนี้ก็สำหรับมาทิลด้าเช่นกัน",
  ui_story_5033_50331502_94_dialog_content = "เอาชนะเธอ พอลลักซ์! เพื่อความสบายใจ!",
  ui_story_5033_50331502_95_dialog_content = "เพื่อความสบายใจ! อิ่มอกอิ่มใจ!",
  ui_story_5033_50331502_96_dialog_content = "มาเริ่มกันเลย. ฉันหวังว่าคุณจะยังคงได้รับมัน",
  ui_story_5033_50331502_97_dialog_content = "ไม่ต้องกังวล ฉันจำข้อมูลสำคัญได้ ที่ฉันจะไม่มีวันลืม...",
  ui_story_5033_50331502_98_dialog_content = "ฉันยังมีคำถามสุดท้ายอยู่หนึ่งคำถาม แอนน์",
  ui_story_5033_50331502_99_dialog_content = "เฮ้. ถาม.",
  ui_story_5033_50331502_100_dialog_content = "ถ้าคุณมีโอกาสครั้งที่สอง คุณจะยังทำอย่างนั้นไหม?",
  ui_story_5033_50331502_101_dialog_content = "หมายถึงกุสตาฟ...",
  ui_story_5033_50331502_102_dialog_content = "ไม่ ฉันหมายถึงครั้งนั้นเมื่อ 14 ปีที่แล้ว...",
  ui_story_5033_50331502_103_dialog_content = "ยังจะโดนฉันแทงอีกเหรอ?",
  ui_story_5033_50331502_104_dialog_content = "ใช่. ถ้าฉันมีโอกาสครั้งที่สอง ฉันจะวิ่งไปหาคุณเหมือนเดิม",
  ui_story_5033_50331502_105_dialog_content = "แล้วฉันจะกอดคุณแน่นและบอกลาคุณ",
  ui_story_5033_50331502_106_dialog_content = "เหมือนกับตอนนี้...",
  ui_story_5033_50331502_107_dialog_content = "<color=#e8d9bb>*แทง—*</color>",
  ui_story_5033_50331502_108_dialog_content = "...",
  ui_story_5033_50331502_109_dialog_content = "ดวงตาของคุณเฉียบแหลมกว่าเมื่อก่อนมาก",
  ui_story_5033_50331502_110_dialog_content = "คุณเปลี่ยนไปแล้ว พอลลักซ์ เป็นการดีที่จะเห็น",
  ui_story_5033_50331502_111_dialog_content = "และ... คุณเก็บ... กริชนั่น...",
  ui_story_5033_50331502_112_dialog_content = "ไม่อีกแล้ว. ฉันจะฝังมันหลังจากวันนี้",
  ui_story_5033_50331502_113_dialog_content = "ลาก่อน พอลลักซ์ของฉัน",
  ui_story_5033_50331502_114_dialog_content = "ลาก่อน... Antares เต็มไปด้วยบาป",
  ui_story_5033_50331502_115_dialog_content = "สุดท้ายนี้ฉันก็เป็นเหมือนคุณ",
  ui_story_5033_50331502_116_dialog_content = "โป—",
  ui_story_5033_50331502_117_dialog_content = "?!",
  ui_story_5033_50331502_118_dialog_content = "นี่... Antares และกุสตาฟ?!",
  ui_story_5033_50331502_119_dialog_content = "...",
  ui_story_5033_50331502_120_dialog_content = "พอลลักซ์! คุณสบายดีหรือเปล่า?",
  ui_story_5033_50331502_121_dialog_content = "...",
  ui_story_5033_50331502_122_dialog_content = "Corax คุณช่วยฉันตรวจสอบได้ไหม",
  ui_story_5033_50331502_123_dialog_content = "กุสตาฟตายแล้ว ให้ฉันตรวจสอบแอน...",
  ui_story_5033_50331502_124_dialog_content = "ไม่จำเป็นนี่",
  ui_story_5033_50331502_125_dialog_content = "ว่าไง",
  ui_story_5033_50331502_126_dialog_content = "ไม่จำเป็นหรอกหมอ",
  ui_story_5033_50331502_127_dialog_content = "ภารกิจของคุณ... <color=#FFB400>ล้มเหลว</color>",
  ui_story_5033_50331502_128_dialog_content = "<color=#e8d9bb>ครืน!</color>",
  ui_story_5033_50331601_1_dialog_content = "<color=#e8d9bb>หลายชั่วโมงต่อมา</color>",
  ui_story_5033_50331601_2_dialog_content = "... มันคือกุสตาฟดึงสายจริงๆ",
  ui_story_5033_50331601_3_dialog_content = "ฉันพูดมานานแล้วว่าเขาใช้ทุกคน แต่ไม่มีใครฟัง ฮึ่ม",
  ui_story_5033_50331601_4_dialog_content = "ดูเหมือนว่าภิกษุณีผู้อาฆาตเสียชีวิตแล้ว พอลลักซ์พาตัวเองออกไป",
  ui_story_5033_50331601_5_dialog_content = "ฉันไม่ได้คาดหวังอะไรจากพอลลักซ์เลย... เราโชคดีที่มีเธอ...",
  ui_story_5033_50331601_6_dialog_content = "ฉันได้ยินมาว่าพวกเขาเติบโตมาด้วยกัน ฉันเดาว่ามันเป็นสิ่งที่เธอไม่สามารถมองข้ามได้?",
  ui_story_5033_50331601_7_dialog_content = "ห้ามนินทาลับหลังคน",
  ui_story_5033_50331601_8_dialog_content = "ถ้าคุณไม่มีอะไรทำจริงๆ คุณสามารถช่วยฉันซ่อมแซมกำแพงและหน้าต่างของโบสถ์ได้ เด็กๆ ยังต้องการที่อยู่อาศัย",
  ui_story_5033_50331601_9_dialog_content = "คุณโตพอที่จะรับผิดชอบบางอย่าง",
  ui_story_5033_50331601_10_dialog_content = "ใช่ใช่...",
  ui_story_5033_50331601_11_dialog_content = "เนโกะยาชิกิ ทุกคนกลับมาที่โบสถ์แล้ว",
  ui_story_5033_50331601_12_dialog_content = "ทำได้ดีมาก ลาตัน",
  ui_story_5033_50331601_13_dialog_content = "แล้วพอลลักซ์ล่ะ? พวกเราทุกคนกังวลมาก...",
  ui_story_5033_50331601_14_dialog_content = "เธอ... เธอผูกปมกับคาสตา",
  ui_story_5033_50331601_15_dialog_content = "พวกมันอยู่บนเนินเขาข้างหลังเรา และน่าจะกลับมาเร็วๆ นี้ คุณเข้าไปข้างใน ฝนยังตกอยู่",
  ui_story_5033_50331601_16_dialog_content = "ฝนหยุดตกนานแล้ว เนโกะยาชิกิ",
  ui_story_5033_50331601_17_dialog_content = "\"... เส้นทางที่ยากลำบากของเธอมาถึงจุดสิ้นสุดแล้ว แต่การเดินทางครั้งใหม่กำลังรออยู่\"",
  ui_story_5033_50331601_18_dialog_content = "“นางจะกลับคืนสู่ผืนดินและรวมเข้ากับทะเลสาบ...”",
  ui_story_5033_50331601_19_dialog_content = "\"และสุดท้าย กลับสู่ละอองดาว\"",
  ui_story_5033_50331601_20_dialog_content = "...",
  ui_story_5033_50331601_21_dialog_content = "ท้องฟ้าแจ่มใส พอลลักซ์",
  ui_story_5033_50331601_22_dialog_content = "อ่า สว่างจังเลย แดดแรงขนาดนี้...?",
  ui_story_5033_50331601_23_dialog_content = "เห็นไหมว่าหมอกหายไปด้วย? นี่คือสิ่งที่ Euphoria เป็นเช่นนั้นจริงๆ",
  ui_story_5033_50331601_24_dialog_content = "ขอขอบคุณ, PlayerName, เพื่อถวายให้อ่านคำสรรเสริญของแอน",
  ui_story_5033_50331601_25_dialog_content = "ฉันละอายใจที่ต้องยอมรับว่าฉันไม่สามารถทำเช่นนี้ได้ แม้จะอยู่ในคริสตจักรมาหลายปีแล้วก็ตาม",
  ui_story_5033_50331601_26_dialog_content = "โอ้ บางทีคุณอาจหาวิธีแสดงออกไม่ได้",
  ui_story_5033_50331601_27_dialog_content = "บางทีคำชมเชยธรรมดาที่มอบให้กับคนจำนวนมากทุกวันอาจไม่เหมาะกับ Antares",
  ui_story_5033_50331601_28_dialog_content = "ยังไงก็ขอแสดงความเสียใจด้วยนะครับ",
  ui_story_5033_50331601_29_dialog_content = "ฉันไม่เสียใจ ตรงกันข้าม ฉันรู้สึกโล่งใจมาก",
  ui_story_5033_50331601_30_dialog_content = "เหมือนตื่นจากความฝันที่วุ่นวาย ได้เห็นผู้คนที่คุณจะไม่มีวันได้เจออีก",
  ui_story_5033_50331601_31_dialog_content = "แต่ตอนนี้ฉันตื่นจากฝัน ท้องฟ้าสดใส และฉันต้องเดินไปตามทางของฉันเอง",
  ui_story_5033_50331601_32_dialog_content = "แล้วยังไงต่อ?",
  ui_story_5033_50331601_33_dialog_content = "ฉันคิดว่าฉันจะอยู่ที่นี่สักพัก",
  ui_story_5033_50331601_34_dialog_content = "ไม่ใช่แค่เพราะเด็กๆ ในโบสถ์เท่านั้น แต่ยังเป็นเพราะไม่ค่อยเห็น Euphoria ชัดเจนขนาดนี้ด้วย",
  ui_story_5033_50331601_35_dialog_content = "นี่อาจเป็นสิ่งที่ Antares อยากเห็นเช่นกัน",
  ui_story_5033_50331601_36_dialog_content = "บางที. หรือบางทีเธอต้องการชดใช้บาปของเธอด้วยมือของฉัน",
  ui_story_5033_50331601_37_dialog_content = "เธอเป็นคนที่ยุ่งยากจริงๆ",
  ui_story_5033_50331601_38_dialog_content = "ถ้านางตายไปเมื่อสิบสี่ปีก่อนจริง ๆ และไม่มีใครใช้...",
  ui_story_5033_50331601_39_dialog_content = "หรือถ้าเราไม่ได้ถูกสร้างมาให้ฆ่ากัน และราศีเมถุนก็พูดต่อ...",
  ui_story_5033_50331601_40_dialog_content = "หรือถ้าเราไม่เคยรู้จักกันล่ะ?",
  ui_story_5033_50331601_41_dialog_content = "Antares และ Pollux เป็นเพียงคนแปลกหน้าสองคนที่ดำเนินชีวิต",
  ui_story_5033_50331601_42_dialog_content = "เรื่องราวจะแตกต่างกันหรือไม่?",
  ui_story_5033_50331601_43_dialog_content = "ชะตากรรมใหม่ของ Euphoria จะเป็นอย่างไร?",
  ui_story_5033_50331601_44_dialog_content = "เอาล่ะ พอลลักซ์ ไม่ใช่ว่าคุณจะคิดถึงมาก",
  ui_story_5033_50331601_45_dialog_content = "คุณถูก. ฉันพร้อมที่จะบอกลาอดีต",
  ui_story_5033_50331601_46_dialog_content = "มีดเล่มนั้น และเข็มกลัดดอกไฮเดรนเยีย...",
  ui_story_5033_50331601_47_dialog_content = "ปล่อยให้พวกเขาพักผ่อนอย่างสงบสุขพร้อมกับ Antares",
  ui_story_5033_50331601_48_dialog_content = "นั่นเตือนฉัน เราไม่ได้แสดงความเคารพต่อมาทิลด้าในปีนี้",
  ui_story_5033_50331601_49_dialog_content = "โอ้ถูกต้อง ไปจัดการทุกอย่างแถวนี้ก่อน แล้วค่อยหาเวลาไปอัมบราตันกัน",
  ui_story_5033_50331601_50_dialog_content = "ได้เลย ฉันจะไม่รบกวนคุณอีกต่อไป ลาก่อน พอลลักซ์ คาสต้า",
  ui_story_5033_50331601_51_dialog_content = "คุณลงเรือเหาะ Shuttle Hub ด้วยตัวเองหรือไม่?",
  ui_story_5033_50331601_52_dialog_content = "เมื่อทุกคนวิ่งไปรอบๆ ราวกับไก่หัวขาด ถนนอาจขรุขระกว่านั้นอีก",
  ui_story_5033_50331601_53_dialog_content = "แต่คอแร็กซ์กลับมาที่อัมบราตันคนเดียวอีกครั้ง พูดอะไรบางอย่างเกี่ยวกับการทำรายงาน...",
  ui_story_5033_50331601_54_dialog_content = "เดี๋ยวฉันไปเลือกชุดด้วย",
  ui_story_5033_50331601_55_dialog_content = "ใช่ ให้คาสต้าไปด้วย",
  ui_story_5033_50331601_56_dialog_content = "ฉันยังมี...เรื่องอื่นๆ ที่ต้องดูแล พวกคุณไปข้างหน้า",
  ui_story_5033_50331601_57_dialog_content = "ฉันเชื่อว่าเราจะได้พบกันอีก PlayerName. เพียงแค่รอให้ Euphoria กลายเป็นดินแดนมหัศจรรย์ที่แท้จริง",
  ui_story_5033_50331601_58_dialog_content = "แน่นอน พอลลักซ์ ฉันตั้งตารอวันนั้น",
  ui_story_5033_50331601_59_dialog_content = "<color=#e8d9bb>Umbraton สองวันต่อมา</color>",
  ui_story_5033_50331601_60_dialog_content = "อ่านทั้งหมดที่เกี่ยวกับมัน! อาชญากรในอัมบราตัน สังหารต่อเนื่องระหว่างการจับกุม!",
  ui_story_5033_50331601_61_dialog_content = "สนใจกระดาษไหม คุณคอแรกซ์?",
  ui_story_5033_50331601_62_dialog_content = "คุณรู้จักฉันได้อย่างไร...?",
  ui_story_5033_50331601_63_dialog_content = "ไปจากฉัน ไปต่อ",
  ui_story_5033_50331601_64_dialog_content = "ได้เลย ไม่ต้องใจร้ายขนาดนั้น อ่านทั้งหมดที่เกี่ยวกับมัน!",
  ui_story_5033_50331601_65_dialog_content = "...",
  ui_story_5033_50331601_66_dialog_content = "คุณมาสาย.",
  ui_story_5033_50331601_67_dialog_content = "Casta ไม่ใช่นักบินเรือเหาะที่ดี",
  ui_story_5033_50331601_67X1_dialog_content = "ตามฉันมา",
  ui_story_5033_50331601_68_dialog_content = "<color=#e8d9bb>พรึบ</color>",
  ui_story_5033_50331601_69_dialog_content = "นี่อะไร...?",
  ui_story_5033_50331601_70_dialog_content = "ปิดคดี. Shadowlord ได้ดูไฟล์แล้ว และเรื่องนี้ก็ได้รับการตัดสินอย่างคร่าวๆ ตามที่อธิบายไว้",
  ui_story_5033_50331601_71_dialog_content = "ดี. ขอบคุณ Corax",
  ui_story_5033_50331601_72_dialog_content = "คุณควรจะขอบคุณฉันจริงๆ!",
  ui_story_5033_50331601_73_dialog_content = "เห็นได้ชัดว่าฉันอยู่ที่นั่นในภารกิจ แต่ไม่สามารถนำผู้ต้องสงสัยคนใดคนหนึ่งในสองคนกลับมาได้ ขอโทษด้วย อาชญากรสองคน",
  ui_story_5033_50331601_74_dialog_content = "ฮ่าๆๆ โชคร้ายจริงๆ",
  ui_story_5033_50331601_75_dialog_content = "ฉัน...",
  ui_story_5033_50331601_76_dialog_content = "ปล่อยให้มันสำหรับตอนนี้ เดินต่อไป คุณจะพบเอกสารอื่น",
  ui_story_5033_50331601_77_dialog_content = "เป็นแผนของ Shadowlord ที่จะสร้าง Euphoria ขึ้นมาใหม่พร้อมกับคุณ ดูว่ามีปัญหาอะไรไหม",
  ui_story_5033_50331601_78_dialog_content = "กุสตาฟตายไปแล้ว มันต้องบ้าไปแล้วแน่ๆ",
  ui_story_5033_50331601_79_dialog_content = "มีแก๊ง Umbraton จำนวนมากที่พึ่งพา Euphoria เพื่อหาเลี้ยงชีพ เราจะต้องคิดใหม่",
  ui_story_5033_50331601_80_dialog_content = "ชาโดว์ลอร์ดไม่ต้องการเดินบนเส้นทางเดิมๆ มิฉะนั้น ก็ไม่มีความแตกต่างกับคนชั่วเหล่านั้น คุณเข้าใจ?",
  ui_story_5033_50331601_81_dialog_content = "ฉันเห็นด้วย. นั่นคือสิ่งที่ฉันก็คิดเช่นกัน",
  ui_story_5033_50331601_82_dialog_content = "เนื้อเน่าได้ถูกตัดออกแล้ว ถึงเวลาเริ่มต้นใหม่อีกครั้ง",
  ui_story_5033_50331601_83_dialog_content = "นั่นเป็นการเปรียบเทียบที่ดี ความอิ่มอกอิ่มใจเป็นผู้ป่วยหนักที่ในที่สุดก็เอาชิ้นส่วนที่เป็นเนื้อตายออก...",
  ui_story_5033_50331601_84_dialog_content = "ถึงเวลาสำหรับการรักษาใหม่ที่จะนำไปสู่เนื้อเยื่อที่แข็งแรง",
  ui_story_5033_50331601_85_dialog_content = "ใช่ และการรักษาแบบใหม่คือแผนฟื้นฟูของอัมบราตัน",
  ui_story_5033_50331601_86_dialog_content = "ในที่สุด เด็กเหล่านั้นก็สามารถเติบโตเป็นเนื้อเยื่อที่แข็งแรงของ Euphoria ได้",
  ui_story_5033_50331601_87_dialog_content = "มีอะไรอีกในแผน Corax? นอกจากการปรับโครงสร้างอุตสาหกรรมแล้ว?",
  ui_story_5033_50331601_88_dialog_content = "ชอบสวัสดิการสังคมไหม?",
  ui_story_5033_50331601_89_dialog_content = "คิดถึงสถานเลี้ยงเด็กกำพร้า?",
  ui_story_5033_50331601_90_dialog_content = "ผ่อนคลาย! รู้สึกอิสระที่จะพูดถึงสิ่งที่คุณต้องการ ฉันไม่คิดว่า Shadowlord จะปฏิเสธคำแนะนำเหล่านี้",
  ui_story_5033_50331601_91_dialog_content = "เขาเป็นแฟนตัวยงของการมีลูก... อะแฮ่ม",
  ui_story_5033_50331601_92_dialog_content = "ดูเหมือนว่าฉันมีบางอย่างที่เหมือนกันกับเขา—เราต่างก็มองโลกในแง่ดีในแง่ดี",
  ui_story_5033_50331601_93_dialog_content = "ฉันคิดว่าฉันเข้าใจแล้ว",
  ui_story_5033_50331601_94_dialog_content = "คุณทั้งคู่สามารถเชื่อได้ว่าโลกนี้อยู่เหนือความช่วยเหลือ แต่ก็ยังมีความหวังสำหรับคนรุ่นต่อไป",
  ui_story_5033_50331601_95_dialog_content = "ตาเด็กอย่าโกหก คอแรกซ์ แค่ไปสถานเลี้ยงเด็กกำพร้าหรือโรงเรียน แล้วคุณจะเห็นเอง",
  ui_story_5033_50331601_96_dialog_content = "นี่เป็นที่เดียวที่บริสุทธิ์และดีเหลืออยู่",
  ui_story_5033_50331601_97_dialog_content = "ฉันเชื่อว่าเราต้องพึ่งพาเด็กเหล่านั้นหาก Euphoria กลับมาสดใสอีกครั้ง",
  ui_story_5033_50331601_98_dialog_content = "เช่นเดียวกับที่มาทิลด้าเชื่อในตัวเรา เมื่อหลายปีก่อน",
  ui_story_5033_50331601_99_dialog_content = "...",
  ui_story_5033_50331601_100_dialog_content = "คุยแค่นี้พอ เราจะดูแผนอีกครั้งและติดต่อกลับหาคุณ",
  ui_story_5033_50331601_101_dialog_content = "ถ้าไม่มีอะไรแล้ว ฉันจะไป",
  ui_story_5033_50331601_102_dialog_content = "แล้วเจอกันที่ Shuttle Hub",
  ui_story_5033_50331601_103_dialog_content = "ไม่จำเป็น แต่ขอบคุณ ฉันอยากไปเที่ยวสุสาน",
  ui_story_5033_50331601_104_dialog_content = "เพื่อแสดงความเคารพต่อมาทิลด้า? ฉันคิดว่าฉันก็ต้องการเหมือนกัน โอเคไหม",
  ui_story_5033_50331601_105_dialog_content = "แน่นอน. ขอบคุณ Corax",
  ui_story_5033_50331601_106_dialog_content = "C'mon วันนี้ \"ขอบคุณ\" ทั้งหมดเป็นอย่างไรบ้าง? ฉันไม่คุ้นเคยกับคุณที่เป็นทางการมาก",
  ui_story_5033_50331601_107_dialog_content = "<color=#e8d9bb>ยักษ์ใหญ่ สะพาน</color>",
  ui_story_5033_50331601_108_dialog_content = "ขนาดที่เหมาะสมสำหรับผ้าม่าน อาจเป็นกระโปรงที่มีอีกไม่กี่เมตร",
  ui_story_5033_50331601_109_dialog_content = "*เฮ้อ*",
  ui_story_5033_50331601_110_dialog_content = "โต๊ะทานอาหาร โคมไฟตั้งพื้น พรม... มีความคลาดเคลื่อนสีกับพรมหรือไม่?",
  ui_story_5033_50331601_111_dialog_content = "*เฮ้อ*",
  ui_story_5033_50331601_112_dialog_content = "หิ้ง เช็ค... เขียงการ์ตูนอยู่ไหน? อ่า นี่แหละ",
